static int
test_tg_policy_tune_allowed(const dsd_opts* opts, int call_type_enabled, int encrypted, int data_call) {
    if (!opts || !call_type_enabled || opts->trunk_use_allow_list) {
        return 0;
    }
    if (encrypted && opts->trunk_tune_enc_calls == 0) {
        return 0;
    }
    if (data_call && opts->trunk_tune_data_calls == 0) {
        return 0;
    }
    return 1;
}

/* The scan timing reads the hangtime of the P25 call it follows from the parked target's machine, which the watchdog
   changes under the P25 SM tick guard: count the reads made without it. */
static int g_p25_hangtime_reads = 0;
static int g_p25_hangtime_unguarded_reads = 0;

double
p25_sm_effective_hangtime(const dsd_state* state, double hangtime) {
    (void)state;
    g_p25_hangtime_reads++;
    if (g_p25_tick_guard_depth == 0) {
        g_p25_hangtime_unguarded_reads++;
    }
    return hangtime;
}

void
p25_sm_init_ctx(p25_sm_ctx_t* ctx, const dsd_opts* opts, dsd_state* state) {
    if (!ctx) {
        return;
    }
    DSD_MEMSET(ctx, 0, sizeof(*ctx));
    ctx->initialized = 1;
    ctx->state = (opts && state && opts->trunk_enable == 1 && state->trunk_cc_freq != 0) ? P25_SM_ON_CC : P25_SM_IDLE;
}

int
p25_sm_restart_pending_cc_acquisition(p25_sm_ctx_t* ctx, dsd_opts* opts, dsd_state* state, double tune_start_m,
                                      const char* source) {
    (void)opts;
    (void)source;
    if (!ctx) {
        return 0;
    }
    ctx->state = P25_SM_ON_CC;
    ctx->cc_tune_request_id = 0U;
    ctx->cc_tune_pending = 0;
    ctx->cc_sync_pending = 1;
    ctx->cc_acquisition_origin = P25_SM_CC_ACQUISITION_RETURN;
    ctx->t_cc_sync_m = tune_start_m;
    ctx->t_cc_tune_m = tune_start_m;
    ctx->t_hunt_try_m = 0.0;
    if (state) {
        if (state->p25_cc_eval_freq != 0) {
            state->p25_cc_eval_start_m = ctx->t_cc_tune_m;
        }
        state->last_cc_sync_time_m = tune_start_m;
        state->p25_sm_mode = DSD_P25_SM_MODE_ON_CC;
    }
    return 1;
}

int
p25_sm_await_pending_cc_tune(p25_sm_ctx_t* ctx, dsd_opts* opts, dsd_state* state, uint64_t request_id,
                             const char* source) {
    (void)opts;
    (void)source;
    if (!ctx || request_id == 0U) {
        return 0;
    }
    ctx->state = P25_SM_ON_CC;
    ctx->cc_tune_request_id = request_id;
    ctx->cc_tune_pending = 1;
    ctx->cc_sync_pending = 1;
    ctx->cc_acquisition_origin = P25_SM_CC_ACQUISITION_RETURN;
    ctx->t_cc_tune_m = 0.0;
    if (state) {
        state->p25_cc_eval_start_m = 0.0;
        state->p25_sm_mode = DSD_P25_SM_MODE_ON_CC;
    }
    return 1;
}

int
p25_sm_tick_guard_try_enter(void) {
    g_p25_tick_guard_enter_calls++;
    if (!g_p25_tick_guard_available) {
        return 0;
    }
    g_p25_tick_guard_depth++;
    return 1;
}

/* The rollback's guard: waited for, never refused. */
void
p25_sm_tick_guard_enter(void) {
    g_p25_tick_guard_blocking_enters++;
    g_p25_tick_guard_depth++;
}

void
p25_sm_tick_guard_leave(void) {
    g_p25_tick_guard_leave_calls++;
    if (g_p25_tick_guard_depth > 0) {
        g_p25_tick_guard_depth--;
    }
}

void
dmr_sm_init_ctx(dmr_sm_ctx_t* ctx, const dsd_opts* opts, const dsd_state* state) {
    if (!ctx) {
        return;
    }
    DSD_MEMSET(ctx, 0, sizeof(*ctx));
    ctx->initialized = 1;
    ctx->state = (opts && state && opts->trunk_enable == 1 && state->p25_cc_freq == 0 && state->trunk_cc_freq != 0)
                     ? DMR_SM_ON_CC
                     : DMR_SM_IDLE;
}

void
dmr_sm_begin_cc_acquisition(dmr_sm_ctx_t* ctx, const dsd_opts* opts, const dsd_state* state, long freq_hz,
                            uint64_t request_id) {
    (void)freq_hz;
    (void)request_id;
    dmr_sm_init_ctx(ctx, opts, state);
}

void
dmr_sm_tick_ctx(dmr_sm_ctx_t* ctx, dsd_opts* opts, dsd_state* state) {
    g_dmr_tick_calls++;
    if (!ctx || !g_dmr_tick_release_tuned || ctx->state != DMR_SM_TUNED) {
        return;
    }
    ctx->state = DMR_SM_ON_CC;
    if (opts) {
        opts->trunk_is_tuned = 0;
    }
    if (state) {
        state->trunk_vc_freq[0] = 0;
        state->trunk_vc_freq[1] = 0;
    }
}

/* The abandon-carrier release the coordinator uses on a forced advance (#507). Mirrors what
 * the real SM leaves behind: at rest on the control channel with no voice channel to its name,
 * and no tune of its own. */
void
p25_sm_abandon_carrier(p25_sm_ctx_t* ctx, dsd_opts* opts, dsd_state* state, const char* reason) {
    (void)opts;
    (void)state;
    (void)reason;
    pause_log("abandon");
    if (!ctx) {
        return;
    }
    ctx->state = P25_SM_ON_CC;
    ctx->vc_freq_hz = 0;
    ctx->vc_channel = 0;
    ctx->vc_tg = 0;
    ctx->vc_src = 0;
}

void
dmr_sm_abandon_carrier(dmr_sm_ctx_t* ctx, dsd_opts* opts, dsd_state* state, const char* reason) {
    (void)opts;
    (void)state;
    (void)reason;
    pause_log("abandon");
    if (!ctx) {
        return;
    }
    /* As the real release does (dmr_sm_release_without_cc()): the machine forgets the control-channel request it was
       waiting on, so whoever owed it something has to have taken it first (issue #671). */
    ctx->cc_tune_request_id = 0U;
    ctx->state = DMR_SM_ON_CC;
    ctx->vc_freq_hz = 0;
    ctx->slots[0].voice_active = 0;
    ctx->slots[1].voice_active = 0;
}

/* From engine/trunk_tuning.c, which this fixture does not link: the observable subtraction the
 * coordinator depends on -- the canonical call rows end, the VC mirrors clear, trunk_is_tuned
 * drops, and nothing tunes. Stamped with the real clock exactly like the original. */
void
dsd_engine_release_tuned_call_state(dsd_opts* opts, dsd_state* state) {
    if (!opts || !state) {
        return;
    }
    pause_log("release");
    const double ended_m = dsd_decode_now_mono_s();
    for (int slot = 0; slot < DSD_CALL_STATE_SLOT_COUNT; slot++) {
        if (dsd_call_state_end_ex(state, (uint8_t)slot, ended_m, DSD_CALL_END_EXPLICIT) > 0) {
            g_explicit_call_ends++;
            DSD_SNPRINTF(g_release_seen_target, sizeof g_release_seen_target, "%s", state->trunk_scan_active_id);
        }
    }
    state->p25_vc_freq[0] = 0;
    state->p25_vc_freq[1] = 0;
    state->trunk_vc_freq[0] = 0;
    state->trunk_vc_freq[1] = 0;
    opts->trunk_is_tuned = 0;
}

/* The stub scanner tunes here model no rigctl leg, so none moved the radio (dsd_engine_scan_tune_moved()). */
int
dsd_engine_scan_tune_moved(void) {
    return 0;
}

dsd_trunk_tune_result
dsd_engine_scan_tune_to_freq(dsd_opts* opts, dsd_state* state, long int freq, int ted_sps, uint64_t* out_request_id) {
    if (out_request_id) {
        *out_request_id = 0U;
    }
    g_scan_tune_to_freq_ted_sps = ted_sps;
    if (!opts || !state || freq <= 0) {
        return DSD_TRUNK_TUNE_RESULT_FAILED;
    }
    if (freq == g_scan_tune_watch_hz) {
        g_scan_tune_watch_calls++;
    }
    g_scan_tune_to_freq_analog_only = opts->analog_only;
    g_scan_tune_to_freq_nfm_width_hz = opts->analog_nfm_bandwidth_hz;
    g_scan_tune_to_freq_analog_demod = opts->analog_demod;
    g_scan_tune_to_freq_am_width_hz = opts->analog_am_bandwidth_hz;
    const dsdneoRuntimeConfig* env = dsd_neo_get_config();
    const int lpf_off = env && env->channel_lpf_is_set && env->channel_lpf_enable == 0;
    if (g_scan_tune_refuses_unfit_width && dsd_opts_is_analog_family(opts) && dsd_opts_analog_width_hz(opts) > 0
        && g_scan_dsp_rate_hz > 0
        && (lpf_off
            || dsd_analog_width_check(opts->analog_demod, dsd_opts_analog_width_hz(opts), g_scan_dsp_rate_hz, NULL, 0U)
                   != 0)) {
        g_scan_tune_width_refusals++;
        return DSD_TRUNK_TUNE_RESULT_FAILED;
    }
    if (g_scan_tune_to_freq_failures_remaining > 0) {
        g_scan_tune_to_freq_failures_remaining--;
        return DSD_TRUNK_TUNE_RESULT_FAILED;
    }
    if (g_scan_tune_to_freq_deferrals_remaining > 0) {
        g_scan_tune_to_freq_deferrals_remaining--;
        return DSD_TRUNK_TUNE_RESULT_DEFERRED;
    }
    if (g_scan_tune_to_freq_pending && out_request_id) {
        g_scan_tune_pending_request = dsd_trunk_tuning_request_begin();
        dsd_trunk_tuning_request_mark_ready(g_scan_tune_pending_request);
        *out_request_id = g_scan_tune_pending_request;
        return DSD_TRUNK_TUNE_RESULT_PENDING;
    }
    opts->trunk_is_tuned = 0;
    state->last_cc_sync_time_m = dsd_engine_trunk_scan_active_index(state) == (size_t)-1 ? 0.0 : 1.0;
    if (g_fake_family_tracking) {
        /* The tune lands: the front end now runs the family the target asked for. */
        g_fake_family_analog = opts->analog_only == 1 ? 1 : 0;
    }
    return DSD_TRUNK_TUNE_RESULT_OK;
}

int
csvChanImport(const dsd_opts* opts, dsd_state* state) {
    if (g_csv_import_result != 0) {
        return g_csv_import_result;
    }
    if (!opts || !state || opts->chan_in_file[0] == '\0') {
        return 0;
    }
    FILE* fp = fopen(opts->chan_in_file, "rb");
    if (!fp) {
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof line, fp)) {
        char* comma = strchr(line, ',');
        if (!comma) {
            continue;
        }
        *comma = '\0';
        char* freq_text = comma + 1;
        /* The optional third column the real importer reads as a row name. This stub keeps
         * no scan-list rows, so every name it sees lands in row 0: enough to prove the store
         * was allocated, which is what the trunk-scan import then has to release. */
        char* name_text = strchr(freq_text, ',');
        if (name_text) {
            *name_text++ = '\0';
        }
        /* A fourth column seeds a per-row key set, the way the real importer
         * loads key cells: enough to prove the store was allocated, which is
         * what the trunk-scan import then has to release. */
        char* key_text = NULL;
        if (name_text) {
            key_text = strchr(name_text, ',');
            if (key_text) {
                *key_text++ = '\0';
            }
        }
        char* tail = key_text ? key_text : (name_text ? name_text : freq_text);
        while (*tail && *tail != '\r' && *tail != '\n') {
            tail++;
        }
        *tail = '\0';
        uint32_t channel = 0;
        long freq = 0;
        if (dsd_parse_uint32_strict(line, 10, 0xFFFFU, &channel) == 0
            && dsd_parse_long_strict(freq_text, 10, 0L, LONG_MAX, &freq) == 0) {
            dsd_state_set_trunk_chan_freq(state, channel, freq);
            if (name_text && name_text[0] != '\0') {
                (void)dsd_state_trunk_lcn_name_set(state, 0U, name_text);
            }
            if (key_text && key_text[0] != '\0') {
                dsd_key_set ks;
                DSD_MEMSET(&ks, 0, sizeof(ks));
                ks.entries = (dsd_key_set_entry*)calloc(1U, sizeof(*ks.entries));
                if (ks.entries != NULL) {
                    ks.count = 1U;
                    ks.present = 1;
                    ks.keyloader = 1;
                    ks.entries[0].index = 9U;
                    ks.entries[0].value = 777ULL;
                    ks.entries[0].loaded = 1U;
                    (void)dsd_state_trunk_lcn_keys_set(state, 0U, &ks);
                }
            }
        }
    }
    (void)fclose(fp);
    return g_csv_import_result;
}

/*
 * Per-target key stubs: a readable key file seeds one keyring slot, the way the
 * real importer loads rows, so the coordinator's install/restore is observable.
 * dsd_key_set_load_csv() runs these against its throwaway state and captures.
 */
static int
seed_scan_key_slot(dsd_state* state, const char* path) {
    if (!state || !path || path[0] == '\0') {
        return -1;
    }
    FILE* fp = fopen(path, "rb");
    if (!fp) {
        return -1;
    }
    (void)fclose(fp);
    state->rkey_array[9] = 999ULL;
    state->rkey_array_loaded[9] = 1U;
    return 0;
}

int
csvKeyImportHexPath(const char* path, int show_keys, dsd_state* state, dsd_csv_validation* stats) {
    (void)show_keys;
    (void)stats;
    return seed_scan_key_slot(state, path);
}

int
csvKeyImportDecPath(const char* path, int show_keys, dsd_state* state, dsd_csv_validation* stats) {
    (void)show_keys;
    (void)stats;
    return seed_scan_key_slot(state, path);
}

