static int
write_text_file(const char* path, const char* content) {
    FILE* fp = dsd_fopen_private(path, "wb");
    if (!fp) {
        return -1;
    }
    size_t len = strlen(content);
    int rc = (fwrite(content, 1, len, fp) == len) ? 0 : -1;
    if (fclose(fp) != 0) {
        rc = -1;
    }
    return rc;
}

static int
make_temp_dir(char* dir, size_t dir_sz) {
    return dsd_test_mkdtemp(dir, dir_sz, "dsdneo_trunk_scan") ? 0 : -1;
}

static int
write_targets_file_with_header(const char* dir, const char* header, const char* body, char* out_path, size_t out_sz) {
    if (dsd_test_path_join(out_path, out_sz, dir, "targets.csv") != 0) {
        return -1;
    }
    char content[8192];
    int n = DSD_SNPRINTF(content, sizeof content, "%s%s", header, body);
    if (n < 0 || (size_t)n >= sizeof content) {
        return -1;
    }
    return write_text_file(out_path, content);
}

static int
write_targets_file(const char* dir, const char* body, char* out_path, size_t out_sz) {
    return write_targets_file_with_header(dir, k_header, body, out_path, out_sz);
}

static void
cleanup_paths(const char* dir, const char* targets, const char* chan) {
    if (targets) {
        (void)remove(targets);
    }
    if (chan) {
        (void)remove(chan);
    }
    if (dir) {
        (void)dsd_test_rmdir(dir);
    }
}

static int
append_text(char* dst, size_t dst_sz, const char* src) {
    size_t dst_len = strlen(dst);
    size_t src_len = strlen(src);
    if (dst_len + src_len + 1 > dst_sz) {
        return -1;
    }
    DSD_MEMCPY(dst + dst_len, src, src_len + 1);
    return 0;
}

static int
test_parser_valid_mixed_targets_and_relative_chan_csv(void) {
    char dir[DSD_TEST_PATH_MAX];
    if (make_temp_dir(dir, sizeof dir) != 0) {
        return 1;
    }
    char chan_path[DSD_TEST_PATH_MAX];
    if (dsd_test_path_join(chan_path, sizeof chan_path, dir, "chan.csv") != 0
        || write_text_file(chan_path, "channel,frequency\n1,851012500\n") != 0) {
        cleanup_paths(dir, NULL, NULL);
        return 1;
    }
    char target_path[DSD_TEST_PATH_MAX];
    if (write_targets_file(dir,
                           "p25,p25-trunk,851000000,chan.csv,,,primary\n"
                           "dmr,dmr-trunk,452000000,,500,1500,tier iii\n"
                           "conv,dmr-conventional,461000000,,750,,simplex\n",
                           target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, NULL, chan_path);
        return 1;
    }

    static dsd_opts opts;
    DSD_MEMSET(&opts, 0, sizeof opts);
    opts.trunk_scan_idle_dwell_ms = 3000;
    opts.trunk_scan_activity_hold_ms = 1200;
    dsd_trunk_scan_target_list list;
    DSD_MEMSET(&list, 0, sizeof list);
    char err[256] = {0};
    int rc = dsd_trunk_scan_load_targets_csv(target_path, &opts, &list, err, sizeof err);

    int test_rc = 0;
    if (rc != 0 || list.count != 3) {
        DSD_FPRINTF(stderr, "parser valid mixed rc=%d count=%zu err=%s\n", rc, list.count, err);
        test_rc = 1;
    }
    if (test_rc == 0) {
        if (list.targets[0].type != DSD_TRUNK_SCAN_TARGET_P25_TRUNK || list.targets[0].frequency_hz != 851000000U
            || list.targets[0].dwell_ms != 3000 || list.targets[0].activity_hold_ms != 1200
            || !strstr(list.targets[0].chan_csv, "chan.csv")) {
            DSD_FPRINTF(stderr, "parser target 0 mismatch\n");
            test_rc = 1;
        }
        /* The id is what the coordinator publishes as the channel label, so the parser
         * owes it verbatim rather than just "some non-empty string". */
        if (strcmp(list.targets[0].id, "p25") != 0 || strcmp(list.targets[1].id, "dmr") != 0
            || strcmp(list.targets[2].id, "conv") != 0) {
            DSD_FPRINTF(stderr, "parser target ids mismatch: '%s' '%s' '%s'\n", list.targets[0].id, list.targets[1].id,
                        list.targets[2].id);
            test_rc = 1;
        }
        if (list.targets[1].dwell_ms != 500 || list.targets[1].activity_hold_ms != 1500) {
            DSD_FPRINTF(stderr, "parser per-target dwell/hold mismatch\n");
            test_rc = 1;
        }
    }

    dsd_trunk_scan_target_list_reset(&list);
    cleanup_paths(dir, target_path, chan_path);
    return test_rc;
}

/* A spreadsheet's "CSV UTF-8" export starts the file with a UTF-8 byte order mark. The header after it is read as it
 * would be without one: the file loads the same targets, its optional columns found by name. */
static int
test_parser_skips_a_utf8_bom_before_the_header(void) {
    char dir[DSD_TEST_PATH_MAX];
    if (make_temp_dir(dir, sizeof dir) != 0) {
        return 1;
    }
    char target_path[DSD_TEST_PATH_MAX];
    static const char header[] = "\xEF\xBB\xBF"
                                 "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,label\n";
    if (write_targets_file_with_header(dir, header,
                                       "p25,p25-trunk,851000000,,500,,primary,County\n"
                                       "conv,dmr-conventional,461000000,,750,1500,simplex,Tower\n",
                                       target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, NULL, NULL);
        return 1;
    }
    static dsd_opts opts;
    DSD_MEMSET(&opts, 0, sizeof opts);
    dsd_trunk_scan_target_list list;
    DSD_MEMSET(&list, 0, sizeof list);
    char err[256] = {0};
    const int rc = dsd_trunk_scan_load_targets_csv(target_path, &opts, &list, err, sizeof err);
    int test_rc = 0;
    if (rc != 0 || list.count != 2) {
        DSD_FPRINTF(stderr, "BOM header rc=%d count=%zu err=%s\n", rc, list.count, err);
        test_rc = 1;
    } else if (strcmp(list.targets[0].id, "p25") != 0 || list.targets[0].type != DSD_TRUNK_SCAN_TARGET_P25_TRUNK
               || list.targets[0].frequency_hz != 851000000U || list.targets[0].dwell_ms != 500
               || strcmp(list.targets[0].label, "County") != 0 || strcmp(list.targets[1].id, "conv") != 0
               || list.targets[1].activity_hold_ms != 1500 || strcmp(list.targets[1].label, "Tower") != 0) {
        DSD_FPRINTF(stderr, "BOM header targets differ: '%s' %u '%s', '%s' '%s'\n", list.targets[0].id,
                    list.targets[0].frequency_hz, list.targets[0].label, list.targets[1].id, list.targets[1].label);
        test_rc = 1;
    }
    dsd_trunk_scan_target_list_reset(&list);
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* A header line longer than the reader's line buffer is refused, as a data row that long is, rather than read as the
 * part that fits: the rest of the line would then be read as the first data row. Here that rest is a valid target. */
static int
test_parser_refuses_an_over_long_header(void) {
    char dir[DSD_TEST_PATH_MAX];
    if (make_temp_dir(dir, sizeof dir) != 0) {
        return 1;
    }
    /* The required columns, then one unknown column name that fills the 4096-byte line buffer, so the remainder of
     * the physical header line is exactly a target row. */
    static const char required[] = "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,";
    static const char remainder[] = "a,dmr-conventional,461000000,,250,,\n";
    static char content[8192];
    size_t used = sizeof required - 1U;
    DSD_MEMCPY(content, required, used);
    DSD_MEMSET(content + used, 'x', 4095U - used);
    used = 4095U;
    DSD_SNPRINTF(content + used, sizeof content - used, "%s%s", remainder, "b,dmr-conventional,462000000,,250,,\n");
    char target_path[DSD_TEST_PATH_MAX];
    if (dsd_test_path_join(target_path, sizeof target_path, dir, "targets.csv") != 0
        || write_text_file(target_path, content) != 0) {
        cleanup_paths(dir, NULL, NULL);
        return 1;
    }
    static dsd_opts opts;
    DSD_MEMSET(&opts, 0, sizeof opts);
    dsd_trunk_scan_target_list list;
    DSD_MEMSET(&list, 0, sizeof list);
    char err[256] = {0};
    const int rc = dsd_trunk_scan_load_targets_csv(target_path, &opts, &list, err, sizeof err);
    int test_rc = 0;
    if (rc == 0 || list.count != 0 || strcmp(err, "row 1 is too long") != 0) {
        DSD_FPRINTF(stderr, "over-long header rc=%d count=%zu err='%s'\n", rc, list.count, err);
        test_rc = 1;
    }
    dsd_trunk_scan_target_list_reset(&list);
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #782: the `label` column as a spreadsheet saves it. A cell wrapped in quotes with every quote inside doubled
 * reads each doubled quote as one, as the options cell does; a cell whose quotes are not all doubled keeps them; a
 * plain cell is read as it is, and padding and control characters are dropped. */
static int
test_parser_reads_spreadsheet_quoted_labels(void) {
    char dir[DSD_TEST_PATH_MAX];
    if (make_temp_dir(dir, sizeof dir) != 0) {
        return 1;
    }
    char target_path[DSD_TEST_PATH_MAX];
    static const char header[] = "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,label\n";
    if (write_targets_file_with_header(dir, header,
                                       "a,dmr-conventional,451000000,,,,,\"Tower \"\"A\"\", east\"\n"
                                       "b,dmr-conventional,452000000,,,,,\"Bob\"s yard\"\n"
                                       "c,dmr-conventional,453000000,,,,, County Fire \n"
                                       "d,dmr-conventional,454000000,,,,,\n",
                                       target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, NULL, NULL);
        return 1;
    }
    static dsd_opts opts;
    DSD_MEMSET(&opts, 0, sizeof opts);
    dsd_trunk_scan_target_list list;
    DSD_MEMSET(&list, 0, sizeof list);
    char err[256] = {0};
    int test_rc = 0;
    if (dsd_trunk_scan_load_targets_csv(target_path, &opts, &list, err, sizeof err) != 0 || list.count != 4) {
        DSD_FPRINTF(stderr, "label parse rc count=%zu err=%s\n", list.count, err);
        test_rc = 1;
    } else {
        static const char* const want[] = {"Tower \"A\", east", "Bob\"s yard", "County Fire", ""};
        for (size_t i = 0; i < 4; i++) {
            if (strcmp(list.targets[i].label, want[i]) != 0) {
                DSD_FPRINTF(stderr, "label %zu '%s', want '%s'\n", i, list.targets[i].label, want[i]);
                test_rc = 1;
            }
        }
    }
    dsd_trunk_scan_target_list_reset(&list);
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

