static int
test_scan_does_not_retune_active_target_while_alternates_cool_down(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_runtime_targets("a,p25-trunk,851000000,,250,,\n"
                             "b,p25-trunk,852000000,,250,,\n",
                             target_path, sizeof target_path, dir, sizeof dir)
        != 0) {
        return 1;
    }

    static dsd_opts opts;
    static dsd_state state;
    reset_scan_opts_state(&opts, &state);
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;

    dsd_trunk_tuning_hooks hooks = {0};
    hooks.tune_to_cc_request = counting_tune_to_cc;
    dsd_trunk_tuning_hooks_set(hooks);
    g_counting_tune_to_cc_calls = 0;
    g_counting_tune_to_cc_failures_remaining = 0;

    char err[256] = {0};
    trunk_scan_test_set_now(0.0);
    int rc = dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err);
    int test_rc = 0;
    if (rc != 0 || dsd_engine_trunk_scan_active_index(&state) != 0 || g_counting_tune_to_cc_calls != 1) {
        DSD_FPRINTF(stderr, "cooldown scan init failed rc=%d active=%zu calls=%d err=%s\n", rc,
                    dsd_engine_trunk_scan_active_index(&state), g_counting_tune_to_cc_calls, err);
        test_rc = 1;
    }

    g_counting_tune_to_cc_failures_remaining = 1;
    trunk_scan_test_set_now(0.26);
    dsd_engine_trunk_scan_tick(&opts, &state);
    int calls_after_failed_alternate = g_counting_tune_to_cc_calls;
    if (dsd_engine_trunk_scan_active_index(&state) != 0 || calls_after_failed_alternate < 2) {
        DSD_FPRINTF(stderr, "failed alternate retune did not leave active target restored active=%zu calls=%d\n",
                    dsd_engine_trunk_scan_active_index(&state), calls_after_failed_alternate);
        test_rc = 1;
    }

    trunk_scan_test_set_now(0.52);
    dsd_engine_trunk_scan_tick(&opts, &state);
    if (dsd_engine_trunk_scan_active_index(&state) != 0
        || g_counting_tune_to_cc_calls != calls_after_failed_alternate) {
        DSD_FPRINTF(stderr, "active target retuned while alternate cooling active=%zu calls=%d was=%d\n",
                    dsd_engine_trunk_scan_active_index(&state), g_counting_tune_to_cc_calls,
                    calls_after_failed_alternate);
        test_rc = 1;
    }

    DSD_MEMSET(&hooks, 0, sizeof hooks);
    dsd_trunk_tuning_hooks_set(hooks);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/*
 * trunk_scan_advance() puts the original target back when every candidate retune fails, and
 * the last thing tried was an alternate: publishing only from the switch would leave that
 * alternate's id on screen while the receiver sits on the target it never left. Two failures
 * at init drive exactly that -- target "a" fails and starts cooling, the advance tries "b"
 * and it fails too, and "a" is then skipped by its own cooldown, so the restore is the only
 * thing that can put "a" back.
 */
static int
test_failed_alternate_retune_republishes_restored_target(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_runtime_targets("a,p25-trunk,851000000,,250,,\n"
                             "b,p25-trunk,852000000,,250,,\n",
                             target_path, sizeof target_path, dir, sizeof dir)
        != 0) {
        return 1;
    }

    static dsd_opts opts;
    static dsd_state state;
    reset_scan_opts_state(&opts, &state);
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;

    dsd_trunk_tuning_hooks hooks = {0};
    hooks.tune_to_cc_request = counting_tune_to_cc;
    dsd_trunk_tuning_hooks_set(hooks);
    g_counting_tune_to_cc_calls = 0;
    g_counting_tune_to_cc_failures_remaining = 2;

    char err[256] = {0};
    trunk_scan_test_set_now(0.0);
    int test_rc = 0;
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0) {
        DSD_FPRINTF(stderr, "failed alternate scan init failed err=%s\n", err);
        test_rc = 1;
    }
    if (dsd_engine_trunk_scan_active_index(&state) != 0 || g_counting_tune_to_cc_calls != 2) {
        DSD_FPRINTF(stderr, "failed alternate did not restore target 0: active=%zu calls=%d\n",
                    dsd_engine_trunk_scan_active_index(&state), g_counting_tune_to_cc_calls);
        test_rc = 1;
    }
    test_rc |= expect_published_target(&state, "failed alternate retune", "a", 1U, 2U);

    DSD_MEMSET(&hooks, 0, sizeof hooks);
    dsd_trunk_tuning_hooks_set(hooks);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* The received identity (dsd_state::rx_id) is the carrier's: every target switch forgets it, and a revisited target's
 * saved state never brings it back (what a target left is last known, not received on this visit). A switch whose
 * retunes all fail leaves the receiver on the carrier it never left, so the record comes back as it was. */
static int
test_target_switch_forgets_the_received_identity(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_runtime_targets("a,p25-trunk,851000000,,250,,\n"
                             "b,p25-trunk,852000000,,250,,\n",
                             target_path, sizeof target_path, dir, sizeof dir)
        != 0) {
        return 1;
    }

    static dsd_opts opts;
    static dsd_state state;
    reset_scan_opts_state(&opts, &state);
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;

    dsd_trunk_tuning_hooks hooks = {0};
    hooks.tune_to_cc_request = counting_tune_to_cc;
    dsd_trunk_tuning_hooks_set(hooks);
    g_counting_tune_to_cc_calls = 0;
    g_counting_tune_to_cc_failures_remaining = 0;

    char err[256] = {0};
    trunk_scan_test_set_now(0.0);
    int test_rc = 0;
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0
        || dsd_engine_trunk_scan_active_index(&state) != 0) {
        DSD_FPRINTF(stderr, "rx-id scan init failed err=%s\n", err);
        test_rc = 1;
    }
    dsd_rxid_note_p25_network(&state, 0xBEE00U, 0x1A3U);
    state.symbol_clock = 7000U;
    trunk_scan_test_set_now(0.26);
    dsd_engine_trunk_scan_tick(&opts, &state);
    if (dsd_engine_trunk_scan_active_index(&state) != 1 || state.rx_id.valid != 0U) {
        DSD_FPRINTF(stderr, "rx-id: the switch to b kept the record: active=%zu valid=%08X\n",
                    dsd_engine_trunk_scan_active_index(&state), (unsigned)state.rx_id.valid);
        test_rc = 1;
    }
    /* What the frame sync and the decoders hold buffered from a is no frame of b's. */
    if (state.carrier_change_seen != 1U || state.carrier_change_symbol_clock != 7000U) {
        DSD_FPRINTF(stderr, "rx-id: the switch to b left no carrier change mark\n");
        test_rc = 1;
    }
    dsd_rxid_note_p25_network(&state, 0xBEE01U, 0x2B4U);
    trunk_scan_test_set_now(0.52);
    dsd_engine_trunk_scan_tick(&opts, &state);
    if (dsd_engine_trunk_scan_active_index(&state) != 0 || state.rx_id.valid != 0U) {
        DSD_FPRINTF(stderr, "rx-id: the revisit of a restored a record: active=%zu valid=%08X\n",
                    dsd_engine_trunk_scan_active_index(&state), (unsigned)state.rx_id.valid);
        test_rc = 1;
    }

    /* Both retunes of the next advance fail: the receiver stays on a, with the record a's visit received, and with
       the Phase 2 proofs a's carrier made (issue #802): the switch attempt forgot them, and the rollback puts them back
       with the rest of a's saved state. */
    dsd_rxid_note_p25_network(&state, 0xBEE00U, 0x1A3U);
    state.p2_cc = 0x293ULL;
    state.p2_cc_verified = 1U;
    state.p2_proven_nac = 0x293;
    const dsd_received_identity before = state.rx_id;
    g_counting_tune_to_cc_failures_remaining = 2;
    trunk_scan_test_set_now(0.78);
    dsd_engine_trunk_scan_tick(&opts, &state);
    if (dsd_engine_trunk_scan_active_index(&state) != 0 || g_counting_tune_to_cc_failures_remaining != 0
        || state.rx_id.epoch != before.epoch || state.rx_id.family != before.family || state.rx_id.valid != before.valid
        || state.rx_id.p25_wacn != before.p25_wacn || state.rx_id.p25_sysid != before.p25_sysid) {
        DSD_FPRINTF(stderr, "rx-id: a rolled-back switch did not restore the record: active=%zu valid=%08X\n",
                    dsd_engine_trunk_scan_active_index(&state), (unsigned)state.rx_id.valid);
        test_rc = 1;
    }
    if (state.p2_cc_verified != 1U || state.p2_proven_nac != 0x293) {
        DSD_FPRINTF(stderr, "rx-id: a rolled-back switch did not restore the Phase 2 proofs: verified=%u proven=%d\n",
                    (unsigned)state.p2_cc_verified, state.p2_proven_nac);
        test_rc = 1;
    }

    DSD_MEMSET(&hooks, 0, sizeof hooks);
    dsd_trunk_tuning_hooks_set(hooks);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #799: a row keeps the site its call was heard on and the numbering of its channel. A target's staged row rides
 * its snapshot whole, so a revisit brings back its own site and channel kind, a fresh target's row holds none, and a
 * rolled-back switch leaves the row as it was; the committed rows, in the one ring, keep theirs through all of it. */
static int expect_active_target(const dsd_state* state, const char* stage, size_t want);

static int
expect_row_site_bytes(const char* stage, const Event_History* row, const dsd_received_identity* site, uint8_t kind) {
    if (memcmp(&row->site_id, site, sizeof(*site)) != 0 || row->call_channel_kind != kind) {
        DSD_FPRINTF(stderr, "row site after %s: family %u valid %08X kind %u, want family %u valid %08X kind %u\n",
                    stage, (unsigned)row->site_id.family, (unsigned)row->site_id.valid,
                    (unsigned)row->call_channel_kind, (unsigned)site->family, (unsigned)site->valid, (unsigned)kind);
        return 1;
    }
    return 0;
}

static int
test_target_switch_keeps_each_rows_site(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_runtime_targets("a,p25-trunk,851000000,,250,,\n"
                             "b,p25-trunk,852000000,,250,,\n",
                             target_path, sizeof target_path, dir, sizeof dir)
        != 0) {
        return 1;
    }

    static dsd_opts opts;
    static dsd_state state;
    static Event_History_I event_history[DSD_CALL_STATE_SLOT_COUNT];
    reset_scan_opts_state(&opts, &state);
    DSD_MEMSET(event_history, 0, sizeof(event_history));
    state.event_history_s = event_history;
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;
    g_counting_tune_to_cc_calls = 0;
    g_counting_tune_to_cc_failures_remaining = 0;

    char err[256] = {0};
    trunk_scan_test_set_now(0.0);
    int test_rc = 0;
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0) {
        DSD_FPRINTF(stderr, "row site scan init failed: %s\n", err);
        test_rc = 1;
        goto cleanup;
    }

    dsd_received_identity none;
    dsd_received_identity site_a;
    dsd_received_identity site_b;
    dsd_received_identity site_committed;
    DSD_MEMSET(&none, 0, sizeof none);
    dsd_rxid_note_p25_network(&state, 0x12345U, 0x111U);
    dsd_rxid_site_snapshot(&state.rx_id, &site_committed);
    dsd_rxid_reset(&state);
    dsd_rxid_note_p25_network(&state, 0xBEE00U, 0x1A3U);
    dsd_rxid_note_p25_site(&state, 0x1A3U, 3U, 21U);
    dsd_rxid_site_snapshot(&state.rx_id, &site_a);

    Event_History* current = &event_history[0].Event_History_Items[0];
    Event_History* committed = &event_history[0].Event_History_Items[1];
    DSD_MEMCPY(&committed->site_id, &site_committed, sizeof site_committed);
    committed->channel = 7U;
    committed->call_channel_kind = (uint8_t)DSD_CALL_CHANNEL_LCN;
    DSD_MEMCPY(&current->site_id, &site_a, sizeof site_a);
    current->channel = 5U;
    current->call_channel_kind = (uint8_t)DSD_CALL_CHANNEL_LSN;

    trunk_scan_test_set_now(0.26);
    dsd_engine_trunk_scan_tick(&opts, &state);
    test_rc |= expect_active_target(&state, "row site switch to b", 1U);
    test_rc |= expect_row_site_bytes("the switch to a fresh target", current, &none, DSD_CALL_CHANNEL_NONE);
    test_rc |= expect_row_site_bytes("the switch, committed row", committed, &site_committed, DSD_CALL_CHANNEL_LCN);

    dsd_rxid_note_p25_network(&state, 0xBEE01U, 0x2B4U);
    dsd_rxid_site_snapshot(&state.rx_id, &site_b);
    DSD_MEMCPY(&current->site_id, &site_b, sizeof site_b);
    current->channel = 3U;
    current->call_channel_kind = (uint8_t)DSD_CALL_CHANNEL_LPCN;
    trunk_scan_test_set_now(0.52);
    dsd_engine_trunk_scan_tick(&opts, &state);
    test_rc |= expect_active_target(&state, "row site revisit of a", 0U);
    test_rc |= expect_row_site_bytes("the revisit of a", current, &site_a, DSD_CALL_CHANNEL_LSN);
    test_rc |= expect_row_site_bytes("the revisit, committed row", committed, &site_committed, DSD_CALL_CHANNEL_LCN);

    /* b's saved row comes back with its own site, and a's again after it. */
    trunk_scan_test_set_now(0.78);
    dsd_engine_trunk_scan_tick(&opts, &state);
    test_rc |= expect_active_target(&state, "row site revisit of b", 1U);
    test_rc |= expect_row_site_bytes("the revisit of b", current, &site_b, DSD_CALL_CHANNEL_LPCN);
    trunk_scan_test_set_now(1.04);
    dsd_engine_trunk_scan_tick(&opts, &state);
    test_rc |= expect_active_target(&state, "row site second revisit of a", 0U);
    test_rc |= expect_row_site_bytes("the second revisit of a", current, &site_a, DSD_CALL_CHANNEL_LSN);

    /* Both retunes of the next advance fail: the receiver stays on a, its row as it was. */
    g_counting_tune_to_cc_failures_remaining = 2;
    trunk_scan_test_set_now(1.30);
    dsd_engine_trunk_scan_tick(&opts, &state);
    test_rc |= expect_active_target(&state, "row site rollback", 0U);
    test_rc |= expect_row_site_bytes("the rollback", current, &site_a, DSD_CALL_CHANNEL_LSN);
    test_rc |= expect_row_site_bytes("the rollback, committed row", committed, &site_committed, DSD_CALL_CHANNEL_LCN);
    if (g_counting_tune_to_cc_failures_remaining != 0) {
        DSD_FPRINTF(stderr, "row site rollback: the advance tried %d retunes too few\n",
                    g_counting_tune_to_cc_failures_remaining);
        test_rc = 1;
    }

cleanup:
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* The DMR RAS evidence (dmr_ras.c) is the carrier's and no target snapshot keeps it: every target switch resets it
 * (dmr_ras_reset()), and so does a rollback, which puts back the record the advance started with but not the evidence,
 * so the part the record held goes too until the carrier proves it again. One signature before the switch or the
 * rollback and one after never confirm. */
static int
test_target_switch_and_rollback_reset_dmr_ras(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_runtime_targets("a,dmr-trunk,452000000,,250,,\n"
                             "b,dmr-trunk,453000000,,250,,\n",
                             target_path, sizeof target_path, dir, sizeof dir)
        != 0) {
        return 1;
    }

    static dsd_opts opts;
    static dsd_state state;
    reset_scan_opts_state(&opts, &state);
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;

    dsd_trunk_tuning_hooks hooks = {0};
    hooks.tune_to_cc_request = counting_tune_to_cc;
    dsd_trunk_tuning_hooks_set(hooks);
    g_counting_tune_to_cc_calls = 0;
    g_counting_tune_to_cc_failures_remaining = 0;

    char err[256] = {0};
    trunk_scan_test_set_now(0.0);
    int test_rc = 0;
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0
        || dsd_engine_trunk_scan_active_index(&state) != 0) {
        DSD_FPRINTF(stderr, "ras scan init failed err=%s\n", err);
        test_rc = 1;
    }
    double now = 0.0;
    for (int confirmed = 0; confirmed <= 1; confirmed++) {
        for (int rollback = 0; rollback <= 1; rollback++) {
            dsd_rxid_note_access(&state, DSD_RXID_FAMILY_DMR, (uint8_t)DSD_ACCESS_CODE_COLOR_CODE, 1U);
            dmr_ras_note_signature(&state);
            if (confirmed) {
                dmr_ras_note_signature(&state);
            }
            const size_t active = dsd_engine_trunk_scan_active_index(&state);
            g_counting_tune_to_cc_failures_remaining = rollback ? 2 : 0;
            now += 5.0; /* past the dwell and any retry cooldown a rolled-back switch left */
            trunk_scan_test_set_now(now);
            dsd_engine_trunk_scan_tick(&opts, &state);
            const int moved = dsd_engine_trunk_scan_active_index(&state) != active;
            if (moved == rollback || dmr_ras_confirmed(&state) || (state.rx_id.valid & DSD_RXID_DMR_RAS) != 0U) {
                DSD_FPRINTF(stderr, "ras: %s kept the evidence (confirmed=%d moved=%d signatures=%u valid=%08X)\n",
                            rollback ? "a rollback" : "a switch", confirmed, moved, (unsigned)state.dmr_ras_signatures,
                            (unsigned)state.rx_id.valid);
                test_rc = 1;
            }
            dmr_ras_note_signature(&state);
            if (dmr_ras_confirmed(&state)) {
                DSD_FPRINTF(stderr, "ras: one signature after %s confirmed\n", rollback ? "a rollback" : "a switch");
                test_rc = 1;
            }
            dmr_ras_reset(&state);
        }
    }

    /* The last rollback left b cooling down: the next advance finds nothing eligible and stays, but the retune drop the
       P25 watchdog requested meanwhile is applied there (before the advance keeps the record), and with it the RAS
       evidence of the carrier that retune left goes. */
    const size_t stayed = dsd_engine_trunk_scan_active_index(&state);
    dsd_rxid_note_access(&state, DSD_RXID_FAMILY_DMR, (uint8_t)DSD_ACCESS_CODE_COLOR_CODE, 1U);
    dmr_ras_note_signature(&state);
    dmr_ras_note_signature(&state);
    (void)dsd_rxid_request_trunk_tune(&state);
    now += 0.3;
    trunk_scan_test_set_now(now);
    dsd_engine_trunk_scan_tick(&opts, &state);
    if (dsd_engine_trunk_scan_active_index(&state) != stayed || state.rx_id_trunk_tune_pending != 0U
        || dmr_ras_confirmed(&state) || (state.rx_id.valid & DSD_RXID_DMR_RAS) != 0U) {
        DSD_FPRINTF(stderr,
                    "ras: an advance with nothing eligible kept the evidence (moved=%d pending=%u valid=%08X)\n",
                    dsd_engine_trunk_scan_active_index(&state) != stayed, (unsigned)state.rx_id_trunk_tune_pending,
                    (unsigned)state.rx_id.valid);
        test_rc = 1;
    }

    DSD_MEMSET(&hooks, 0, sizeof hooks);
    dsd_trunk_tuning_hooks_set(hooks);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
test_dmr_targets_pass_sps_to_retune_paths(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_runtime_targets("p25,p25-trunk,851000000,,250,,\n"
                             "dmr,dmr-trunk,452000000,,250,,\n"
                             "conv,dmr-conventional,461000000,,250,,\n",
                             target_path, sizeof target_path, dir, sizeof dir)
        != 0) {
        return 1;
    }

    static dsd_opts opts;
    static dsd_state state;
    reset_scan_opts_state(&opts, &state);
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;

    dsd_trunk_tuning_hooks hooks = {0};
    hooks.tune_to_cc_request = counting_tune_to_cc;
    dsd_trunk_tuning_hooks_set(hooks);
    g_counting_tune_to_cc_calls = 0;
    g_counting_tune_to_cc_failures_remaining = 0;
    g_counting_tune_to_cc_ted_sps = 0;
    g_scan_tune_to_freq_ted_sps = 0;

    char err[256] = {0};
    trunk_scan_test_set_now(0.0);
    int rc = dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err);
    int test_rc = 0;
    if (rc != 0 || dsd_engine_trunk_scan_active_index(&state) != 0) {
        DSD_FPRINTF(stderr, "dmr sps scan init failed rc=%d err=%s\n", rc, err);
        test_rc = 1;
    }

    trunk_scan_test_set_now(0.26);
    dsd_engine_trunk_scan_tick(&opts, &state);
    if (dsd_engine_trunk_scan_active_index(&state) != 1 || g_counting_tune_to_cc_ted_sps != 10) {
        DSD_FPRINTF(stderr, "dmr trunk retune did not receive DMR sps active=%zu sps=%d\n",
                    dsd_engine_trunk_scan_active_index(&state), g_counting_tune_to_cc_ted_sps);
        test_rc = 1;
    }

    trunk_scan_test_set_now(0.52);
    dsd_engine_trunk_scan_tick(&opts, &state);
    if (dsd_engine_trunk_scan_active_index(&state) != 2 || g_scan_tune_to_freq_ted_sps != 10) {
        DSD_FPRINTF(stderr, "dmr conventional retune did not receive DMR sps active=%zu sps=%d\n",
                    dsd_engine_trunk_scan_active_index(&state), g_scan_tune_to_freq_ted_sps);
        test_rc = 1;
    }

    DSD_MEMSET(&hooks, 0, sizeof hooks);
    dsd_trunk_tuning_hooks_set(hooks);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
test_init_failure_restores_saved_trunk_opts(void) {
    char dir[DSD_TEST_PATH_MAX];
    char chan_path[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_temp_dir(dir, sizeof dir) != 0) {
        return 1;
    }
    /* The target's own modulation is in force when its channel map fails to import, so the rollback has the
       configured modulation to put back as well as the trunking flags. */
    static const char header[] = "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,modulation\n";
    if (dsd_test_path_join(chan_path, sizeof chan_path, dir, "chan.csv") != 0
        || write_text_file(chan_path, "channel,frequency\n1,851012500\n") != 0
        || write_targets_file_with_header(dir, header, "dmr,dmr-trunk,452000000,chan.csv,250,,,gfsk\n", target_path,
                                          sizeof target_path)
               != 0) {
        cleanup_paths(dir, NULL, chan_path);
        return 1;
    }

    static dsd_opts opts;
    static dsd_state state;
    reset_scan_opts_state(&opts, &state);
    opts.trunk_enable = 1;
    opts.trunk_is_tuned = 1;
    opts.mod_cli_lock = 1;
    opts.mod_c4fm = 0;
    opts.mod_qpsk = 1;
    opts.mod_gfsk = 0;
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;

    g_csv_import_result = -1;
    char err[256] = {0};
    int rc = dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err);
    g_csv_import_result = 0;

    int test_rc = 0;
    if (rc == 0) {
        DSD_FPRINTF(stderr, "scan init should have failed on chan_csv import\n");
        test_rc = 1;
    }
    if (opts.trunk_enable != 1 || opts.trunk_is_tuned != 1) {
        DSD_FPRINTF(stderr, "scan init failure did not restore trunk opts enabled=%d tuned=%d\n", opts.trunk_enable,
                    opts.trunk_is_tuned);
        test_rc = 1;
    }
    if (opts.mod_cli_lock != 1 || opts.mod_c4fm != 0 || opts.mod_qpsk != 1 || opts.mod_gfsk != 0) {
        DSD_FPRINTF(stderr, "scan init failure did not restore modulation lock=%d c4fm=%d qpsk=%d gfsk=%d\n",
                    opts.mod_cli_lock, opts.mod_c4fm, opts.mod_qpsk, opts.mod_gfsk);
        test_rc = 1;
    }
    if (dsd_engine_trunk_scan_active_index(&state) != (size_t)-1) {
        DSD_FPRINTF(stderr, "failed scan init attached a coordinator\n");
        test_rc = 1;
    }

    cleanup_paths(dir, target_path, chan_path);
    return test_rc;
}

/* Issue #671 (B6): each target's type sets the live trunking flag while it is parked, so a save made then writes the
   trunking setting the session runs outside the scan, which the coordinator publishes, not the parked target's. */
static int
test_save_writes_configured_trunking_under_scan(void) {
    static const struct {
        const char* type;
        const char* row;
        int configured;
        int parked;
    } cases[] = {
        {"p25-trunk", "p25,p25-trunk,851000000,,250,,\n", 0, 1},
        {"dmr-conventional", "dmr,dmr-conventional,452000000,,250,,\n", 1, 0},
    };

    int test_rc = 0;
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        char dir[DSD_TEST_PATH_MAX];
        char target_path[DSD_TEST_PATH_MAX];
        if (make_runtime_targets(cases[i].row, target_path, sizeof target_path, dir, sizeof dir) != 0) {
            return 1;
        }
        static dsd_opts opts;
        static dsd_state state;
        reset_scan_opts_state(&opts, &state);
        opts.trunk_enable = cases[i].configured;
        DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
        opts.trunk_scan_list_count = 1;

        char err[256] = {0};
        trunk_scan_test_set_now(0.0);
        const int rc = dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err);
        static dsdneoUserConfig cfg;
        dsd_snapshot_opts_to_user_config(&opts, &state, &cfg);
        if (rc != 0 || opts.trunk_enable != cases[i].parked
            || state.trunk_scan_configured_trunk_enable != (uint8_t)cases[i].configured
            || cfg.trunk_enabled != cases[i].configured) {
            DSD_FPRINTF(stderr,
                        "save under trunk scan (%s): rc=%d live=%d published=%u saved=%d, want live=%d saved=%d\n",
                        cases[i].type, rc, opts.trunk_enable, (unsigned)state.trunk_scan_configured_trunk_enable,
                        cfg.trunk_enabled, cases[i].parked, cases[i].configured);
            test_rc = 1;
        }
        dsd_engine_trunk_scan_shutdown(&opts, &state);
        if (opts.trunk_enable != cases[i].configured || state.trunk_scan_configured_trunk_enable != 0U) {
            DSD_FPRINTF(stderr, "shutdown (%s): trunk_enable=%d published=%u, want %d and cleared\n", cases[i].type,
                        opts.trunk_enable, (unsigned)state.trunk_scan_configured_trunk_enable, cases[i].configured);
            test_rc = 1;
        }
        trunk_scan_test_clear_now();
        cleanup_paths(dir, target_path, NULL);
    }
    return test_rc;
}

/* The configured trunking setting a scan restores at shutdown can be edited while it runs: the edit is published for
   the save and kept for shutdown, and never reaches the parked target's live flag. */
static int
test_set_configured_trunk_enable(void) {
    static dsd_opts opts;
    static dsd_state state;
    reset_scan_opts_state(&opts, &state);
    int test_rc = 0;
    if (dsd_engine_trunk_scan_set_configured_trunk_enable(&state, 1) != -1
        || state.trunk_scan_configured_trunk_enable != 0U) {
        DSD_FPRINTF(stderr, "configured trunking set without a scan\n");
        test_rc = 1;
    }

    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_runtime_targets("dmr,dmr-conventional,452000000,,250,,\n", target_path, sizeof target_path, dir,
                             sizeof dir)
        != 0) {
        return 1;
    }
    opts.trunk_enable = 0;
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;
    char err[256] = {0};
    trunk_scan_test_set_now(0.0);
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0) {
        DSD_FPRINTF(stderr, "configured trunking scan init failed: %s\n", err);
        test_rc = 1;
    }
    const int set_rc = dsd_engine_trunk_scan_set_configured_trunk_enable(&state, 1);
    static dsdneoUserConfig cfg;
    dsd_snapshot_opts_to_user_config(&opts, &state, &cfg);
    if (set_rc != 0 || state.trunk_scan_configured_trunk_enable != 1U || opts.trunk_enable != 0
        || cfg.trunk_enabled != 1) {
        DSD_FPRINTF(stderr, "configured trunking edit rc=%d published=%u live=%d saved=%d\n", set_rc,
                    (unsigned)state.trunk_scan_configured_trunk_enable, opts.trunk_enable, cfg.trunk_enabled);
        test_rc = 1;
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    if (opts.trunk_enable != 1) {
        DSD_FPRINTF(stderr, "shutdown did not restore the edited trunking setting: %d\n", opts.trunk_enable);
        test_rc = 1;
    }
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #671 (B7): a modulation change made during the scan is the configured modulation (app-control runs it inside
   the scope's suspend/resume bracket, which recaptures the configured settings). Shutdown keeps it, so the exit autosave
   writes it, rather than putting back the modulation the scan started with. */
static int
test_shutdown_keeps_modulation_changed_during_scan(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_runtime_targets("p25,p25-trunk,851000000,,250,,\n", target_path, sizeof target_path, dir, sizeof dir)
        != 0) {
        return 1;
    }
    static dsd_opts opts;
    static dsd_state state;
    reset_scan_opts_state(&opts, &state);
    opts.mod_cli_lock = 0;
    opts.mod_c4fm = 1;
    opts.mod_qpsk = 1;
    opts.mod_gfsk = 1;
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;

    char err[256] = {0};
    trunk_scan_test_set_now(0.0);
    int test_rc = 0;
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0) {
        DSD_FPRINTF(stderr, "modulation scan init failed: %s\n", err);
        test_rc = 1;
    }
    /* What DSD_APP_CMD_MOD_SET does for CQPSK under a scan row. */
    if (dsd_scan_mode_suspend(&opts, &state) != 1) {
        DSD_FPRINTF(stderr, "modulation edit found no scan scope to suspend\n");
        test_rc = 1;
    }
    opts.mod_cli_lock = 1;
    opts.mod_c4fm = 0;
    opts.mod_qpsk = 1;
    opts.mod_gfsk = 0;
    (void)dsd_scan_mode_resume(&opts, &state);

    dsd_engine_trunk_scan_shutdown(&opts, &state);
    static dsdneoUserConfig cfg;
    dsd_snapshot_opts_to_user_config(&opts, &state, &cfg);
    if (opts.mod_cli_lock != 1 || opts.mod_c4fm != 0 || opts.mod_qpsk != 1 || opts.mod_gfsk != 0 || !cfg.has_demod
        || cfg.demod_path != DSDCFG_DEMOD_QPSK) {
        DSD_FPRINTF(
            stderr,
            "shutdown lost the modulation changed during the scan lock=%d c4fm=%d qpsk=%d gfsk=%d saved=%d/%d\n",
            opts.mod_cli_lock, opts.mod_c4fm, opts.mod_qpsk, opts.mod_gfsk, cfg.has_demod, (int)cfg.demod_path);
        test_rc = 1;
    }
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
test_trunk_scan_rejects_fixed_input_without_tuner(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_runtime_targets("a,p25-trunk,851000000,,250,,\n"
                             "b,p25-trunk,852000000,,250,,\n",
                             target_path, sizeof target_path, dir, sizeof dir)
        != 0) {
        return 1;
    }

    static dsd_opts opts;
    static dsd_state state;
    reset_scan_opts_state(&opts, &state);
    opts.audio_in_type = AUDIO_IN_PULSE;
    opts.use_rigctl = 0;
    opts.rigctl_sockfd = DSD_INVALID_SOCKET;
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;

    char err[256] = {0};
    int rc = dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err);
    int test_rc = 0;
    if (rc == 0 || strstr(err, "requires an open RTL input or rigctl") == NULL) {
        DSD_FPRINTF(stderr, "fixed input scan should reject without tuner rc=%d err=%s\n", rc, err);
        test_rc = 1;
    }
    if (dsd_engine_trunk_scan_active_index(&state) != (size_t)-1) {
        DSD_FPRINTF(stderr, "fixed input rejection attached a coordinator\n");
        test_rc = 1;
    }

    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

