#if !DSD_PLATFORM_WIN_NATIVE
/* A key file one row names and the other names through a hard link to it is the same file (issue #697): both rows load
   the same keys, so they are one target; the canonical path of a hard link is its own, so only the file's identity
   tells. */
static int
test_lists_shared_row_key_file_hard_link(void) {
    static const char* const names[] = {"one", "two"};
    const char* bodies[] = {
        "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,keys_hex_csv\n"
        "ROK,dmr-conventional,461000000,,1500,1200,,keys.csv\n",
        "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,keys_hex_csv\n"
        "ROK,dmr-conventional,461000000,,1500,1200,,keys-link.csv\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    char keys[DSD_TEST_PATH_MAX];
    char keys_link[DSD_TEST_PATH_MAX];
    if (scan_list_files_write(&files, "", names, bodies, 2) != 0
        || dsd_test_path_join(keys, sizeof keys, files.dir, "keys.csv") != 0
        || write_text_file(keys, "key id(hex),key value (hex)\n0010,AAAAAAAAAAAAAAAA\n") != 0
        || dsd_test_path_join(keys_link, sizeof keys_link, files.dir, "keys-link.csv") != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    int test_rc = 0;
    if (link(keys, keys_link) == 0) {
        reset_scan_opts_state(&opts, &state);
        scan_list_files_to_opts(&files, NULL, &opts);
        char err[2048] = {0};
        trunk_scan_test_set_now(0.0);
        if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0
            || dsd_engine_trunk_scan_target_count(&state) != 1U) {
            DSD_FPRINTF(stderr, "a key file and a hard link to it did not share: %zu targets, err \"%s\"\n",
                        dsd_engine_trunk_scan_target_count(&state), err);
            test_rc = 1;
        }
        test_rc |= expect_target_lists(&state, 0U, 0x3, 0U);
        dsd_engine_trunk_scan_shutdown(&opts, &state);
        trunk_scan_test_clear_now();
    }
    (void)remove(keys_link);
    (void)remove(keys);
    scan_list_files_remove(&files);
    return test_rc;
}
#endif

/* The target budget counts distinct targets: two lists over half the budget each fit when they hold the same targets
   (test_lists_union_target_cap() refuses them under ids of their own). */
static int
test_lists_budget_counts_distinct_targets(void) {
    const size_t half = (dsd_trunk_scan_max_targets() / 2U) + 1U;
    dsd_trunk_scan_target* rows = (dsd_trunk_scan_target*)calloc(half, sizeof *rows);
    size_t* row_targets = (size_t*)calloc(half * 2U, sizeof *row_targets);
    if (rows == NULL || row_targets == NULL) {
        free(rows);
        free(row_targets);
        return 1;
    }
    for (size_t i = 0; i < half; i++) {
        DSD_SNPRINTF(rows[i].id, sizeof rows[i].id, "t%zu", i);
        rows[i].type = DSD_TRUNK_SCAN_TARGET_P25_TRUNK;
        rows[i].frequency_hz = (uint32_t)(800000000U + i);
        rows[i].csv_row = (unsigned int)(i + 2U);
    }
    /* One file as both lists. */
    dsd_trunk_scan_target_list lists[2] = {{rows, half, half}, {rows, half, half}};
    static const char* const names[] = {"first", "second"};
    char err[512] = {0};
    size_t distinct = 0U;
    int test_rc = 0;
    if (dsd_trunk_scan_check_target_lists(lists, names, 2U, row_targets, half * 2U, &distinct, err, sizeof err) != 0
        || distinct != half) {
        DSD_FPRINTF(stderr, "two shared lists over half the budget: distinct %zu (want %zu), err \"%s\"\n", distinct,
                    half, err);
        test_rc = 1;
    }
    for (size_t i = 0; test_rc == 0 && i < half; i++) {
        if (row_targets[i] != i || row_targets[half + i] != i) {
            DSD_FPRINTF(stderr, "row %zu: targets %zu and %zu, want %zu in both lists\n", i, row_targets[i],
                        row_targets[half + i], i);
            test_rc = 1;
        }
    }
    free(rows);
    free(row_targets);
    return test_rc;
}

/* A row_targets with room for fewer entries than the lists hold rows is refused before the merge writes into it. */
static int
test_lists_short_row_targets_refused(void) {
    static dsd_trunk_scan_target rows[2];
    DSD_MEMSET(rows, 0, sizeof rows);
    for (size_t i = 0; i < 2U; i++) {
        DSD_SNPRINTF(rows[i].id, sizeof rows[i].id, "t%zu", i);
        rows[i].type = DSD_TRUNK_SCAN_TARGET_P25_TRUNK;
        rows[i].frequency_hz = (uint32_t)(851000000U + i);
        rows[i].csv_row = (unsigned int)(i + 2U);
    }
    dsd_trunk_scan_target_list lists[2] = {{&rows[0], 1U, 1U}, {&rows[1], 1U, 1U}};
    static const char* const names[] = {"first", "second"};
    size_t row_targets[3] = {7U, 7U, 7U};
    char err[512] = {0};
    size_t distinct = 9U;
    const int rc = dsd_trunk_scan_check_target_lists(lists, names, 2U, row_targets, 1U, &distinct, err, sizeof err);
    if (rc != -1 || distinct != 0U || strcmp(err, "failed to merge the trunk scan target lists") != 0
        || row_targets[0] != 7U || row_targets[1] != 7U || row_targets[2] != 7U) {
        DSD_FPRINTF(stderr, "short row_targets: rc %d distinct %zu err \"%s\" entries %zu %zu %zu\n", rc, distinct, err,
                    row_targets[0], row_targets[1], row_targets[2]);
        return 1;
    }
    if (dsd_trunk_scan_check_target_lists(lists, names, 2U, row_targets, 2U, &distinct, err, sizeof err) != 0
        || distinct != 2U || row_targets[0] != 0U || row_targets[1] != 1U || row_targets[2] != 7U) {
        DSD_FPRINTF(stderr, "exact row_targets: distinct %zu err \"%s\" entries %zu %zu %zu\n", distinct, err,
                    row_targets[0], row_targets[1], row_targets[2]);
        return 1;
    }
    return 0;
}

/* A target in two lists that both start off: --trunk-scan-hold names every list that holds it. A target whose owner
   list starts off while another of its lists starts on loads as one target in both, and --trunk-scan-hold holds it,
   the list on that holds it named on air. */
static int
test_hold_on_shared_target_lists_off(void) {
    static const char* const names[] = {"state", "conv", "low"};
    static const char* const bodies[] = {
        "x,p25-trunk,851000000,,250,,\n",
        "ROK,p25-trunk,853000000,,250,,\n",
        "y,p25-trunk,854000000,,250,,\nROK,p25-trunk,853000000,,250,,\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_list_files_write(&files, k_header, names, bodies, 3) != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    int test_rc = 0;
    reset_scan_opts_state(&opts, &state);
    const int both_off[] = {0, 1, 1};
    scan_list_files_to_opts(&files, both_off, &opts);
    DSD_SNPRINTF(opts.trunk_scan_hold_id, sizeof opts.trunk_scan_hold_id, "%s", "ROK");
    char err[512] = {0};
    trunk_scan_test_set_now(0.0);
    static const char want[] =
        "--trunk-scan-hold: target \"ROK\" is in lists that are off (list 2, conv; list 3, low); start one of them on";
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != -1 || strcmp(err, want) != 0
        || dsd_engine_trunk_scan_active_index(&state) != (size_t)-1 || opts.trunk_scan_hold_id[0] != '\0') {
        DSD_FPRINTF(stderr, "hold on a shared target with its lists off: \"%s\", want \"%s\"\n", err, want);
        test_rc = 1;
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);

    reset_scan_opts_state(&opts, &state);
    const int owner_off[] = {0, 1, 0};
    scan_list_files_to_opts(&files, owner_off, &opts);
    DSD_SNPRINTF(opts.trunk_scan_hold_id, sizeof opts.trunk_scan_hold_id, "%s", "ROK");
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0
        || dsd_engine_trunk_scan_target_count(&state) != 3U) {
        DSD_FPRINTF(stderr, "a shared target whose owner list starts off: %zu targets, err \"%s\"\n",
                    dsd_engine_trunk_scan_target_count(&state), err);
        test_rc = 1;
    }
    test_rc |= expect_target_lists(&state, 1U, 0x6, 1U);
    test_rc |= expect_list_published(&state, "owner off", 2, "conv", 0U, 1U);
    test_rc |= expect_list_published(&state, "owner off", 3, "low", 1U, 2U);
    /* Targets x ROK y, x and ROK and y in the rotation: ROK held, named by low. */
    test_rc |= expect_published_target(&state, "hold, owner off", "ROK", 2U, 3U);
    test_rc |= expect_list_on_air(&state, "hold, owner off", 3U, 0U, 2U, 3U);
    if (state.trunk_scan_hold != 1U || state.trunk_scan_active_lists != 0x6U) {
        DSD_FPRINTF(stderr, "hold, owner off: hold %u lists 0x%x, want 1 0x6\n", (unsigned)state.trunk_scan_hold,
                    (unsigned)state.trunk_scan_active_lists);
        test_rc = 1;
    }
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* A target of list 2 that cannot be built (its channel map fails to import) fails the start through the init-failure
 * path, after list 1's target was built: the trunking and modulation options come back, nothing stays attached and
 * nothing is published. */
static int
test_lists_build_failure_in_list_two_cleans_up(void) {
    static const char* const names[] = {"one", "two"};
    scan_list_files files;
    const char* bodies[] = {"a,p25-trunk,851000000,,250,,\n", "dmr,dmr-trunk,452000000,chan.csv,250,,\n"};
    if (scan_list_files_write(&files, k_header, names, bodies, 2) != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    char chan_path[DSD_TEST_PATH_MAX];
    if (dsd_test_path_join(chan_path, sizeof chan_path, files.dir, "chan.csv") != 0
        || write_text_file(chan_path, "channel,frequency\n1,851012500\n") != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    static dsd_opts opts;
    static dsd_state state;
    reset_scan_opts_state(&opts, &state);
    scan_list_files_to_opts(&files, NULL, &opts);
    opts.trunk_enable = 1;
    opts.trunk_is_tuned = 1;
    g_csv_import_result = -1;
    char err[512] = {0};
    const int rc = dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err);
    g_csv_import_result = 0;
    int test_rc = 0;
    if (rc == 0 || opts.trunk_enable != 1 || opts.trunk_is_tuned != 1
        || dsd_engine_trunk_scan_active_index(&state) != (size_t)-1 || state.trunk_scan_list_count != 0U
        || state.trunk_scan_active_id[0] != '\0') {
        DSD_FPRINTF(stderr, "list 2 build failure: rc=%d trunk %d/%d attached=%d lists=%u err=%s\n", rc,
                    opts.trunk_enable, opts.trunk_is_tuned, dsd_engine_trunk_scan_active_index(&state) != (size_t)-1,
                    (unsigned)state.trunk_scan_list_count, err);
        test_rc = 1;
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    (void)remove(chan_path);
    scan_list_files_remove(&files);
    return test_rc;
}

/* A start with list 1 off parks on the first target of a list that is on; the startup park also passes over a target
 * the DSP rate cannot filter. Every list on at once, and every list off is refused. */
static int
test_lists_start_on_the_first_reachable_target_and_all_on(void) {
    static const char* const names[] = {"one", "two", "three"};
    static const char two[] = "wide,nfm-conventional,155430000,,250,2000,,--nfm-bandwidth-hz 20000\n"
                              "b,nfm-conventional,156430000,,250,2000,,\n";
    static const char* const bodies[] = {
        "a,nfm-conventional,154430000,,250,2000,,\n",
        two,
        "c,nfm-conventional,157430000,,250,2000,,\n",
    };
    static const int off[] = {1, 0, 1};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    g_scan_dsp_rate_hz = 16000;
    int test_rc = 0;
    if (scan_lists_init(&files, k_squelch_targets_header, names, bodies, off, 3, &opts, &state) != 0) {
        g_scan_dsp_rate_hz = 0;
        return 1;
    }
    test_rc |= expect_published_target(&state, "start with list 1 off", "b", 3U, 4U);
    test_rc |= expect_list_on_air(&state, "start with list 1 off", 2U, 0U, 2U, 2U);
    test_rc |= expect_list_rc("every list on", list_set(&opts, &state, DSD_TRUNK_SCAN_LIST_ALL, 1),
                              DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_list_published(&state, "every list on", 1, "one", 1U, 1U);
    test_rc |= expect_list_published(&state, "every list on", 2, "two", 1U, 2U);
    test_rc |= expect_list_published(&state, "every list on", 3, "three", 1U, 1U);
    test_rc |= expect_list_on_air(&state, "every list on", 2U, 0U, 3U, 4U);
    test_rc |= expect_list_rc("every list on again", list_set(&opts, &state, DSD_TRUNK_SCAN_LIST_ALL, 1),
                              DSD_TRUNK_SCAN_LIST_SET_UNCHANGED);
    test_rc |= expect_list_rc("every list off", list_set(&opts, &state, DSD_TRUNK_SCAN_LIST_ALL, 0),
                              DSD_TRUNK_SCAN_LIST_SET_REFUSED_LAST);
    scan_lists_finish(&files, &opts, &state);
    g_scan_dsp_rate_hz = 0;
    return test_rc;
}

/* Switching off the list that holds the target on air leaves it at once, as `L` does: the call in progress ends
 * and commits under the target it was heard on, its carrier is handed back, and the operator's hold carries over to
 * the target it lands on. Two lists of one target each: switching the first off moves to the second. */
static int
test_lists_switching_off_the_list_on_air_leaves_at_once(void) {
    static const char* const names[] = {"a", "b"};
    static const char* const bodies[] = {"a,p25-trunk,851000000,,250,,\n", "b,p25-trunk,852000000,,250,,\n"};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
        return 1;
    }
    int test_rc =
        expect_control_rc("hold", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
    opts.trunk_is_tuned = 1;
    state.p25_vc_freq[0] = 851112500;
    state.trunk_vc_freq[0] = 851112500;
    test_rc |= seed_active_call_row(&state, 1001U, 2002U, 0.10);
    const int ends_before = g_explicit_call_ends;
    g_release_seen_target[0] = '\0';
    trunk_scan_test_set_now(0.20);
    test_rc |= expect_list_rc("list a off", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_published_target(&state, "list a off", "b", 2U, 2U);
    test_rc |= expect_list_on_air(&state, "list a off", 2U, 0U, 1U, 1U);
    if (g_explicit_call_ends != ends_before + 1 || strcmp(g_release_seen_target, "a") != 0 || opts.trunk_is_tuned != 0
        || state.trunk_scan_hold != 1U) {
        DSD_FPRINTF(stderr, "list off on air: %d calls ended under '%s', tuned %d, hold %u; want 1 under 'a', 0, 1\n",
                    g_explicit_call_ends - ends_before, g_release_seen_target, opts.trunk_is_tuned,
                    (unsigned)state.trunk_scan_hold);
        test_rc = 1;
    }
    test_rc |= expect_vc_mirrors_clear(&state, "list a off");
    /* The hold keeps b; a never comes back while its list is off. */
    tick_at(&opts, &state, 0.60);
    tick_at(&opts, &state, 1.20);
    test_rc |= expect_published_target(&state, "held after the list went off", "b", 2U, 2U);
    test_rc |= expect_no_active_call_row(&state, "held after the list went off");
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* Issue #668 beside issue #697: switching off the list of an NFM target on air leaves it through the release `b` and
 * `L` use (trunk_scan_release_active_carrier()), whose dsd_engine_release_tuned_call_state() ends the NFM call first,
 * so its recording (pre-roll included) and its row close once, under its own name, before the next target's replace
 * them. A switch of a list not on air releases nothing. */
static int
test_lists_switching_off_an_nfm_target_ends_its_call_once(void) {
    static const char* const names[] = {"a", "b", "c"};
    static const char* const bodies[] = {
        "a1,nfm-conventional,154430000,,250,250,,\n",
        "b1,nfm-conventional,155430000,,250,250,,\n",
        "c1,nfm-conventional,156430000,,250,250,,\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, k_squelch_targets_header, names, bodies, NULL, 3, &opts, &state) != 0) {
        return 1;
    }
    int test_rc = expect_published_target(&state, "nfm lists start", "a1", 1U, 3U);
    test_rc |= seed_active_call_row(&state, 1001U, 2002U, 0.05);
    const int ends_before = g_explicit_call_ends;
    g_release_seen_target[0] = '\0';
    trunk_scan_test_set_now(0.10);
    test_rc |= expect_list_rc("nfm list c off", list_set(&opts, &state, 3, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_published_target(&state, "nfm list c off", "a1", 1U, 3U);
    if (g_explicit_call_ends != ends_before) {
        DSD_FPRINTF(stderr, "nfm list c off ended %d calls, want 0\n", g_explicit_call_ends - ends_before);
        test_rc = 1;
    }
    trunk_scan_test_set_now(0.20);
    test_rc |= expect_list_rc("nfm list a off", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_published_target(&state, "nfm list a off", "b1", 2U, 3U);
    if (g_explicit_call_ends != ends_before + 1 || strcmp(g_release_seen_target, "a1") != 0) {
        DSD_FPRINTF(stderr, "nfm list a off ended %d calls under '%s', want 1 under 'a1'\n",
                    g_explicit_call_ends - ends_before, g_release_seen_target);
        test_rc = 1;
    }
    /* The rotation on b1 and back: nothing of a1's call is ended again. */
    tick_at(&opts, &state, 0.60);
    tick_at(&opts, &state, 1.20);
    test_rc |= expect_no_active_call_row(&state, "nfm after the list went off");
    if (g_explicit_call_ends != ends_before + 1) {
        DSD_FPRINTF(stderr, "nfm after the list went off: a1's call ended again\n");
        test_rc = 1;
    }
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* A toggle that would leave nothing to scan is refused -- the last list on, every list at once, a list
 * whose others hold only avoided targets or targets the DSP rate cannot filter -- and so is any while the scan is
 * paused, while the tick guard is held, or that names another session or a list it does not have. None changes a
 * list. */
static int
test_lists_refusals(void) {
    static const char* const names[] = {"a", "b", "wide"};
    static const char* const bodies[] = {
        "a1,nfm-conventional,154430000,,250,250,,\n",
        "b1,nfm-conventional,155430000,,250,250,,\n",
        "w1,nfm-conventional,156430000,,250,250,,--nfm-bandwidth-hz 20000\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    g_scan_dsp_rate_hz = 16000;
    if (scan_lists_init(&files, k_squelch_targets_header, names, bodies, NULL, 3, &opts, &state) != 0) {
        g_scan_dsp_rate_hz = 0;
        return 1;
    }
    int test_rc = expect_published_target(&state, "start", "a1", 1U, 3U);
    test_rc |= expect_list_rc("b off", list_set(&opts, &state, 2, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_list_rc("b off again", list_set(&opts, &state, 2, 0), DSD_TRUNK_SCAN_LIST_SET_UNCHANGED);
    /* Left with the width-skipped w1 alone, which the rotation can only pass over. */
    test_rc |= expect_list_rc("a off, wide left", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_REFUSED_LAST);
    test_rc |= expect_list_rc("every list off", list_set(&opts, &state, DSD_TRUNK_SCAN_LIST_ALL, 0),
                              DSD_TRUNK_SCAN_LIST_SET_REFUSED_LAST);
    test_rc |= expect_list_rc("b on", list_set(&opts, &state, 2, 1), DSD_TRUNK_SCAN_LIST_SET_OK);
    /* b1 avoided: list a off would leave only it and w1. */
    test_rc |= expect_control_rc("advance to b1",
                                 dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE), 0);
    test_rc |= expect_control_rc("avoid b1",
                                 dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE), 0);
    test_rc |= expect_published_target(&state, "avoid b1", "a1", 1U, 3U);
    test_rc |= expect_list_rc("a off, the others avoided", list_set(&opts, &state, 1, 0),
                              DSD_TRUNK_SCAN_LIST_SET_REFUSED_LAST);

    /* The session a list toggle names is the one a put back names (issue #672's trunk_scan_session). */
    const uint32_t session = state.trunk_scan_session;
    const uint32_t seq = state.trunk_scan_lists_seq;
    if (session == 0U || session != state.scan_row_session) {
        DSD_FPRINTF(stderr, "running: trunk_scan_session %u, scan_row_session %u; want the same nonzero session\n",
                    (unsigned)session, (unsigned)state.scan_row_session);
        test_rc = 1;
    }
    test_rc |= expect_list_rc("another session", dsd_engine_trunk_scan_list_set(&opts, &state, session + 1U, 2, 0, 7U),
                              DSD_TRUNK_SCAN_LIST_SET_STALE);
    test_rc |= expect_list_rc("no session", dsd_engine_trunk_scan_list_set(&opts, &state, 0U, 2, 0, 7U),
                              DSD_TRUNK_SCAN_LIST_SET_STALE);
    test_rc |= expect_list_rc("list 0", list_set(&opts, &state, 0, 0), DSD_TRUNK_SCAN_LIST_SET_STALE);
    test_rc |= expect_list_rc("list 4", list_set(&opts, &state, 4, 0), DSD_TRUNK_SCAN_LIST_SET_STALE);
    g_p25_tick_guard_available = 0;
    test_rc |= expect_list_rc("guard held", list_set(&opts, &state, 3, 0), DSD_TRUNK_SCAN_LIST_SET_BUSY);
    g_p25_tick_guard_available = 1;
    if (dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_IN_PLACE) != 0) {
        test_rc = 1;
    }
    /* Paused, the published session stays (scan_row_session does not), so a frontend's toggle hears "paused", not
       "stale". */
    if (state.trunk_scan_session != session || state.scan_row_session != 0U) {
        DSD_FPRINTF(stderr, "paused: trunk_scan_session %u, scan_row_session %u; want %u and 0\n",
                    (unsigned)state.trunk_scan_session, (unsigned)state.scan_row_session, (unsigned)session);
        test_rc = 1;
    }
    test_rc |= expect_list_rc("paused", list_set(&opts, &state, 3, 0), DSD_TRUNK_SCAN_LIST_SET_PAUSED);
    if (state.trunk_scan_lists_seq != seq || state.trunk_scan_lists[2].enabled != 1U) {
        DSD_FPRINTF(stderr, "a refused toggle changed the lists: seq %u -> %u, wide %u\n", (unsigned)seq,
                    (unsigned)state.trunk_scan_lists_seq, (unsigned)state.trunk_scan_lists[2].enabled);
        test_rc = 1;
    }
    scan_lists_finish(&files, &opts, &state);
    g_scan_dsp_rate_hz = 0;
    return test_rc;
}

/* Issue #697: `b` on a target whose only alternate the DSP rate cannot filter used to be accepted
 * and leave the operator on a target avoided. Somewhere to go is a target the rotation can reach. */
static int
test_scan_avoid_refuses_when_the_only_alternate_is_width_skipped(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    g_scan_dsp_rate_hz = 16000;
    if (nfm_targets_init("fire,nfm-conventional,154430000,,250,2000,,--nfm-bandwidth-hz 12500\n"
                         "wide,nfm-conventional,155430000,,250,2000,,--nfm-bandwidth-hz 20000\n",
                         &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        g_scan_dsp_rate_hz = 0;
        return 1;
    }
    int test_rc = expect_control_rc("avoid with a width-skipped alternate",
                                    dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE),
                                    DSD_TRUNK_SCAN_CONTROL_REFUSED);
    test_rc |= expect_scan_control_publication(&state, "avoid with a width-skipped alternate", 0U, 0U, 0U);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    g_scan_dsp_rate_hz = 0;
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* `J` and `L` (issue #666) pass over a list that is off in either direction. */
static int
test_lists_retreat_and_advance_pass_over_a_list_off(void) {
    static const char* const names[] = {"a", "b", "c"};
    static const char* const bodies[] = {
        "a1,p25-trunk,851000000,,250,,\na2,p25-trunk,852000000,,250,,\n",
        "b1,p25-trunk,853000000,,250,,\n",
        "c1,p25-trunk,854000000,,250,,\n",
    };
    static const int off[] = {0, 1, 0};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, off, 3, &opts, &state) != 0) {
        return 1;
    }
    int test_rc = expect_control_rc("retreat from a1",
                                    dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_RETREAT), 0);
    test_rc |= expect_published_target(&state, "retreat from a1", "c1", 4U, 4U);
    test_rc |= expect_list_on_air(&state, "retreat from a1", 3U, 0U, 3U, 3U);
    test_rc |= expect_control_rc("retreat from c1",
                                 dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_RETREAT), 0);
    test_rc |= expect_published_target(&state, "retreat past b", "a2", 2U, 4U);
    test_rc |= expect_control_rc("advance from a2",
                                 dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE), 0);
    test_rc |= expect_published_target(&state, "advance past b", "c1", 4U, 4U);
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* The visit cap counts only alternates in the rotation: with the other target's list off it re-arms, and switching
 * that list on gives the visit on air its first alternate, so its limit starts again in full there -- not at once. */
static int
test_lists_visit_cap_waits_for_a_list_on(void) {
    static const char* const names[] = {"a", "b"};
    static const char* const bodies[] = {"a,p25-trunk,851000000,,250,,\n", "b,p25-trunk,852000000,,250,,\n"};
    static const int off[] = {0, 1};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_list_files_write(&files, k_header, names, bodies, 2) != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    reset_scan_opts_state(&opts, &state);
    scan_list_files_to_opts(&files, off, &opts);
    opts.scan_max_visit_ms = 1000;
    char err[512] = {0};
    trunk_scan_test_set_now(0.0);
    int test_rc = 0;
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0) {
        DSD_FPRINTF(stderr, "visit cap lists init: %s\n", err);
        scan_list_files_remove(&files);
        return 1;
    }
    /* A call being followed holds a against its dwell; only the cap could move it. */
    for (int tick = 1; tick <= 5; tick++) {
        opts.trunk_is_tuned = 1;
        tick_at(&opts, &state, (double)tick);
    }
    test_rc |= expect_published_target(&state, "the cap with b's list off", "a", 1U, 2U);
    trunk_scan_test_set_now(5.0);
    test_rc |= expect_list_rc("b on", list_set(&opts, &state, 2, 1), DSD_TRUNK_SCAN_LIST_SET_OK);
    opts.trunk_is_tuned = 1;
    tick_at(&opts, &state, 5.5);
    test_rc |= expect_published_target(&state, "half a limit after b went on", "a", 1U, 2U);
    opts.trunk_is_tuned = 1;
    tick_at(&opts, &state, 6.05);
    test_rc |= expect_published_target(&state, "a full limit after b went on", "b", 2U, 2U);
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

static int
expect_departure_due(const dsd_opts* opts, const dsd_state* state, const char* stage, double now_m, int want) {
    trunk_scan_test_set_now(now_m);
    const int got = dsd_engine_trunk_scan_departure_due(opts, state);
    if (got != want) {
        DSD_FPRINTF(stderr, "departure due after %s at %.2f: %d, want %d\n", stage, now_m, got, want);
        return 1;
    }
    return 0;
}

/* Issue #697: a departure that cannot tune anywhere stays owed. With b's retune failing, switching a's list off falls
 * back onto a -- published as out of the rotation, (-/1) -- under the operator's hold, with traffic still holding it.
 * The frame loop is not asked to yield before b's cooldown ends, and is then; the tick leaves for b ahead of the hold
 * and the activity. */
static int
test_lists_departure_waits_out_a_failed_retune(void) {
    static const char* const names[] = {"a", "b"};
    static const char* const bodies[] = {"a,p25-trunk,851000000,,250,,\n", "b,p25-trunk,852000000,,250,,\n"};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
        return 1;
    }
    int test_rc =
        expect_control_rc("hold", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
    g_counting_tune_to_cc_calls = 0;
    g_counting_tune_to_cc_failures_remaining = 1;
    trunk_scan_test_set_now(0.10);
    test_rc |= expect_list_rc("a off, b failing", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    g_counting_tune_to_cc_failures_remaining = 0;
    test_rc |= expect_published_target(&state, "a off, b failing", "a", 1U, 2U);
    test_rc |= expect_list_on_air(&state, "a off, b failing", 1U, 1U, 0U, 1U);
    test_rc |= expect_departure_due(&opts, &state, "b's failure", 0.50, 0);
    /* A pause keeps the obligation, and a resume with b still cooling down resumes where it paused and waits again. */
    trunk_scan_test_set_now(0.55);
    if (dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_IN_PLACE) != 0
        || dsd_engine_trunk_scan_resume_locked(&opts, &state) != 0) {
        DSD_FPRINTF(stderr, "pause and resume while the departure waits failed\n");
        test_rc = 1;
    }
    test_rc |= expect_published_target(&state, "resumed while b cools down", "a", 1U, 2U);
    test_rc |= expect_departure_due(&opts, &state, "the resume in place", 0.60, 0);
    opts.trunk_is_tuned = 1;
    tick_at(&opts, &state, 1.00);
    test_rc |= expect_published_target(&state, "b cooling down", "a", 1U, 2U);
    test_rc |= expect_departure_due(&opts, &state, "b's cooldown", 2.15, 1);
    const int calls = g_counting_tune_to_cc_calls;
    opts.trunk_is_tuned = 1;
    tick_at(&opts, &state, 2.15);
    test_rc |= expect_published_target(&state, "the departure after b's cooldown", "b", 2U, 2U);
    test_rc |= expect_list_on_air(&state, "the departure after b's cooldown", 2U, 0U, 1U, 1U);
    test_rc |= expect_departure_due(&opts, &state, "the departure", 2.20, 0);
    if (g_counting_tune_to_cc_calls != calls + 1 || state.trunk_scan_hold != 1U) {
        DSD_FPRINTF(stderr, "departure after the cooldown: %d tunes, hold %u; want 1 and the hold kept\n",
                    g_counting_tune_to_cc_calls - calls, (unsigned)state.trunk_scan_hold);
        test_rc = 1;
    }
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* Issue #697: a departure whose switch cannot be prepared (b's keys do not allocate) backs off a cooldown, as a failed
 * retune does, rather than trying again at every tick or making the frame loop yield at every frame. */
static int
test_lists_departure_backs_off_a_failed_preparation(void) {
    static const char* const names[] = {"a", "b"};
    static const char* const bodies[] = {"a,p25-trunk,851000000,,250,,,\n",
                                         "b,p25-trunk,852000000,,250,,,-K keys.csv\n"};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_list_files_write(&files, k_squelch_targets_header, names, bodies, 2) != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    char keys[DSD_TEST_PATH_MAX];
    if (dsd_test_path_join(keys, sizeof keys, files.dir, "keys.csv") != 0
        || write_text_file(keys, "key id(hex),key value (hex)\n0010,AAAAAAAAAAAAAAAA\n") != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    reset_scan_opts_state(&opts, &state);
    scan_list_files_to_opts(&files, NULL, &opts);
    char err[512] = {0};
    trunk_scan_test_set_now(0.0);
    int test_rc = 0;
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0) {
        DSD_FPRINTF(stderr, "prepare failure lists init: %s\n", err);
        test_rc = 1;
    } else {
        test_rc |= expect_control_rc(
            "hold", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
        g_counting_tune_to_cc_calls = 0;
        dsd_key_set_test_alloc_fail_after(0);
        trunk_scan_test_set_now(0.10);
        test_rc |= expect_list_rc("a off, b unprepared", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
        dsd_key_set_test_alloc_fail_after(-1);
        test_rc |= expect_published_target(&state, "a off, b unprepared", "a", 1U, 2U);
        test_rc |= expect_departure_due(&opts, &state, "the failed preparation", 1.00, 0);
        tick_at(&opts, &state, 1.00);
        tick_at(&opts, &state, 1.50);
        if (g_counting_tune_to_cc_calls != 0) {
            DSD_FPRINTF(stderr, "a failed preparation was retried within its cooldown: %d tunes\n",
                        g_counting_tune_to_cc_calls);
            test_rc = 1;
        }
        test_rc |= expect_departure_due(&opts, &state, "the preparation's cooldown", 2.15, 1);
        tick_at(&opts, &state, 2.15);
        test_rc |= expect_published_target(&state, "the departure after the cooldown", "b", 2U, 2U);
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    (void)remove(keys);
    scan_list_files_remove(&files);
    return test_rc;
}

/* A departure onto b whose retune then fails asynchronously leaves b with no alternate in the rotation (a's list is
 * off), so b is retried in place after its cooldown, as a target in the rotation with no alternate is. */
static int
test_lists_departure_with_an_async_failure_retries_the_landing(void) {
    static const char* const names[] = {"a", "b"};
    static const char* const bodies[] = {"a,dmr-trunk,461000000,,250,,\n", "b,dmr-trunk,462000000,,250,,\n"};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    dsd_trunk_tuning_requests_reset();
    if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
        return 1;
    }
    int test_rc = 0;
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    g_counting_tune_to_cc_calls = 0;
    trunk_scan_test_set_now(1.0);
    test_rc |= expect_list_rc("a off, b pending", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    test_rc |= expect_published_target(&state, "a off, b pending", "b", 2U, 2U);
    dsd_trunk_tuning_request_publish(g_counting_tune_to_cc_last_request_id, DSD_TRUNK_TUNE_RESULT_FAILED);
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_published_target(&state, "b failed asynchronously", "b", 2U, 2U);
    tick_at(&opts, &state, 3.2);
    if (g_counting_tune_to_cc_calls != 2 || g_counting_tune_to_cc_freq != 462000000L) {
        DSD_FPRINTF(stderr, "b was not retried in place: %d tunes, last %ld\n", g_counting_tune_to_cc_calls,
                    g_counting_tune_to_cc_freq);
        test_rc = 1;
    }
    scan_lists_finish(&files, &opts, &state);
    dsd_trunk_tuning_requests_reset();
    return test_rc;
}

/* Issue #697: the obligation ends as soon as the target on air is in the rotation again -- its list switched back on,
 * every list on, the avoids cleared, the target put back (issue #672) -- and stays while either reason still holds: an
 * avoided target whose list is off owes the departure after its avoid is cleared or it is put back, and a put back
 * never switches its list on. Both reasons are published, each on its own. */
static int
test_lists_departure_cancellation(void) {
    static const char* const names[] = {"a", "b"};
    static const char* const bodies[] = {"a,p25-trunk,851000000,,250,,\n", "b,p25-trunk,852000000,,250,,\n"};
    static dsd_opts opts;
    static dsd_state state;
    int test_rc = 0;
    for (int how = 0; how < 4; how++) {
        scan_list_files files;
        if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
            return 1;
        }
        test_rc |= expect_control_rc(
            "hold", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
        g_counting_tune_to_cc_failures_remaining = 1;
        trunk_scan_test_set_now(0.10);
        if (how < 2) {
            test_rc |= expect_list_rc("a off", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
            test_rc |= expect_list_rc("a back on", list_set(&opts, &state, how == 0 ? 1 : DSD_TRUNK_SCAN_LIST_ALL, 1),
                                      DSD_TRUNK_SCAN_LIST_SET_OK);
        } else {
            test_rc |= expect_control_rc(
                "avoid a", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE), 1);
            test_rc |= expect_scan_control_publication(&state, "avoid a, b failing", 1U, 1U, 1U);
            if (how == 2) {
                test_rc |= expect_control_rc(
                    "clear", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_CLEAR), 1);
            } else {
                test_rc |= expect_control_rc(
                    "put back a",
                    dsd_engine_trunk_scan_unavoid_target(&opts, &state, state.trunk_scan_session, "a", NULL),
                    DSD_TRUNK_SCAN_CONTROL_OK);
                test_rc |= expect_scan_control_publication(&state, "a put back", 1U, 0U, 0U);
            }
        }
        g_counting_tune_to_cc_failures_remaining = 0;
        test_rc |= expect_list_on_air(&state, "back in the rotation", 1U, 0U, 1U, 2U);
        test_rc |= expect_departure_due(&opts, &state, "back in the rotation", 2.20, 0);
        tick_at(&opts, &state, 2.20);
        tick_at(&opts, &state, 3.00);
        test_rc |= expect_published_target(&state, "held after the obligation ended", "a", 1U, 2U);
        scan_lists_finish(&files, &opts, &state);
    }

    /* List off and avoided at once: clearing the avoid, or putting the target back, leaves the list off, and the
       departure still runs. */
    for (int put_back = 0; put_back < 2; put_back++) {
        scan_list_files files;
        if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
            return 1;
        }
        test_rc |= expect_control_rc(
            "hold", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
        g_counting_tune_to_cc_failures_remaining = 1;
        trunk_scan_test_set_now(0.10);
        test_rc |= expect_control_rc(
            "avoid a", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE), 1);
        g_counting_tune_to_cc_failures_remaining = 0;
        test_rc |= expect_list_rc("a off too", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
        test_rc |= expect_scan_control_publication(&state, "avoided and off", 1U, 1U, 1U);
        test_rc |= expect_list_on_air(&state, "avoided and off", 1U, 1U, 0U, 1U);
        if (put_back) {
            test_rc |= expect_control_rc(
                "put back a", dsd_engine_trunk_scan_unavoid_target(&opts, &state, state.trunk_scan_session, "a", NULL),
                DSD_TRUNK_SCAN_CONTROL_OK);
        } else {
            test_rc |= expect_control_rc(
                "clear", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_CLEAR), 1);
        }
        test_rc |= expect_scan_control_publication(&state, "off, no longer avoided", 1U, 0U, 0U);
        test_rc |= expect_list_on_air(&state, "off, no longer avoided", 1U, 1U, 0U, 1U);
        test_rc |= expect_list_published(&state, "off, no longer avoided", 1, "a", 0U, 1U);
        test_rc |= expect_departure_due(&opts, &state, "off, no longer avoided", 2.20, 1);
        tick_at(&opts, &state, 2.20);
        test_rc |= expect_published_target(&state, "the departure the list still owes", "b", 2U, 2U);
        scan_lists_finish(&files, &opts, &state);
    }
    return test_rc;
}

/* A put back (issue #672) that gives the departure an alternate lets it run at once, as clearing the avoids does:
 * the receiver fell back onto the avoided a with b cooling down and c avoided, so the departure waits for b's
 * cooldown; putting c back makes it due now, the frame loop may yield for it, and the next tick leaves for c. */
static int
test_lists_departure_runs_at_once_when_a_put_back_gives_it_an_alternate(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (avoid_scan_init(k_avoid_body3, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path) != 0) {
        return 1;
    }
    int test_rc = expect_control_rc("retreat to c",
                                    dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_RETREAT), 0);
    test_rc |= expect_control_rc("avoid c, back to a",
                                 dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE), 0);
    test_rc |= expect_published_target(&state, "avoid c", "a", 1U, 3U);
    g_counting_tune_to_cc_failures_remaining = 1;
    trunk_scan_test_set_now(0.10);
    test_rc |= expect_control_rc("avoid a, b failing",
                                 dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE), 1);
    g_counting_tune_to_cc_failures_remaining = 0;
    test_rc |= expect_scan_control_publication(&state, "fell back onto a", 0U, 1U, 2U);
    test_rc |= expect_departure_due(&opts, &state, "b cooling, c avoided", 0.50, 0);
    tick_at(&opts, &state, 0.50);
    test_rc |= expect_published_target(&state, "b cooling, c avoided", "a", 1U, 3U);
    test_rc |= expect_control_rc(
        "put back c", dsd_engine_trunk_scan_unavoid_target(&opts, &state, state.trunk_scan_session, "c", NULL),
        DSD_TRUNK_SCAN_CONTROL_OK);
    test_rc |= expect_departure_due(&opts, &state, "c put back", 0.60, 1);
    tick_at(&opts, &state, 0.60);
    test_rc |= expect_published_target(&state, "the departure c made possible", "c", 3U, 3U);
    test_rc |= expect_scan_control_publication(&state, "the departure c made possible", 0U, 0U, 1U);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #697: a resume from a pause taken while the target on air was out of the rotation walks the targets after it
 * the advance would try, past one the DSP rate cannot filter; one whose retune fails leaves the scan paused, with the
 * manual session put back, and the next resume tries again rather than staying pinned. The publication survives the
 * pause (the lists and their states; no list on air while paused) and is taken down when the scan detaches. */
static int
test_lists_resume_walks_past_an_unreachable_target(void) {
    static const char* const names[] = {"a", "b"};
    /* c runs a tuner gain of its own and a the configured one: a refused landing on c may leave c's on the device. */
    static const char header[] = "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,options,rtl_gain\n";
    static const char second[] = "wide,nfm-conventional,155430000,,250,2000,,--nfm-bandwidth-hz 20000,\n"
                                 "c,nfm-conventional,156430000,,250,2000,,,10\n";
    static const char* const bodies[] = {"a,nfm-conventional,154430000,,250,2000,,,\n", second};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    g_scan_dsp_rate_hz = 16000;
    if (scan_lists_init(&files, header, names, bodies, NULL, 2, &opts, &state) != 0) {
        g_scan_dsp_rate_hz = 0;
        return 1;
    }
    int test_rc =
        expect_control_rc("hold", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
    g_scan_tune_to_freq_failures_remaining = 1;
    trunk_scan_test_set_now(0.10);
    test_rc |= expect_list_rc("a off, c failing", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_published_target(&state, "a off, c failing", "a", 1U, 3U);
    trunk_scan_test_set_now(0.20);
    if (dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_IN_PLACE) != 0) {
        test_rc = 1;
    }
    const uint32_t seq = state.trunk_scan_lists_seq;
    test_rc |= expect_list_on_air(&state, "paused", 0U, 0U, 0U, 2U);
    test_rc |= expect_list_published(&state, "paused", 1, "a", 0U, 1U);
    test_rc |= expect_list_published(&state, "paused", 2, "b", 1U, 2U);
    test_rc |= expect_departure_due(&opts, &state, "paused", 5.0, 0);

    /* c fails again: the resume leaves the scan paused, and the gain the stream must give back is c's, the target the
       refused landing installed, not that of a, which the scan stays paused at. */
    trunk_scan_test_set_now(2.50);
    g_scan_tune_to_freq_failures_remaining = 1;
    dsd_trunk_scan_leave_report report;
    const int refused = dsd_engine_trunk_scan_resume_ex_locked(&opts, &state, &report);
    g_scan_tune_to_freq_failures_remaining = 0;
    if (refused != -3 || state.trunk_scan_paused != 1U || dsd_engine_trunk_scan_active_index(&state) != 0U
        || report.restart_gain != 1) {
        DSD_FPRINTF(stderr,
                    "a resume whose landing fails: rc %d paused %u active %zu restart gain %d; want -3, paused, at a, "
                    "c's gain to give back\n",
                    refused, (unsigned)state.trunk_scan_paused, dsd_engine_trunk_scan_active_index(&state),
                    report.restart_gain);
        test_rc = 1;
    }
    trunk_scan_test_set_now(5.00);
    const int resumed = dsd_engine_trunk_scan_resume_locked(&opts, &state);
    if (resumed != 0 || state.trunk_scan_paused != 0U) {
        DSD_FPRINTF(stderr, "the next resume: rc %d paused %u\n", resumed, (unsigned)state.trunk_scan_paused);
        test_rc = 1;
    }
    test_rc |= expect_published_target(&state, "the resume past wide", "c", 3U, 3U);
    test_rc |= expect_list_on_air(&state, "the resume past wide", 2U, 0U, 2U, 2U);
    if (state.trunk_scan_lists_seq != seq) {
        DSD_FPRINTF(stderr, "a pause or resume moved lists_seq %u -> %u\n", (unsigned)seq,
                    (unsigned)state.trunk_scan_lists_seq);
        test_rc = 1;
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    if (state.trunk_scan_list_count != 0U || state.trunk_scan_lists_seq != 0U
        || state.trunk_scan_lists[0].name[0] != '\0' || state.trunk_scan_rotation_count != 0U
        || state.trunk_scan_active_list != 0U) {
        DSD_FPRINTF(stderr, "the lists stayed published after the scan detached\n");
        test_rc = 1;
    }
    scan_lists_finish(&files, &opts, &state);
    g_scan_dsp_rate_hz = 0;
    return test_rc;
}

/* Issue #697: what the session must be ready for counts every loaded target, a list that is off included, since it can
 * be switched on: the configured NFM width an nfm target there runs, and the tone detection it would need. Peer IDEN
 * sharing and the band-plan export read every target's snapshot, a list that is off included. */
static int
test_lists_global_predicates_and_idens_count_every_list(void) {
    static const char* const names[] = {"a", "b", "radio"};
    static const char* const bodies[] = {
        "a,p25-trunk,851000000,,250,,,\n",
        "b,p25-trunk,852000000,,250,,,\n",
        "n,nfm-conventional,154430000,,250,2000,,\n",
    };
    static const int off[] = {0, 0, 1};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, k_squelch_targets_header, names, bodies, off, 3, &opts, &state) != 0) {
        return 1;
    }
    int test_rc = 0;
    if (!dsd_engine_scan_runs_configured_nfm_width(&opts, &state) || !dsd_engine_scan_hears_tones(&opts, &state)) {
        DSD_FPRINTF(stderr, "an nfm target in a list that is off: configured width %d, tones %d; want both\n",
                    dsd_engine_scan_runs_configured_nfm_width(&opts, &state),
                    dsd_engine_scan_hears_tones(&opts, &state));
        test_rc = 1;
    }
    /* a learns an identifier on system A, then its list goes off while b is on air. */
    state.p2_wacn = k_sys_a_wacn;
    state.p2_sysid = k_sys_a_sysid;
    seed_iden_entry(&state.p25_iden_fdma[1], 170201250, 1, k_sys_a_wacn, k_sys_a_sysid, 2);
    state.p25_chan_tdma_explicit[1] |= 0x01;
    tick_at(&opts, &state, 0.26);
    test_rc |= expect_published_target(&state, "rotation to b", "b", 2U, 3U);
    test_rc |= expect_list_rc("a off", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    char out_path[DSD_TEST_PATH_MAX];
    const int fd = dsd_test_mkstemp(out_path, sizeof out_path, "dsdneo_lists_bandplan");
    if (fd < 0) {
        scan_lists_finish(&files, &opts, &state);
        return 1;
    }
    (void)dsd_close(fd);
    const int rows = dsd_engine_p25_bandplan_export(&opts, &state, out_path);
    if (rows != 1) {
        DSD_FPRINTF(stderr, "band-plan export with a's list off wrote %d rows, want a's 1\n", rows);
        test_rc = 1;
    }
    (void)remove(out_path);
    /* b turns out to be a site of system A: a's identifier reaches it from a's snapshot. */
    state.p2_wacn = k_sys_a_wacn;
    state.p2_sysid = k_sys_a_sysid;
    tick_at(&opts, &state, 0.30);
    test_rc |= expect_iden_entry("b fdma[1] from a list that is off", &state.p25_iden_fdma[1], 170201250, k_sys_a_wacn,
                                 k_sys_a_sysid, 1);
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* Issue #697: two lists may hold one nfm channel under different tone lists. They rotate like any two targets, but
 * traffic one copy's tone policy rejects never moves to the other copy: with only the two it stays, muted; with a third
 * target it moves there, past the copy. */
static int
test_lists_tone_rejection_passes_over_a_copy(void) {
    static const char* const names[] = {"fire", "ems", "other"};
    static const char* const bodies[] = {
        "fire,nfm-conventional,154430000,,250,2000,,--tone-allow 100.0\n",
        "ems,nfm-conventional,154430000,,250,2000,,--tone-allow 131.8\n",
        "dmr,dmr-conventional,461000000,,250,250,\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    int test_rc = 0;
    for (int lists = 2; lists <= 3; lists++) {
        scan_list_files files;
        if (scan_lists_init_in(&files, k_squelch_targets_header, names, bodies, NULL, lists, &opts, &state,
                               scan_lists_nfm_session)
            != 0) {
            return 1;
        }
        if (lists == 2) {
            /* Idle copies rotate. */
            tick_at(&opts, &state, 0.30);
            test_rc |= expect_published_target(&state, "the copies rotate", "ems", 2U, 2U);
            tick_at(&opts, &state, 0.56);
            test_rc |= expect_published_target(&state, "the copies rotate back", "fire", 1U, 2U);
        }
        /* Rejected traffic on fire: tick after tick with only the copy, one tick (the next one's dwell would move on)
           with a third target. */
        const double start = lists == 2 ? 0.60 : 0.10;
        g_scan_dsp_rate_reads = 0;
        const int ticks = lists == 2 ? 4 : 1;
        for (int tick = 0; tick < ticks; tick++) {
            publish_tone_gate(&state, DSD_ANALOG_TONE_GATE_REJECTED);
            tick_at(&opts, &state, start + (0.10 * tick));
        }
        /* With only the copy there is nowhere to go, so no advance is even tried: each tick asks the question alone
           (its walk reads the DSP rate once, beside the one read of the entry reasons' publication), where an advance
           would read it again for its own walk. */
        if (lists == 2 && g_scan_dsp_rate_reads != 2 * ticks) {
            DSD_FPRINTF(stderr, "tone rejection with only a copy: %d rate reads in %d ticks, want two a tick\n",
                        g_scan_dsp_rate_reads, ticks);
            test_rc = 1;
        }
        const char* want = lists == 2 ? "fire" : "dmr";
        if (strcmp(state.trunk_scan_active_id, want) != 0) {
            DSD_FPRINTF(stderr, "tone rejection on fire with %d lists landed on '%s', want '%s'\n", lists,
                        state.trunk_scan_active_id, want);
            test_rc = 1;
        }
        scan_lists_finish(&files, &opts, &state);
        DSD_MEMSET(&state.analog_rx, 0, sizeof(state.analog_rx));
    }
    return test_rc;
}

/* Issue #697: digital receive rejection keeps a copy as somewhere to go: two lists holding one DMR repeater with
 * complementary color-code filters hand the traffic one rejects to the other. */
static int
test_lists_receive_rejection_hands_over_to_a_copy(void) {
    static const char* const names[] = {"cc2", "cc3"};
    static const char* const bodies[] = {
        "x,dmr-conventional,461000000,,250,250,,--dcc-allow 2\n",
        "y,dmr-conventional,461000000,,250,250,,--dcc-allow 3\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, k_squelch_targets_header, names, bodies, NULL, 2, &opts, &state) != 0) {
        return 1;
    }
    int test_rc = expect_published_target(&state, "start", "x", 1U, 2U);
    state.synctype = DSD_SYNC_DMR_BS_VOICE_POS;
    state.dmr_color_code = 3;
    trunk_scan_test_set_now(5.0);
    if (!dsd_engine_trunk_scan_receive_expired(&opts, &state)) {
        DSD_FPRINTF(stderr, "color code 3 on x: the frame loop was not let go to the copy that admits it\n");
        test_rc = 1;
    }
    tick_at(&opts, &state, 5.0);
    test_rc |= expect_published_target(&state, "receive rejection on x", "y", 2U, 2U);
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* Issue #697: once a failed retune's cooldown has run out while another target can take the
 * receiver, the retry in place waits for the rotation and asks again a cooldown later, not at every tick (each asking
 * walks the targets, which reads the DSP rate once). A call being followed keeps a past its dwell meanwhile. */
static int
test_due_retry_with_an_alternate_walks_once_a_cooldown(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_control_init("a,p25-trunk,851000000,,250,,\n"
                          "b,p25-trunk,852000000,,250,,\n"
                          "c,p25-trunk,853000000,,250,,\n",
                          &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        return 1;
    }
    int test_rc = 0;
    /* a's dwell runs out; b and c fail, and so does the fallback onto a: a cools down beside them. */
    g_counting_tune_to_cc_failures_remaining = 3;
    tick_at(&opts, &state, 0.30);
    g_counting_tune_to_cc_failures_remaining = 0;
    test_rc |= expect_published_target(&state, "everything failed", "a", 1U, 3U);
    g_scan_dsp_rate_reads = 0;
    g_counting_tune_to_cc_calls = 0;
    for (int tick = 0; tick < 20; tick++) {
        opts.trunk_is_tuned = 1;
        tick_at(&opts, &state, 2.35 + (0.05 * tick));
    }
    /* Each tick also reads the rate once for the entry reasons' publication (issue #644): 20 of the reads. */
    if (g_scan_dsp_rate_reads - 20 != 1 || g_counting_tune_to_cc_calls != 0) {
        DSD_FPRINTF(stderr, "a due retry with an alternate: %d walks and %d tunes in 1 s, want 1 and 0\n",
                    g_scan_dsp_rate_reads - 20, g_counting_tune_to_cc_calls);
        test_rc = 1;
    }
    /* The operator's hold makes the retry in place owed at once: the wait for the rotation does not outlast it. */
    trunk_scan_test_set_now(3.40);
    test_rc |=
        expect_control_rc("hold", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
    opts.trunk_is_tuned = 1;
    tick_at(&opts, &state, 3.45);
    if (g_counting_tune_to_cc_calls != 1 || g_counting_tune_to_cc_freq != 851000000L) {
        DSD_FPRINTF(stderr, "a held target's due retry waited for the rotation's re-check: %d tunes, want 1 on a\n",
                    g_counting_tune_to_cc_calls);
        test_rc = 1;
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #697: one advance reads the DSP rate once for its whole candidate walk, however many
 * targets it passes over (here three avoided ones), not once per candidate. */
static int
test_advance_reads_the_rate_once_per_walk(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_control_init("a,p25-trunk,851000000,,250,,\n"
                          "b,p25-trunk,852000000,,250,,\n"
                          "c,p25-trunk,853000000,,250,,\n"
                          "d,p25-trunk,854000000,,250,,\n"
                          "e,p25-trunk,855000000,,250,,\n",
                          &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        return 1;
    }
    int test_rc = 0;
    for (int i = 0; i < 3; i++) {
        test_rc |= expect_control_rc(
            "avoid", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE), 0);
    }
    test_rc |= expect_published_target(&state, "three avoided", "d", 4U, 5U);
    g_scan_dsp_rate_reads = 0;
    test_rc |=
        expect_control_rc("advance", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE), 0);
    test_rc |= expect_published_target(&state, "advance", "e", 5U, 5U);
    const int one_hop = g_scan_dsp_rate_reads;
    g_scan_dsp_rate_reads = 0;
    test_rc |= expect_control_rc("advance past a, b, c",
                                 dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE), 0);
    test_rc |= expect_published_target(&state, "advance past a, b, c", "d", 4U, 5U);
    if (g_scan_dsp_rate_reads != one_hop) {
        DSD_FPRINTF(stderr, "an advance past three avoided targets read the rate %d times, a plain one %d\n",
                    g_scan_dsp_rate_reads, one_hop);
        test_rc = 1;
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #697: a failed preparation cools its target down as a failed retune does. A dwell advance whose
 * switch to b cannot be prepared (b's keys do not allocate) moves on to c, and the rotation then passes b over until
 * its cooldown ends instead of trying it again at the next dwell. */
static int
test_dwell_advance_cools_a_target_whose_switch_fails_to_prepare(void) {
    static const char* const names[] = {"targets"};
    static const char* const bodies[] = {"a,p25-trunk,851000000,,250,,,\n"
                                         "b,p25-trunk,852000000,,250,,,-K keys.csv\n"
                                         "c,p25-trunk,853000000,,250,,,\n"};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    char keys[DSD_TEST_PATH_MAX] = "";
    int test_rc = 0;
    if (scan_list_files_write(&files, k_squelch_targets_header, names, bodies, 1) != 0
        || dsd_test_path_join(keys, sizeof keys, files.dir, "keys.csv") != 0
        || write_text_file(keys, "key id(hex),key value (hex)\n0010,AAAAAAAAAAAAAAAA\n") != 0) {
        test_rc = 1;
    } else {
        reset_scan_opts_state(&opts, &state);
        scan_list_files_to_opts(&files, NULL, &opts);
        char err[512] = {0};
        trunk_scan_test_set_now(0.0);
        if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0) {
            DSD_FPRINTF(stderr, "prepare cooldown init: %s\n", err);
            test_rc = 1;
        } else {
            dsd_key_set_test_alloc_fail_after(0);
            tick_at(&opts, &state, 0.30);
            dsd_key_set_test_alloc_fail_after(-1);
            test_rc |= expect_published_target(&state, "b unprepared, on to c", "c", 3U, 3U);
            tick_at(&opts, &state, 0.56);
            test_rc |= expect_published_target(&state, "rotation to a", "a", 1U, 3U);
            tick_at(&opts, &state, 0.82);
            test_rc |= expect_published_target(&state, "b still cooling down", "c", 3U, 3U);
            tick_at(&opts, &state, 2.40);
            tick_at(&opts, &state, 2.66);
            test_rc |= expect_published_target(&state, "b after its cooldown", "b", 2U, 3U);
        }
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    if (keys[0] != '\0') {
        (void)remove(keys);
    }
    scan_list_files_remove(&files);
    return test_rc;
}

/* Issue #697: a departure that did not move waits for the soonest cooldown among its alternates, not a flat
 * cooldown from its own attempt. c cooled down from a failed retune at 0.10; at 1.80 list a goes off and b's switch
 * cannot be prepared (b cools until 3.80); the departure leaves for c as c's cooldown ends at 2.10. */
static int
test_lists_departure_waits_for_the_soonest_cooldown(void) {
    static const char* const names[] = {"a", "b"};
    static const char* const bodies[] = {"a,p25-trunk,851000000,,250,,,\n",
                                         "c,p25-trunk,853000000,,250,,,\n"
                                         "b,p25-trunk,852000000,,250,,,-K keys.csv\n"};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    char keys[DSD_TEST_PATH_MAX] = "";
    int test_rc = 0;
    if (scan_list_files_write(&files, k_squelch_targets_header, names, bodies, 2) != 0
        || dsd_test_path_join(keys, sizeof keys, files.dir, "keys.csv") != 0
        || write_text_file(keys, "key id(hex),key value (hex)\n0010,AAAAAAAAAAAAAAAA\n") != 0) {
        test_rc = 1;
    } else {
        reset_scan_opts_state(&opts, &state);
        scan_list_files_to_opts(&files, NULL, &opts);
        char err[512] = {0};
        trunk_scan_test_set_now(0.0);
        if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0) {
            DSD_FPRINTF(stderr, "soonest cooldown init: %s\n", err);
            test_rc = 1;
        } else {
            test_rc |= expect_control_rc(
                "hold", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
            /* c fails (cooling until 2.10) and the step lands on b; the next one goes back to a, past c. */
            g_counting_tune_to_cc_failures_remaining = 1;
            trunk_scan_test_set_now(0.10);
            test_rc |=
                expect_control_rc("advance past a failing c",
                                  dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE), 0);
            g_counting_tune_to_cc_failures_remaining = 0;
            trunk_scan_test_set_now(0.15);
            test_rc |= expect_control_rc(
                "advance to a", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE), 0);
            test_rc |= expect_published_target(&state, "back on a", "a", 1U, 3U);
            dsd_key_set_test_alloc_fail_after(0);
            trunk_scan_test_set_now(1.80);
            test_rc |= expect_list_rc("a off, b unprepared", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
            dsd_key_set_test_alloc_fail_after(-1);
            test_rc |= expect_published_target(&state, "a off, nowhere yet", "a", 1U, 3U);
            test_rc |= expect_departure_due(&opts, &state, "c's cooldown", 2.05, 0);
            test_rc |= expect_departure_due(&opts, &state, "c's cooldown end", 2.15, 1);
            tick_at(&opts, &state, 2.15);
            test_rc |= expect_published_target(&state, "the departure at c's cooldown end", "c", 2U, 3U);
        }
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    if (keys[0] != '\0') {
        (void)remove(keys);
    }
    scan_list_files_remove(&files);
    return test_rc;
}

/* The startup park's fallback: with every target in the rotation skipped for its width (list one, whose target is
 * receivable, starts off), the scan starts on the first one in the rotation; the front end refuses that park before
 * any backend moves, with no "retune failed" line of the coordinator's own, and the advance after it finds nowhere to
 * go. */
static int
test_lists_start_on_an_unreachable_target_when_nothing_else_is_on(void) {
    static const char* const names[] = {"one", "two"};
    static const char* const bodies[] = {"a,nfm-conventional,154430000,,250,2000,,\n",
                                         "wide,nfm-conventional,155430000,,250,2000,,--nfm-bandwidth-hz 20000\n"};
    static const int off[] = {1, 0};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_list_files_write(&files, k_squelch_targets_header, names, bodies, 2) != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    reset_scan_opts_state(&opts, &state);
    scan_list_files_to_opts(&files, off, &opts);
    dsd_test_capture_stderr cap;
    char buf[8192] = {0};
    if (dsd_test_capture_stderr_begin(&cap, "trunkscanstartfallback") != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    g_scan_tune_refuses_unfit_width = 1;
    g_scan_tune_width_refusals = 0;
    g_scan_dsp_rate_hz = 16000;
    char err[512] = {0};
    trunk_scan_test_set_now(0.0);
    const int rc = dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err);
    const size_t started_on = dsd_engine_trunk_scan_active_index(&state);
    const int refusals = g_scan_tune_width_refusals;
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    (void)dsd_test_capture_stderr_end(&cap);
    (void)dsd_test_capture_stderr_read(&cap, buf, sizeof buf);
    g_scan_tune_refuses_unfit_width = 0;
    g_scan_dsp_rate_hz = 0;
    trunk_scan_test_clear_now();
    scan_list_files_remove(&files);
    const int failed = count_text(buf, "Trunk scan target 'wide' retune failed");
    if (rc != 0 || started_on != 1U || refusals != 1 || failed != 0) {
        DSD_FPRINTF(stderr,
                    "start fallback (rc=%d %s): started on %zu, refused %d, retune-failed %d; want 1, 1, 0\n%s\n", rc,
                    err, started_on, refusals, failed, buf);
        return 1;
    }
    return 0;
}

/* A list's name is its file's name without the extension, the extension found on the whole name however long, then
 * cut to fit: a long name with a dot inside keeps what precedes the extension, not what precedes the inner dot. */
static int
test_lists_long_file_names_keep_their_stem(void) {
    char name[160];
    DSD_SNPRINTF(name, sizeof name, "a.b");
    DSD_MEMSET(name + 3, 'x', 140U);
    name[143] = '\0';
    const char* names[] = {"short", name};
    static const char* const bodies[] = {"s,p25-trunk,851000000,,250,,\n", "l,p25-trunk,852000000,,250,,\n"};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
        return 1;
    }
    char want[DSD_TRUNK_SCAN_LIST_NAME_SIZE];
    DSD_SNPRINTF(want, sizeof want, "%s", name);
    const int test_rc = expect_list_published(&state, "a long file name", 2, want, 1U, 1U);
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* A list switch publishes the scan timing it leaves while it still holds the P25 SM tick guard, as the controls do: the
 * timing reads the parked target's P25 machine (here the hangtime of the call it follows), which the watchdog changes
 * under that guard. */
static int
test_lists_switch_publishes_timing_under_the_guard(void) {
    static const char* const names[] = {"security", "hospital"};
    static const char* const bodies[] = {"s1,p25-trunk,851000000,,250,,\n", "h1,p25-trunk,852000000,,250,,\n"};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
        return 1;
    }
    int test_rc = 0;
    opts.trunk_is_tuned = 1;
    tick_at(&opts, &state, 0.10);
    test_rc |= expect_scan_timing(&state, "a call followed", DSD_SCAN_STAY_CALL_FOLLOW, -1.0, 250U, 0U);
    const int reads = g_p25_hangtime_reads;
    const int unguarded = g_p25_hangtime_unguarded_reads;
    state.scan_timing.reason = 0xEEU;
    test_rc |= expect_list_rc("hospital off", list_set(&opts, &state, 2, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_scan_timing(&state, "hospital off", DSD_SCAN_STAY_CALL_FOLLOW, -1.0, 250U, 0U);
    if (g_p25_hangtime_reads == reads || g_p25_hangtime_unguarded_reads != unguarded) {
        DSD_FPRINTF(stderr, "a list switch read the P25 machine for its timing %d times, %d without the guard\n",
                    g_p25_hangtime_reads - reads, g_p25_hangtime_unguarded_reads - unguarded);
        test_rc = 1;
    }
    if (g_p25_tick_guard_depth != 0) {
        DSD_FPRINTF(stderr, "a list switch left the P25 guard depth=%d\n", g_p25_tick_guard_depth);
        test_rc = 1;
    }
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* The alternate walk the visit cap and the receive expiry run at every burst boundary looks only at the targets of the
 * lists that are on: the far list's forty targets are never looked at while it is off, though one of them, f20, is
 * also the near list's, so it stays in the rotation at its own place (the start parks on it) and is the alternate the
 * cap finds from n1 (issue #697). */
static int
test_lists_alternate_walk_skips_a_list_off(void) {
    static char far_body[40 * 40];
    size_t used = 0U;
    for (int i = 0; i < 40; i++) {
        used += (size_t)DSD_SNPRINTF(far_body + used, sizeof far_body - used, "f%d,p25-trunk,%d,,250,,\n", i,
                                     851000000 + (i * 12500));
    }
    static const char* const names[] = {"far", "near"};
    const char* bodies[] = {far_body, "n1,p25-trunk,860000000,,250,,\nf20,p25-trunk,851250000,,250,,\n"};
    static const int off[] = {1, 0};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_list_files_write(&files, k_header, names, bodies, 2) != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    reset_scan_opts_state(&opts, &state);
    scan_list_files_to_opts(&files, off, &opts);
    opts.scan_max_visit_ms = 1000;
    char err[512] = {0};
    trunk_scan_test_set_now(0.0);
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0) {
        DSD_FPRINTF(stderr, "alternate walk lists init: %s\n", err);
        scan_list_files_remove(&files);
        return 1;
    }
    /* f20 is the far list's (its owner, off) and the near list's: in the rotation, first of it in target order. */
    int test_rc = expect_published_target(&state, "start", "f20", 21U, 41U);
    test_rc |= expect_list_on_air(&state, "start", 2U, 0U, 1U, 2U);
    /* f20 on air and n1 its alternate: the walk looks at the near list alone. */
    trunk_scan_test_set_now(0.10);
    size_t steps = trunk_scan_test_alternate_walk_off_list_steps();
    (void)dsd_engine_trunk_scan_visit_expired(&opts, &state);
    (void)dsd_engine_trunk_scan_receive_expired(&opts, &state);
    steps = trunk_scan_test_alternate_walk_off_list_steps() - steps;
    if (steps != 0U) {
        DSD_FPRINTF(stderr, "the alternate walk looked at %zu targets of the far list while it was off\n", steps);
        test_rc = 1;
    }
    /* The cap runs out against n1. */
    trunk_scan_test_set_now(1.20);
    if (!dsd_engine_trunk_scan_visit_expired(&opts, &state)) {
        DSD_FPRINTF(stderr, "the visit cap did not run out with n1 to go to\n");
        test_rc = 1;
    }
    /* On n1, the one alternate is f20, whose owner list is off: the walk finds it, and still looks at nothing only the
       far list holds. */
    test_rc |=
        expect_control_rc("advance to n1", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE),
                          DSD_TRUNK_SCAN_CONTROL_OK);
    test_rc |= expect_published_target(&state, "advance to n1", "n1", 41U, 41U);
    test_rc |= expect_list_on_air(&state, "advance to n1", 2U, 0U, 2U, 2U);
    trunk_scan_test_set_now(2.40);
    steps = trunk_scan_test_alternate_walk_off_list_steps();
    if (!dsd_engine_trunk_scan_visit_expired(&opts, &state)) {
        DSD_FPRINTF(stderr, "the visit cap did not run out with f20, held by the near list, to go to\n");
        test_rc = 1;
    }
    steps = trunk_scan_test_alternate_walk_off_list_steps() - steps;
    if (steps != 0U) {
        DSD_FPRINTF(stderr, "the alternate walk from n1 looked at %zu targets only the far list holds\n", steps);
        test_rc = 1;
    }
    /* Back on, the far list's targets are alternates again; off again, they are passed over again. */
    test_rc |= expect_list_rc("far on", list_set(&opts, &state, 1, 1), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_list_rc("far off again", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    trunk_scan_test_set_now(2.50);
    steps = trunk_scan_test_alternate_walk_off_list_steps();
    (void)dsd_engine_trunk_scan_visit_expired(&opts, &state);
    steps = trunk_scan_test_alternate_walk_off_list_steps() - steps;
    if (steps != 0U) {
        DSD_FPRINTF(stderr, "the alternate walk looked at %zu targets of the far list off again\n", steps);
        test_rc = 1;
    }
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* Every list holding the target on air, as published (bit N-1: list N). */
static int
expect_active_lists(const dsd_state* state, const char* stage, unsigned mask) {
    if (state->trunk_scan_active_lists != mask) {
        DSD_FPRINTF(stderr, "lists of the target on air after %s: 0x%x, want 0x%x\n", stage,
                    (unsigned)state->trunk_scan_active_lists, mask);
        return 1;
    }
    return 0;
}

/* The target on air stayed through a switch of one of its lists: no call ended, no carrier handed back, none owed. */
static int
expect_stayed_on_air(const dsd_opts* opts, const dsd_state* state, const char* stage, int ends_before, double now_m) {
    int rc = 0;
    if (g_explicit_call_ends != ends_before || g_release_seen_target[0] != '\0' || opts->trunk_is_tuned != 1) {
        DSD_FPRINTF(stderr, "%s: %d calls ended, carrier released under '%s', tuned %d; want none, tuned 1\n", stage,
                    g_explicit_call_ends - ends_before, g_release_seen_target, opts->trunk_is_tuned);
        rc = 1;
    }
    rc |= expect_departure_due(opts, state, stage, now_m, 0);
    return rc;
}

/* A target two lists hold (issue #697): with both on it is visited once a rotation, at its owner's place; with its
 * owner off and the other on it stays in the rotation at that place; the readout counts distinct targets. Switching
 * off one of its lists while it is on air keeps it there, its call going on; switching off the last of its lists that
 * is on leaves it at once, as for any target. The list named on air is the lowest-numbered one on that holds it. */
static int
test_lists_shared_target_rotation_and_switches(void) {
    static const char* const names[] = {"conv", "low", "fav"};
    static const char* const bodies[] = {
        "a1,p25-trunk,851000000,,250,,\nROK,p25-trunk,853000000,,250,,\na2,p25-trunk,852000000,,250,,\n",
        "b1,p25-trunk,854000000,,250,,\nROK,p25-trunk,853000000,,250,,\n",
        "c1,p25-trunk,857000000,,250,,\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, NULL, 3, &opts, &state) != 0) {
        return 1;
    }
    /* Targets a1 ROK a2 | b1 | c1. */
    int test_rc = expect_published_target(&state, "start", "a1", 1U, 5U);
    test_rc |= expect_list_on_air(&state, "start", 1U, 0U, 1U, 5U);
    test_rc |= expect_list_published(&state, "start", 2, "low", 1U, 2U);

    static const struct {
        double at;
        const char* id;
        unsigned identity;
        unsigned list;
        unsigned ordinal;
    } k_all_on[] = {
        {0.30, "ROK", 2U, 1U, 2U}, {0.56, "a2", 3U, 1U, 3U}, {0.82, "b1", 4U, 2U, 4U},
        {1.08, "c1", 5U, 3U, 5U},  {1.34, "a1", 1U, 1U, 1U},
    };

    for (size_t i = 0; i < sizeof k_all_on / sizeof k_all_on[0]; i++) {
        tick_at(&opts, &state, k_all_on[i].at);
        test_rc |= expect_published_target(&state, "every list on", k_all_on[i].id, k_all_on[i].identity, 5U);
        test_rc |= expect_list_on_air(&state, "every list on", k_all_on[i].list, 0U, k_all_on[i].ordinal, 5U);
    }

    /* conv off on a1: a1 leaves; ROK, conv's but low's too, is next, and the rotation keeps it at conv's place. */
    trunk_scan_test_set_now(1.40);
    test_rc |= expect_list_rc("conv off", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_published_target(&state, "conv off", "ROK", 2U, 5U);
    test_rc |= expect_list_on_air(&state, "conv off", 2U, 0U, 1U, 3U);
    test_rc |= expect_active_lists(&state, "conv off", 0x3U);

    static const struct {
        double at;
        const char* id;
        unsigned identity;
        unsigned list;
        unsigned ordinal;
    } k_conv_off[] = {{1.70, "b1", 4U, 2U, 2U}, {1.96, "c1", 5U, 3U, 3U}, {2.22, "ROK", 2U, 2U, 1U}};

    for (size_t i = 0; i < sizeof k_conv_off / sizeof k_conv_off[0]; i++) {
        tick_at(&opts, &state, k_conv_off[i].at);
        test_rc |= expect_published_target(&state, "conv off", k_conv_off[i].id, k_conv_off[i].identity, 5U);
        test_rc |= expect_list_on_air(&state, "conv off", k_conv_off[i].list, 0U, k_conv_off[i].ordinal, 3U);
    }

    /* On ROK with every list on, a call in progress: switching off either of its lists keeps it, and the call. */
    trunk_scan_test_set_now(2.25);
    test_rc |= expect_list_rc("conv on", list_set(&opts, &state, 1, 1), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_list_on_air(&state, "conv on", 1U, 0U, 2U, 5U);
    opts.trunk_is_tuned = 1;
    test_rc |= seed_active_call_row(&state, 1001U, 2002U, 2.25);
    const int ends_before = g_explicit_call_ends;
    g_release_seen_target[0] = '\0';
    trunk_scan_test_set_now(2.30);
    test_rc |= expect_list_rc("low off on ROK", list_set(&opts, &state, 2, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_published_target(&state, "low off on ROK", "ROK", 2U, 5U);
    test_rc |= expect_list_on_air(&state, "low off on ROK", 1U, 0U, 2U, 4U);
    test_rc |= expect_stayed_on_air(&opts, &state, "low off on ROK", ends_before, 2.30);
    test_rc |= expect_list_rc("low on again", list_set(&opts, &state, 2, 1), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_list_rc("conv off on ROK", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_published_target(&state, "conv off on ROK", "ROK", 2U, 5U);
    test_rc |= expect_list_on_air(&state, "conv off on ROK", 2U, 0U, 1U, 3U);
    test_rc |= expect_stayed_on_air(&opts, &state, "conv off on ROK", ends_before, 2.30);
    dsd_call_snapshot call;
    if (dsd_call_state_get(&state, 0U, &call) <= 0 || call.phase != DSD_CALL_PHASE_ACTIVE) {
        DSD_FPRINTF(stderr, "ROK's call did not go on through the switches of its lists\n");
        test_rc = 1;
    }

    /* low, the last of ROK's lists on, off: ROK leaves at once, its call ending under its name. */
    trunk_scan_test_set_now(2.35);
    test_rc |= expect_list_rc("low off, ROK's last", list_set(&opts, &state, 2, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_published_target(&state, "low off, ROK's last", "c1", 5U, 5U);
    test_rc |= expect_list_on_air(&state, "low off, ROK's last", 3U, 0U, 1U, 1U);
    test_rc |= expect_active_lists(&state, "low off, ROK's last", 0x4U);
    if (g_explicit_call_ends != ends_before + 1 || strcmp(g_release_seen_target, "ROK") != 0) {
        DSD_FPRINTF(stderr, "ROK's last list off: %d calls ended under '%s', want 1 under 'ROK'\n",
                    g_explicit_call_ends - ends_before, g_release_seen_target);
        test_rc = 1;
    }

    /* A pause publishes no list on air, nor its lists. */
    test_rc |= expect_list_rc("every list on", list_set(&opts, &state, DSD_TRUNK_SCAN_LIST_ALL, 1),
                              DSD_TRUNK_SCAN_LIST_SET_OK);
    if (dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_IN_PLACE) != 0) {
        DSD_FPRINTF(stderr, "shared lists: pause failed\n");
        test_rc = 1;
    }
    test_rc |= expect_list_on_air(&state, "paused", 0U, 0U, 0U, 5U);
    test_rc |= expect_active_lists(&state, "paused", 0x0U);
    scan_lists_finish(&files, &opts, &state);
    test_rc |= expect_active_lists(&state, "shutdown", 0x0U);
    return test_rc;
}

/* A list whose every target an earlier list holds owns none (issue #697): with that earlier list off, its targets are
 * all the rotation has and the rotation goes over them alone. A toggle's last-usable refusal counts the lists that
 * would be on: a target the list switched off shares with one that stays on counts, one only it holds does not, and
 * one avoided (in every list at once) does not. Put back by its id, it counts again. */
static int
test_lists_wholly_shared_list_and_last_usable(void) {
    static const char* const names[] = {"conv", "low"};
    static const char* const bodies[] = {
        "a1,p25-trunk,851000000,,250,,\nROK,p25-trunk,853000000,,250,,\na2,p25-trunk,852000000,,250,,\n",
        "ROK,p25-trunk,853000000,,250,,\na1,p25-trunk,851000000,,250,,\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
        return 1;
    }
    static const size_t low_members[] = {1U, 0U};
    int test_rc = expect_list_layout(&state, 1, 3U, 0U, low_members, 2U);
    test_rc |= expect_published_target(&state, "start", "a1", 1U, 3U);
    test_rc |= expect_list_on_air(&state, "start", 1U, 0U, 1U, 3U);
    test_rc |= expect_active_lists(&state, "start", 0x3U);

    /* conv off on a1: low holds a1 and ROK, so the switch is taken and a1 stays on air. */
    const int ends_before = g_explicit_call_ends;
    g_release_seen_target[0] = '\0';
    opts.trunk_is_tuned = 1;
    trunk_scan_test_set_now(0.10);
    test_rc |= expect_list_rc("conv off", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_published_target(&state, "conv off", "a1", 1U, 3U);
    test_rc |= expect_list_on_air(&state, "conv off", 2U, 0U, 1U, 2U);
    test_rc |= expect_stayed_on_air(&opts, &state, "conv off", ends_before, 0.10);
    opts.trunk_is_tuned = 0;
    /* The rotation goes over low's targets, both conv's own: a2 is passed over. */
    tick_at(&opts, &state, 0.40);
    test_rc |= expect_published_target(&state, "low alone", "ROK", 2U, 3U);
    test_rc |= expect_list_on_air(&state, "low alone", 2U, 0U, 2U, 2U);
    tick_at(&opts, &state, 0.70);
    test_rc |= expect_published_target(&state, "low alone again", "a1", 1U, 3U);
    test_rc |=
        expect_list_rc("low off, the last list", list_set(&opts, &state, 2, 0), DSD_TRUNK_SCAN_LIST_SET_REFUSED_LAST);

    /* Both on, a1 and ROK avoided: they are avoided in both lists, so switching conv off would leave only targets the
       rotation passes over, though conv holds a2. */
    test_rc |= expect_list_rc("conv on", list_set(&opts, &state, 1, 1), DSD_TRUNK_SCAN_LIST_SET_OK);
    trunk_scan_test_set_now(0.80);
    test_rc |=
        expect_control_rc("avoid a1", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE),
                          DSD_TRUNK_SCAN_CONTROL_OK);
    test_rc |= expect_published_target(&state, "avoid a1", "ROK", 2U, 3U);
    test_rc |= expect_control_rc("avoid ROK",
                                 dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE),
                                 DSD_TRUNK_SCAN_CONTROL_OK);
    test_rc |= expect_published_target(&state, "avoid ROK", "a2", 3U, 3U);
    if (state.trunk_scan_avoided_count != 2U) {
        DSD_FPRINTF(stderr, "a1 and ROK avoided: %u avoided, want 2\n", (unsigned)state.trunk_scan_avoided_count);
        test_rc = 1;
    }
    test_rc |= expect_list_rc("conv off, low's targets avoided", list_set(&opts, &state, 1, 0),
                              DSD_TRUNK_SCAN_LIST_SET_REFUSED_LAST);
    /* ROK put back by its id: back in both lists, so conv off is taken and a2 leaves for it. */
    test_rc |= expect_control_rc(
        "put back ROK", dsd_engine_trunk_scan_unavoid_target(&opts, &state, state.trunk_scan_session, "ROK", NULL),
        DSD_TRUNK_SCAN_CONTROL_OK);
    test_rc |= expect_list_rc("conv off, ROK put back", list_set(&opts, &state, 1, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_published_target(&state, "conv off, ROK put back", "ROK", 2U, 3U);
    test_rc |= expect_list_on_air(&state, "conv off, ROK put back", 2U, 0U, 2U, 2U);
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* A shared target avoided while only one of its lists is on (issue #697): it leaves the rotation, and stays out of it
 * when its other list comes on, since the avoid is the target's, not a list's; put back by its id, the rotation
 * reaches it again. */
static int
test_lists_avoid_a_shared_target_with_one_of_its_lists_on(void) {
    static const char* const names[] = {"conv", "low"};
    static const char* const bodies[] = {
        "a1,p25-trunk,851000000,,250,,\nROK,p25-trunk,853000000,,250,,\n",
        "ROK,p25-trunk,853000000,,250,,\nb1,p25-trunk,854000000,,250,,\n",
    };
    static const int off[] = {1, 0};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, off, 2, &opts, &state) != 0) {
        return 1;
    }
    /* Targets a1 ROK | b1; conv off, so the rotation is ROK, b1. */
    int test_rc = expect_published_target(&state, "start", "ROK", 2U, 3U);
    test_rc |= expect_list_on_air(&state, "start", 2U, 0U, 1U, 2U);
    trunk_scan_test_set_now(0.10);
    test_rc |= expect_control_rc("avoid ROK",
                                 dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE),
                                 DSD_TRUNK_SCAN_CONTROL_OK);
    test_rc |= expect_published_target(&state, "avoid ROK", "b1", 3U, 3U);
    if (state.trunk_scan_avoided_count != 1U) {
        DSD_FPRINTF(stderr, "ROK avoided: %u avoided, want 1\n", (unsigned)state.trunk_scan_avoided_count);
        test_rc = 1;
    }
    /* Out of the rotation: nowhere else to go, b1 stays. */
    tick_at(&opts, &state, 0.40);
    test_rc |= expect_published_target(&state, "ROK avoided, low alone", "b1", 3U, 3U);
    /* conv on: ROK is conv's too, and still avoided, so the rotation goes a1, b1 and passes it over. */
    trunk_scan_test_set_now(0.45);
    test_rc |= expect_list_rc("conv on", list_set(&opts, &state, 1, 1), DSD_TRUNK_SCAN_LIST_SET_OK);

    static const struct {
        double at;
        const char* id;
        unsigned identity;
    } k_avoided[] = {{0.75, "a1", 1U}, {1.05, "b1", 3U}, {1.35, "a1", 1U}};

    for (size_t i = 0; i < sizeof k_avoided / sizeof k_avoided[0]; i++) {
        tick_at(&opts, &state, k_avoided[i].at);
        test_rc |= expect_published_target(&state, "ROK avoided, both on", k_avoided[i].id, k_avoided[i].identity, 3U);
    }
    /* Put back by its id: the rotation reaches ROK again. */
    trunk_scan_test_set_now(1.40);
    test_rc |= expect_control_rc(
        "put back ROK", dsd_engine_trunk_scan_unavoid_target(&opts, &state, state.trunk_scan_session, "ROK", NULL),
        DSD_TRUNK_SCAN_CONTROL_OK);
    tick_at(&opts, &state, 1.70);
    test_rc |= expect_published_target(&state, "ROK put back", "ROK", 2U, 3U);
    test_rc |= expect_list_on_air(&state, "ROK put back", 1U, 0U, 2U, 3U);
    tick_at(&opts, &state, 2.00);
    test_rc |= expect_published_target(&state, "after ROK", "b1", 3U, 3U);
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* A park that failed beside an alternate whose switch keeps failing to prepare (its keys never allocate): the retry in
 * place must not keep waiting for the rotation, whose every walk finds nothing it can try. b's retune fails and so
 * does the fallback onto a, leaving a unparked and cooling; from then on b's preparation fails at every attempt. a is
 * tuned again in place once its cooldown has run, within about 2.5 s, at the dwells of @p dwell_ms. */
static int
run_failed_park_beside_an_unprepared_alternate(int dwell_ms) {
    char body[256];
    DSD_SNPRINTF(body, sizeof body,
                 "a,p25-trunk,851000000,,%d,,,\n"
                 "b,p25-trunk,852000000,,%d,,,-K keys.csv\n",
                 dwell_ms, dwell_ms);
    const char* names[] = {"targets"};
    const char* bodies[] = {body};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    char keys[DSD_TEST_PATH_MAX] = "";
    if (scan_list_files_write(&files, k_squelch_targets_header, names, bodies, 1) != 0
        || dsd_test_path_join(keys, sizeof keys, files.dir, "keys.csv") != 0
        || write_text_file(keys, "key id(hex),key value (hex)\n0010,AAAAAAAAAAAAAAAA\n") != 0) {
        scan_list_files_remove(&files);
        return 1;
    }
    reset_scan_opts_state(&opts, &state);
    scan_list_files_to_opts(&files, NULL, &opts);
    char err[512] = {0};
    trunk_scan_test_set_now(0.0);
    int test_rc = 0;
    if (dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) != 0) {
        DSD_FPRINTF(stderr, "failed park beside an unprepared alternate init: %s\n", err);
        test_rc = 1;
    } else {
        const double failed_m = (double)dwell_ms / 1000.0;
        g_counting_tune_to_cc_failures_remaining = 2;
        tick_at(&opts, &state, failed_m);
        g_counting_tune_to_cc_failures_remaining = 0;
        dsd_key_set_test_alloc_fail_after(0);
        g_counting_tune_to_cc_calls = 0;
        double reparked_m = -1.0;
        for (int i = 1; i <= 64 && reparked_m < 0.0; i++) {
            const int before = g_counting_tune_to_cc_calls;
            tick_at(&opts, &state, failed_m + (0.0625 * i));
            if (g_counting_tune_to_cc_calls != before && g_counting_tune_to_cc_freq == 851000000L) {
                reparked_m = failed_m + (0.0625 * i);
            }
        }
        dsd_key_set_test_alloc_fail_after(-1);
        if (reparked_m < 0.0 || reparked_m > failed_m + 2.5) {
            DSD_FPRINTF(stderr,
                        "dwell %d ms: a failed park beside an unprepared alternate was tuned again at %.2f, "
                        "want by %.2f\n",
                        dwell_ms, reparked_m, failed_m + 2.5);
            test_rc = 1;
        }
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    (void)remove(keys);
    scan_list_files_remove(&files);
    return test_rc;
}

static int
test_failed_park_beside_an_unprepared_alternate_is_retried(void) {
    return run_failed_park_beside_an_unprepared_alternate(250) | run_failed_park_beside_an_unprepared_alternate(300);
}

/* ---- A frequency typed by hand that is a target (issue #644): the go-to and its entry hold ---------------------- */

static int
expect_goto_rc(const char* stage, dsd_scan_goto_result got, dsd_scan_goto_result want) {
    if (got != want) {
        DSD_FPRINTF(stderr, "go-to %s answered %d, want %d\n", stage, (int)got, (int)want);
        return 1;
    }
    return 0;
}

/* Where a go-to left the scan: the target on air, and the hold and its entry mark as published. */
static int
expect_goto_entry(const dsd_state* state, const char* stage, size_t active, unsigned hold, unsigned mark) {
    const size_t got = dsd_engine_trunk_scan_active_index(state);
    if (got != active || state->trunk_scan_hold != hold || state->trunk_scan_entry_hold != mark) {
        DSD_FPRINTF(stderr, "go-to %s: on %zu, hold %u, entry %u; want %zu, %u, %u\n", stage, got,
                    (unsigned)state->trunk_scan_hold, (unsigned)state->trunk_scan_entry_hold, active, hold, mark);
        return 1;
    }
    return 0;
}

static int
expect_goto(const char* stage, int ok) {
    if (!ok) {
        DSD_FPRINTF(stderr, "go-to: %s failed\n", stage);
        return 1;
    }
    return 0;
}

/* Whether the scan kept the failure of an entry to target @p index, a refused park, for app-control to name once
   (dsd_engine_scan_entry_take_failure()); @p index -1 for none kept. Takes it either way. */
static int
expect_goto_failure(dsd_state* state, const char* stage, int index) {
    dsd_scan_entry_failure_t failed;
    DSD_MEMSET(&failed, 0, sizeof failed);
    const int took = dsd_engine_scan_entry_take_failure(state, &failed);
    const int ok = index < 0 ? !took
                             : took && failed.scanner == DSD_SCAN_ENTRY_TRUNK && failed.row == index
                                   && failed.result == DSD_SCAN_GOTO_REFUSED && strcmp(failed.label, "b") == 0
                                   && !dsd_engine_scan_entry_take_failure(state, NULL);
    if (!ok) {
        DSD_FPRINTF(stderr, "go-to %s: failure kept %d (target %d \"%s\"), want target %d \"b\"\n", stage, took,
                    took ? failed.row : -1, took ? failed.label : "", index);
        return 1;
    }
    return 0;
}

/* A go-to and a release as app-control runs them: inside the P25 SM tick guard, which they never take themselves. */
static dsd_scan_goto_result
goto_target(dsd_opts* opts, dsd_state* state, int index, dsd_trunk_scan_goto_report* report) {
    p25_sm_tick_guard_enter();
    const dsd_scan_goto_result result = dsd_engine_trunk_scan_goto_locked(opts, state, index, report);
    p25_sm_tick_guard_leave();
    return result;
}

static void
entry_release(dsd_opts* opts, dsd_state* state) {
    p25_sm_tick_guard_enter();
    dsd_engine_trunk_scan_entry_release_locked(opts, state);
    p25_sm_tick_guard_leave();
}

static const char k_goto_body[] = "a,dmr-trunk,451000000,,250,,\n"
                                  "b,dmr-conventional,452000000,,250,,\n"
                                  "c,nfm-conventional,154430000,,250,,\n";

static const char k_goto_trunked_body[] = "a,dmr-trunk,451000000,,250,,\n"
                                          "b,dmr-trunk,452000000,,250,,\n"
                                          "c,dmr-trunk,453000000,,250,,\n";

/* A running scan goes to a conventional, an analog and a trunked target and holds each, marked an entry hold, once its
   park landed; a target already on air takes the hold with no tune. A trunked target parks on the control channel it
   learned, which the report names. Nothing takes the tick guard the caller holds. */
static int
test_goto_running_switches_and_holds(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path) != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    /* Parked on the trunked target, which learned its control channel away from its CSV seed. */
    state.trunk_cc_freq = 451500000L;
    trunk_scan_test_set_now(1.0);
    const guard_counters guard = guard_counters_now();
    const int unguarded = g_p25_hangtime_unguarded_reads;
    dsd_trunk_scan_goto_report report;
    int test_rc = expect_goto_rc("conventional", goto_target(&opts, &state, 1, &report), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_goto_entry(&state, "conventional", 1U, 1U, 1U);
    test_rc |= expect_goto("conventional: park named and on air",
                           report.park_hz == 452000000L && report.monitor_request == 0 && report.restart_gain == 0
                               && dsd_engine_trunk_scan_target_confirmed(&state, 1));

    g_scan_tune_watch_hz = 452000000L;
    const int watched = g_scan_tune_watch_calls;
    test_rc |= expect_goto_rc("on air", goto_target(&opts, &state, 1, &report), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_goto("on air: no tune", g_scan_tune_watch_calls == watched && report.park_hz == 452000000L);
    g_scan_tune_watch_hz = 0;

    test_rc |= expect_goto_rc("analog", goto_target(&opts, &state, 2, &report), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_goto_entry(&state, "analog", 2U, 1U, 1U);
    test_rc |= expect_goto("analog: park named", report.park_hz == 154430000L);

    const int calls = g_counting_tune_to_cc_calls;
    test_rc |= expect_goto_rc("trunked", goto_target(&opts, &state, 0, &report), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_goto_entry(&state, "trunked", 0U, 1U, 1U);
    test_rc |= expect_goto("trunked: parked on its learned control channel",
                           g_counting_tune_to_cc_calls == calls + 1 && g_counting_tune_to_cc_freq == 451500000L
                               && report.park_hz == 451500000L);
    /* Four go-tos inside the caller's guard: none tried or waited for it itself, and every read it guards ran under
       it. */
    const guard_counters after = guard_counters_now();
    test_rc |= expect_goto("the go-to leaves the guard to its caller",
                           after.enter_calls == guard.enter_calls && after.blocking_enters == guard.blocking_enters + 4
                               && after.leave_calls == guard.leave_calls + 4 && g_p25_tick_guard_depth == 0
                               && g_p25_hangtime_unguarded_reads == unguarded);

    dsd_engine_trunk_scan_shutdown(&opts, &state);
    test_rc |= expect_goto("the shutdown takes the published hold and mark",
                           state.trunk_scan_hold == 0U && state.trunk_scan_entry_hold == 0U);
    test_rc |= expect_goto_rc("no coordinator", goto_target(&opts, &state, 0, &report), DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_goto("no coordinator: an empty report", report.park_hz == 0L);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

enum {
    GOTO_PENDING_LANDS = 0,
    GOTO_PENDING_FAILS_LATE,
    GOTO_PENDING_THEN_ADVANCE,
    GOTO_PENDING_THEN_HOLD,
    GOTO_PENDING_THEN_PAUSE,
    GOTO_PENDING_THEN_RELEASE,
    GOTO_PENDING_REPLACED,
};

/* What a case does while the go-to's park is in flight, and the target, hold and mark it wants once the park answers.
 */
static int
goto_pending_interrupt(dsd_opts* opts, dsd_state* state, int c, const char* what, size_t* on, unsigned* hold,
                       unsigned* mark) {
    int rc = 0;
    switch (c) {
        case GOTO_PENDING_THEN_ADVANCE:
            rc |=
                expect_control_rc(what, dsd_engine_trunk_scan_control(opts, state, DSD_TRUNK_SCAN_CONTROL_ADVANCE), 0);
            *on = 2U;
            *hold = *mark = 0U;
            break;
        case GOTO_PENDING_THEN_HOLD:
            rc |= expect_control_rc(what,
                                    dsd_engine_trunk_scan_control(opts, state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
            *mark = 0U;
            break;
        case GOTO_PENDING_THEN_PAUSE:
            rc |=
                expect_control_rc(what, dsd_engine_trunk_scan_pause_locked(opts, state, DSD_TRUNK_SCAN_PAUSE_TUNE), 0);
            *hold = *mark = 0U;
            break;
        case GOTO_PENDING_THEN_RELEASE:
            entry_release(opts, state);
            *hold = *mark = 0U;
            break;
        default: return 0;
    }
    return rc | expect_goto(what, dsd_engine_trunk_scan_entry_pending(state) == 0);
}

/* A running scan's go-to whose park is in flight: the hold and mark come with its landing, not before; a late failure
   leaves the scan running unheld on its normal failure path (on to the next target); `L`, `Y`, a pause and a release
   cancel it, so its late landing holds nothing; a later go-to replaces it. */
static int
goto_pending_case(int c, const char* what) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_trunked_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    dsd_trunk_scan_goto_report report;
    int test_rc = expect_goto_rc(what, goto_target(&opts, &state, 1, &report), DSD_SCAN_GOTO_PENDING);
    uint64_t park = g_counting_tune_to_cc_last_request_id;
    test_rc |= expect_goto_entry(&state, what, 1U, 0U, 0U);
    test_rc |=
        expect_goto(what, park != 0U && report.park_hz == 452000000L && dsd_engine_trunk_scan_entry_pending(&state) == 1
                              && !dsd_engine_trunk_scan_target_confirmed(&state, 1));
    size_t on = c == GOTO_PENDING_FAILS_LATE ? 2U : 1U;
    unsigned hold = c == GOTO_PENDING_FAILS_LATE ? 0U : 1U;
    unsigned mark = hold;
    if (c == GOTO_PENDING_REPLACED) {
        test_rc |= expect_goto_rc(what, goto_target(&opts, &state, 2, &report), DSD_SCAN_GOTO_PENDING);
        const uint64_t replaced = park;
        park = g_counting_tune_to_cc_last_request_id;
        /* The park let go of answers: it holds nothing, and the new one is still awaited. */
        dsd_trunk_tuning_request_publish(replaced, DSD_TRUNK_TUNE_RESULT_OK);
        tick_at(&opts, &state, 1.05);
        test_rc |= expect_goto_entry(&state, "replaced: the earlier park answered", 2U, 0U, 0U);
        test_rc |= expect_goto(what, dsd_engine_trunk_scan_entry_pending(&state) == 1);
        on = 2U;
    }
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    test_rc |= goto_pending_interrupt(&opts, &state, c, what, &on, &hold, &mark);
    dsd_trunk_tuning_request_publish(park, c == GOTO_PENDING_FAILS_LATE ? DSD_TRUNK_TUNE_RESULT_FAILED
                                                                        : DSD_TRUNK_TUNE_RESULT_OK);
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_goto_entry(&state, what, on, hold, mark);
    test_rc |= expect_goto(what, dsd_engine_trunk_scan_entry_pending(&state) == 0);
    /* Only the entry's own park failing is kept for its toast; a cancel or a replacement keeps none. */
    test_rc |= expect_goto_failure(&state, what, c == GOTO_PENDING_FAILS_LATE ? 1 : -1);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #644: a go-to of trunked target b whose park is pending when the radio stream restarts: the stop fails the park
   it queued. The new stream opens on the radio source the stopped one ran, on the frequency the park asked for: the
   park landed there, so the target holds, marked an entry hold, and the scan does not move on. With @p elsewhere the
   new stream opens on another centre: the stop's failure stands, as for any late failure. */
static int
goto_park_over_a_restart_case(int elsewhere) {
    const char* what = elsewhere ? "go-to park over a restart elsewhere" : "go-to park over a restart on its frequency";
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_trunked_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    dsd_trunk_scan_goto_report report;
    int test_rc = expect_goto_rc(what, goto_target(&opts, &state, 1, &report), DSD_SCAN_GOTO_PENDING);
    const uint64_t park = g_counting_tune_to_cc_last_request_id;
    test_rc |= expect_goto(what, park != 0U && report.park_hz == 452000000L);
    const int input = opts.audio_in_type;
    opts.audio_in_type = AUDIO_IN_RTL;
    state.rtl_ctx = (struct RtlSdrContext*)(void*)&state;
    state.carrier_source_key = 1U;
    p25_sm_tick_guard_enter();
    dsd_engine_trunk_scan_stream_stopping(&opts, &state);
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_FAILED); /* the stop fails the park it queued */
    opts.rtlsdr_center_freq = elsewhere ? 452500000U : 452000000U;
    dsd_engine_trunk_scan_stream_reopened(&opts, &state, 1);
    p25_sm_tick_guard_leave();
    state.rtl_ctx = NULL;
    opts.audio_in_type = input;
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    tick_at(&opts, &state, 1.1);
    if (elsewhere) {
        test_rc |= expect_goto_entry(&state, what, 2U, 0U, 0U);
        test_rc |= expect_goto_failure(&state, what, 1);
    } else {
        test_rc |= expect_goto_entry(&state, what, 1U, 1U, 1U);
        test_rc |= expect_goto(what, dsd_engine_trunk_scan_target_confirmed(&state, 1));
        test_rc |= expect_goto_failure(&state, what, -1);
    }
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #644: the published target the entry match would take as on air follows the park's confirmation: none while
   the go-to's park of b is in flight, b once it lands, none again once the scan is paused; each change with a new
   revision. */
static int
test_entry_on_air_follows_the_park(void) {
    const char* what = "entry on air";
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_trunked_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    int test_rc = expect_goto_rc(what, goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_PENDING);
    const uint64_t park = g_counting_tune_to_cc_last_request_id;
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    tick_at(&opts, &state, 1.05);
    test_rc |= expect_goto("the park in flight is no target on air", state.trunk_scan_entry_on_air == -1);
    uint64_t rev = state.trunk_scan_entry_rev;
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_OK);
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_goto("the landed park is on air",
                           state.trunk_scan_entry_on_air == 1 && state.trunk_scan_entry_rev != rev);
    rev = state.trunk_scan_entry_rev;
    p25_sm_tick_guard_enter();
    test_rc |=
        expect_goto("the pause", dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_IN_PLACE) == 0);
    p25_sm_tick_guard_leave();
    tick_at(&opts, &state, 1.2);
    test_rc |= expect_goto("a paused scan has none on air",
                           state.trunk_scan_entry_on_air == -1 && state.trunk_scan_entry_rev != rev);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #644: a go-to from DMR trunked target a to NXDN48 trunked target b, its park pending when the radio stream
   restarts on b's frequency. A park puts the target's settings in force before its tune, so the new stream opens on
   b's (NXDN48 at 2400 sym/s, the profile a restart publishes to it), and the landing at the reopen keeps them, never
   a's DMR at 4800. */
static int
test_goto_park_over_a_restart_runs_the_target_profile(void) {
    const char* what = "go-to park over a restart across a family";
    static const char k_body[] = "a,dmr-trunk,451000000,,250,,\n"
                                 "b,nxdn48-trunk,452000000,,250,,\n";
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path) != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    int test_rc = expect_goto(what, opts.frame_dmr == 1 && opts.frame_nxdn48 == 0);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    test_rc |= expect_goto_rc(what, goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_PENDING);
    const uint64_t park = g_counting_tune_to_cc_last_request_id;
    const int input = opts.audio_in_type;
    opts.audio_in_type = AUDIO_IN_RTL;
    state.rtl_ctx = (struct RtlSdrContext*)(void*)&state;
    state.carrier_source_key = 1U;
    p25_sm_tick_guard_enter();
    dsd_engine_trunk_scan_stream_stopping(&opts, &state);
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_FAILED); /* the stop fails the park it queued */
    /* What the restart opens on and publishes: b's settings. */
    test_rc |= expect_goto("the restart opens on b's profile",
                           opts.frame_nxdn48 == 1 && opts.frame_dmr == 0
                               && dsd_scan_mode_effective_profile(&opts, &state).symbol_rate_hz == 2400);
    opts.rtlsdr_center_freq = 452000000U;
    dsd_engine_trunk_scan_stream_reopened(&opts, &state, 1);
    p25_sm_tick_guard_leave();
    state.rtl_ctx = NULL;
    opts.audio_in_type = input;
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_goto_entry(&state, what, 1U, 1U, 1U);
    test_rc |=
        expect_goto("the landed park runs b's profile",
                    dsd_engine_trunk_scan_target_confirmed(&state, 1) && opts.frame_nxdn48 == 1 && opts.frame_dmr == 0
                        && dsd_scan_mode_effective_profile(&opts, &state).symbol_rate_hz == 2400);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #644: a go-to's park of b lands before the next tick, then @p advances Next presses come first, every other
   target's retune refused. Refused targets cool down, so the presses tune only a few times between two ticks, far
   fewer than the trunk-tuning ledger keeps: the park's landing is still read at the tick, b is confirmed, and the
   receiver never moved off it. */
static int
park_landing_outlives_refused_advances_case(int advances) {
    const char* what = "a park's landing after refused advances";
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_trunked_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    int test_rc = expect_goto_rc(what, goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_PENDING);
    const uint64_t park = g_counting_tune_to_cc_last_request_id;
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_OK);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_FAILED;
    const int calls = g_counting_tune_to_cc_calls;
    for (int i = 0; i < advances; i++) {
        (void)dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE);
    }
    test_rc |= expect_goto(what, g_counting_tune_to_cc_calls - calls < 8
                                     && dsd_trunk_tuning_request_status(park, NULL) == DSD_TRUNK_TUNE_RESULT_OK);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_goto(what, dsd_engine_trunk_scan_target_confirmed(&state, 1)
                                     && dsd_engine_trunk_scan_active_index(&state) == 1);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
test_park_landing_outlives_refused_advances(void) {
    return park_landing_outlives_refused_advances_case(8) | park_landing_outlives_refused_advances_case(70);
}

static int
test_goto_park_over_a_restart(void) {
    return goto_park_over_a_restart_case(0) | goto_park_over_a_restart_case(1);
}

/* A paused scan resumed at its target, the park still in flight, then that target typed: the go-to waits on that park,
   with no second one, and the park's landing holds the target, marked an entry hold. */
static int
test_goto_joins_a_pending_resume_of_its_target(void) {
    const char* what = "go-to of the target a pending resume parks";
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_trunked_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    int test_rc =
        expect_control_rc(what, dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_TUNE), 0);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    test_rc |= expect_control_rc(what, dsd_engine_trunk_scan_resume_locked(&opts, &state), 1);
    const uint64_t park = g_counting_tune_to_cc_last_request_id;
    const int calls = g_counting_tune_to_cc_calls;
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_DEFERRED;
    dsd_trunk_scan_goto_report report;
    test_rc |= expect_goto_rc(what, goto_target(&opts, &state, 0, &report), DSD_SCAN_GOTO_PENDING);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    test_rc |= expect_goto(what, park != 0U && g_counting_tune_to_cc_calls == calls
                                     && dsd_engine_trunk_scan_entry_pending(&state) == 1);
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_OK);
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_goto_entry(&state, what, 0U, 1U, 1U);
    test_rc |= expect_goto(what, dsd_engine_trunk_scan_entry_pending(&state) == 0);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
test_goto_running_pending_outcomes(void) {
    return goto_pending_case(GOTO_PENDING_LANDS, "pending, lands")
           | goto_pending_case(GOTO_PENDING_FAILS_LATE, "pending, fails late")
           | goto_pending_case(GOTO_PENDING_THEN_ADVANCE, "pending, then L")
           | goto_pending_case(GOTO_PENDING_THEN_HOLD, "pending, then Y")
           | goto_pending_case(GOTO_PENDING_THEN_PAUSE, "pending, then a pause")
           | goto_pending_case(GOTO_PENDING_THEN_RELEASE, "pending, then released")
           | goto_pending_case(GOTO_PENDING_REPLACED, "pending, replaced by a later go-to");
}

/* A go-to of the target whose park is already in flight waits on that park, with no tune of its own; so does a
   P25 target whose park failed while its state machine's own control-channel tune recovered it: that recovery is the
   landing, whether it completed before the coordinator looked or the coordinator adopted its request first. */
static int
goto_p25_recovery_case(int adopted, const char* what) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, "a,p25-trunk,851000000,,250,,\nb,p25-trunk,852000000,,250,,\n", 0, &opts, &state, dir,
                        sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    int test_rc = expect_goto_rc(what, goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_PENDING);
    const uint64_t park = g_counting_tune_to_cc_last_request_id;
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    const int calls = g_counting_tune_to_cc_calls;
    test_rc |= expect_goto_rc(what, goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_PENDING);
    test_rc |= expect_goto("a second go-to waits on the park in flight", g_counting_tune_to_cc_calls == calls);
    p25_sm_ctx_t* ctx = (p25_sm_ctx_t*)dsd_engine_trunk_scan_active_p25_ctx();
    if (!ctx) {
        dsd_engine_trunk_scan_shutdown(&opts, &state);
        trunk_scan_test_clear_now();
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_FAILED);
    if (adopted) {
        const uint64_t retry = dsd_trunk_tuning_request_begin();
        dsd_trunk_tuning_request_mark_ready(retry);
        ctx->cc_tune_request_id = retry;
        ctx->cc_tune_pending = 1;
        ctx->state = P25_SM_ON_CC;
        tick_at(&opts, &state, 1.05);
        test_rc |= expect_goto_entry(&state, "the recovery adopted", 1U, 0U, 0U);
        test_rc |= expect_goto(what, dsd_engine_trunk_scan_entry_pending(&state) == 1);
        dsd_trunk_tuning_request_publish(retry, DSD_TRUNK_TUNE_RESULT_OK);
        (void)p25_sm_restart_pending_cc_acquisition(ctx, &opts, &state, 1.06, "test-sm-recovery");
    } else {
        ctx->cc_tune_pending = 0;
        ctx->cc_tune_request_id = 0U;
        ctx->state = P25_SM_ON_CC;
    }
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_goto_entry(&state, what, 1U, 1U, 1U);
    test_rc |= expect_goto(what, dsd_engine_trunk_scan_entry_pending(&state) == 0);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
test_goto_lands_on_a_p25_recovery(void) {
    return goto_p25_recovery_case(0, "p25 recovered at once") | goto_p25_recovery_case(1, "p25 recovery adopted");
}

/* A running scan's go-to whose retune is refused (@p failures 1) or deferred (@p deferrals 1) is rolled back as an
   advance: the target left is parked again and lands. One whose recovery fails too (@p failures 2) leaves it installed
   and cooling down, its park retried at the cooldown's end as a failed advance's is. Either way nothing is held, and
   the target that failed, cooling down, is still a pick. */
static int
goto_refused_case(int failures, int deferrals, const char* what) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_trunked_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    int test_rc = seed_active_call_row(&state, 7U, 8U, 1.0);
    const int ends = g_explicit_call_ends;
    g_counting_tune_to_cc_failures_remaining = failures;
    g_counting_tune_to_cc_deferrals_remaining = deferrals;
    dsd_trunk_scan_goto_report report;
    test_rc |= expect_goto_rc(what, goto_target(&opts, &state, 2, &report),
                              deferrals ? DSD_SCAN_GOTO_DEFERRED : DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_goto_entry(&state, what, 0U, 0U, 0U);
    test_rc |= expect_published_target(&state, what, "a", 1U, 3U);
    test_rc |= expect_goto(what, report.park_hz == 453000000L && g_explicit_call_ends == ends + 1
                                     && dsd_engine_trunk_scan_entry_pending(&state) == 0);
    const int recovered = failures < 2;
    test_rc |= expect_goto(what, dsd_engine_trunk_scan_target_confirmed(&state, 0) == recovered);
    if (!recovered) {
        const int calls = g_counting_tune_to_cc_calls;
        tick_at(&opts, &state, 2.5);
        test_rc |= expect_goto("no retry before the cooldown ends", g_counting_tune_to_cc_calls == calls);
        tick_at(&opts, &state, 3.1);
        test_rc |=
            expect_goto("the park left is retried at the cooldown's end",
                        g_counting_tune_to_cc_calls == calls + 1 && dsd_engine_trunk_scan_target_confirmed(&state, 0));
    }
    test_rc |= expect_goto_rc(what, goto_target(&opts, &state, 2, &report), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_goto_entry(&state, "the target cooling down is still a pick", 2U, 1U, 1U);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
test_goto_running_refused_rolls_back(void) {
    return goto_refused_case(1, 0, "refused, recovered") | goto_refused_case(0, 1, "deferred, recovered")
           | goto_refused_case(2, 0, "refused, recovery refused");
}

/* A go-to whose preparation fails (no memory for the keyed target's key set) moves nothing: the target on air keeps
   its hold, mark and landing, and an earlier entry still waiting lands held. */
static int
test_goto_preparation_failure_changes_nothing(void) {
    char dir[DSD_TEST_PATH_MAX];
    char keys_path[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (pause_keyed_scan_init(k_pause_keyed_body, &opts, &state, dir, sizeof dir, keys_path, sizeof keys_path,
                              target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, keys_path);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    g_scan_tune_to_freq_pending = 1;
    int test_rc = expect_goto_rc("earlier entry", goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_PENDING);
    g_scan_tune_to_freq_pending = 0;
    const uint64_t park = g_scan_tune_pending_request;
    const int tunes = g_counting_tune_to_cc_calls;
    dsd_trunk_scan_goto_report report;
    dsd_key_set_test_alloc_fail_after(0);
    dsd_scan_goto_result got = goto_target(&opts, &state, 0, &report);
    dsd_key_set_test_alloc_fail_after(-1);
    test_rc |= expect_goto_rc("over an earlier entry", got, DSD_SCAN_GOTO_SETUP_FAILED);
    test_rc |= expect_goto("over an earlier entry: nothing moved",
                           g_counting_tune_to_cc_calls == tunes && report.park_hz == 851000000L
                               && dsd_engine_trunk_scan_entry_pending(&state) == 1);
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_OK);
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_goto_entry(&state, "the earlier entry lands", 1U, 1U, 1U);

    dsd_key_set_test_alloc_fail_after(0);
    got = goto_target(&opts, &state, 0, &report);
    dsd_key_set_test_alloc_fail_after(-1);
    test_rc |= expect_goto_rc("over a hold", got, DSD_SCAN_GOTO_SETUP_FAILED);
    test_rc |= expect_goto_entry(&state, "over a hold", 1U, 1U, 1U);
    test_rc |= expect_goto("over a hold: still on air",
                           g_counting_tune_to_cc_calls == tunes && dsd_engine_trunk_scan_target_confirmed(&state, 1));
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, keys_path);
    return test_rc;
}

/* Only a target the rotation takes is a go-to's: one out of range, in a list that is off, avoided, or skipped at every
   visit for a width the DSP rate cannot filter is refused with nothing tuned. */
static int
test_goto_refuses_a_target_out_of_the_rotation(void) {
    static const char* const names[] = {"county", "state"};
    static const char* const bodies[] = {
        "a,dmr-trunk,451000000,,250,,\nb,dmr-trunk,452000000,,250,,\n",
        "c,dmr-trunk,453000000,,250,,\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
        return 1;
    }
    const int calls = g_counting_tune_to_cc_calls;
    int test_rc = expect_goto_rc("below range", goto_target(&opts, &state, -1, NULL), DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_goto_rc("past range", goto_target(&opts, &state, 3, NULL), DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_goto_rc("no state", goto_target(&opts, NULL, 0, NULL), DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_list_rc("state off", list_set(&opts, &state, 2, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_goto_rc("list off", goto_target(&opts, &state, 2, NULL), DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_list_rc("state on", list_set(&opts, &state, 2, 1), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_goto("refusals tuned nothing", g_counting_tune_to_cc_calls == calls);
    test_rc |= expect_control_rc("avoid a",
                                 dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE), 0);
    const int after_avoid = g_counting_tune_to_cc_calls;
    test_rc |= expect_goto_rc("avoided", goto_target(&opts, &state, 0, NULL), DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_goto_entry(&state, "avoided", 1U, 0U, 0U);
    test_rc |= expect_goto("the avoided refusal tuned nothing", g_counting_tune_to_cc_calls == after_avoid);
    scan_lists_finish(&files, &opts, &state);

    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    if (make_temp_dir(dir, sizeof dir) != 0
        || write_targets_file_with_header(dir, k_squelch_targets_header,
                                          "dmr,dmr-conventional,461000000,,250,250,,\n"
                                          "fire,nfm-conventional,154430000,,250,250,,"
                                          "--nfm-bandwidth-hz 20000 --squelch-db -50\n",
                                          target_path, sizeof target_path)
               != 0) {
        return 1;
    }
    reset_scan_opts_state(&opts, &state);
    DSD_SNPRINTF(opts.trunk_scan_lists[0].path, sizeof opts.trunk_scan_lists[0].path, "%s", target_path);
    opts.trunk_scan_list_count = 1;
    g_scan_dsp_rate_hz = 16000;
    char err[256] = {0};
    trunk_scan_test_set_now(0.0);
    test_rc |= expect_goto("width fixture", dsd_engine_trunk_scan_init(&opts, &state, err, sizeof err) == 0);
    test_rc |= expect_goto_rc("width unfit", goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_goto_entry(&state, "width unfit", 0U, 0U, 0U);
    dsd_scan_row_edit_value value;
    DSD_MEMSET(&value, 0, sizeof value);
    value.width_hz = 12500;
    test_rc |= expect_goto("width edit", dsd_engine_trunk_scan_edit_target(&opts, &state, state.scan_row_session,
                                                                           "fire", DSD_SCAN_ROW_FIELD_WIDTH,
                                                                           DSD_SCAN_ROW_EDIT_SET, &value, NULL)
                                             == DSD_SCAN_ROW_EDIT_STORED);
    test_rc |= expect_goto_rc("width edited to fit", goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_goto_entry(&state, "width edited to fit", 1U, 1U, 1U);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    g_scan_dsp_rate_hz = 0;
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* A one-target scan has no `count < 2` shortcut: its park in flight is waited on, and a park that failed late leaves
   it cooling down where it is, unheld; a go-to then parks it again at once (its cooldown is no bar to a pick), and a
   refused park leaves it unheld with no recovery to try. */
static int
test_goto_single_target(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    if (scan_visit_init(NULL, "a,dmr-trunk,451000000,,250,,\n", 0, &opts, &state, dir, sizeof dir, target_path,
                        sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    const uint64_t park = dsd_trunk_tuning_pending_request();
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    int calls = g_counting_tune_to_cc_calls;
    int test_rc = expect_goto_rc("park in flight", goto_target(&opts, &state, 0, NULL), DSD_SCAN_GOTO_PENDING);
    test_rc |= expect_goto("park in flight: no tune of its own", park != 0U && g_counting_tune_to_cc_calls == calls);
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_FAILED);
    tick_at(&opts, &state, 0.1);
    test_rc |= expect_goto_entry(&state, "the park failed late", 0U, 0U, 0U);
    test_rc |= expect_goto("the park failed late: nothing waits, nothing on air",
                           dsd_engine_trunk_scan_entry_pending(&state) == 0
                               && !dsd_engine_trunk_scan_target_confirmed(&state, 0));

    g_counting_tune_to_cc_failures_remaining = 1;
    test_rc |= expect_goto_rc("refused", goto_target(&opts, &state, 0, NULL), DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_goto_entry(&state, "refused", 0U, 0U, 0U);
    test_rc |= expect_goto("refused: one park, no recovery", g_counting_tune_to_cc_calls == calls + 1
                                                                 && !dsd_engine_trunk_scan_target_confirmed(&state, 0));
    calls = g_counting_tune_to_cc_calls;
    test_rc |= expect_goto_rc("parked again", goto_target(&opts, &state, 0, NULL), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_goto_entry(&state, "parked again", 0U, 1U, 1U);
    test_rc |= expect_goto("parked again at once", g_counting_tune_to_cc_calls == calls + 1);
    test_rc |= expect_goto_rc("on air", goto_target(&opts, &state, 0, NULL), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_goto("on air: no tune", g_counting_tune_to_cc_calls == calls + 1);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* Issue #644: a running trunk scan with an entry waiting on target b that names no park, or a park no longer in flight
   (set so directly): the next tick ends it, its failure kept for the toast, so nothing is left waiting. */
static int
goto_entry_waiting_on_nothing_case(uint64_t request) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path) != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    (void)dsd_engine_scan_entry_take_failure(&state, NULL);
    dsd_engine_scan_entry_intent_set_target(&state, 1, 0U, request);
    int test_rc = expect_goto("the entry is set", dsd_engine_scan_entry_intent_get(&state).active);
    tick_at(&opts, &state, 1.05);
    test_rc |= expect_goto("the tick ends it", !dsd_engine_scan_entry_intent_get(&state).active);
    test_rc |= expect_goto_failure(&state, "waiting on nothing", 1);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
test_goto_entry_waiting_on_nothing(void) {
    return goto_entry_waiting_on_nothing_case(0U) | goto_entry_waiting_on_nothing_case(UINT64_C(4444));
}

/* Issue #644: a park whose request already failed (a stream stop fails the one it queued) before the coordinator's next
   tick is dead: a go-to of its target never waits on it, but parks the target afresh, and that park's landing holds
   it. */
static int
test_goto_never_joins_a_failed_park(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    if (scan_visit_init(NULL, "a,dmr-trunk,451000000,,250,,\n", 0, &opts, &state, dir, sizeof dir, target_path,
                        sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    const uint64_t park = dsd_trunk_tuning_pending_request();
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_FAILED);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    const int calls = g_counting_tune_to_cc_calls;
    int test_rc = expect_goto_rc("over a failed park", goto_target(&opts, &state, 0, NULL), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_goto("over a failed park: parked afresh", park != 0U && g_counting_tune_to_cc_calls == calls + 1);
    test_rc |= expect_goto_entry(&state, "over a failed park", 0U, 1U, 1U);
    tick_at(&opts, &state, 0.1);
    test_rc |= expect_goto_entry(&state, "over a failed park, after a tick", 0U, 1U, 1U);
    test_rc |= expect_goto_failure(&state, "over a failed park", -1);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* The same channel in two lists (issue #697) is two targets, each with its own settings: a go-to of the copy not on
   air switches to it. */
static int
test_goto_a_copy_in_another_list(void) {
    static const char* const names[] = {"county", "state"};
    static const char* const bodies[] = {
        "a,dmr-conventional,461000000,,250,,\n",
        "a2,dmr-conventional,461000000,,250,,\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    int test_rc = expect_goto_rc("copy", goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_goto_entry(&state, "copy", 1U, 1U, 1U);
    test_rc |= expect_goto("copy: its own list on air", state.trunk_scan_active_list == 2U
                                                            && dsd_engine_trunk_scan_target_confirmed(&state, 1)
                                                            && !dsd_engine_trunk_scan_target_confirmed(&state, 0));
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

enum {
    GOTO_PAUSED_LANDS = 0,
    GOTO_PAUSED_PENDING,
    GOTO_PAUSED_REFUSED,
    GOTO_PAUSED_UNPREPARED,
    GOTO_PAUSED_FAILS_LATE,
    GOTO_PAUSED_DEFERRED,
};

/* Two keyed targets: the scan pauses at the trunked one, and the go-to resumes at the conventional one. */
static const char k_goto_paused_body[] = "a,p25-trunk,851000000,,250,,keyed,hexkeys.csv\n"
                                         "b,dmr-conventional,461000000,,250,,keyed,hexkeys.csv\n";

/* What a paused go-to that stayed paused left: the toast, and the target it paused at is the one a plain resume parks.
 */
static int
expect_goto_stayed_paused(dsd_opts* opts, dsd_state* state, const char* stage, const char* want) {
    int rc = expect_paused_publication(state, stage, 2U, 0, 0U, 0U);
    rc |= expect_text(stage, state->ui_msg, want);
    rc |= expect_control_rc(stage, dsd_engine_trunk_scan_resume_locked(opts, state), 0);
    rc |= expect_published_target(state, "the plain resume parks the target paused at", "a", 1U, 2U);
    return rc | expect_goto_entry(state, stage, 0U, 0U, 0U);
}

/* A paused scan resumes at the target given (issue #644): the scan runs on it, held and marked once its park lands,
   and while that park is in flight it runs as a resume pending does. A refused park or a failed preparation leaves it
   paused, with the toast, and the target it paused at is still the one a plain resume parks; a park that fails late
   leaves it running unheld on its normal failure path, on to the next target. */
static int
goto_paused_case(int c, const char* what) {
    char dir[DSD_TEST_PATH_MAX];
    char keys_path[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (pause_keyed_scan_init(k_goto_paused_body, &opts, &state, dir, sizeof dir, keys_path, sizeof keys_path,
                              target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, keys_path);
        return 1;
    }
    int test_rc =
        expect_control_rc(what, dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_TUNE), 0);
    trunk_scan_test_set_now(1.0);
    state.ui_msg[0] = '\0';
    g_scan_tune_to_freq_failures_remaining = c == GOTO_PAUSED_REFUSED ? 1 : 0;
    g_scan_tune_to_freq_deferrals_remaining = c == GOTO_PAUSED_DEFERRED ? 1 : 0;
    g_scan_tune_to_freq_pending = c == GOTO_PAUSED_PENDING || c == GOTO_PAUSED_FAILS_LATE;
    dsd_key_set_test_alloc_fail_after(c == GOTO_PAUSED_UNPREPARED ? 0 : -1);
    dsd_trunk_scan_goto_report report;
    const dsd_scan_goto_result got = goto_target(&opts, &state, 1, &report);
    dsd_key_set_test_alloc_fail_after(-1);
    g_scan_tune_to_freq_pending = 0;
    static const dsd_scan_goto_result want[] = {
        DSD_SCAN_GOTO_HOLDING,      DSD_SCAN_GOTO_PENDING, DSD_SCAN_GOTO_REFUSED,
        DSD_SCAN_GOTO_SETUP_FAILED, DSD_SCAN_GOTO_PENDING, DSD_SCAN_GOTO_DEFERRED,
    };
    test_rc |= expect_goto_rc(what, got, want[c]);
    test_rc |= expect_goto(what, report.park_hz == 461000000L);
    if (c == GOTO_PAUSED_REFUSED) {
        test_rc |= expect_goto_stayed_paused(&opts, &state, what, "Scan stays paused: tune to 461.000000 MHz failed");
    } else if (c == GOTO_PAUSED_UNPREPARED) {
        test_rc |= expect_goto_stayed_paused(&opts, &state, what,
                                             "Scan stays paused: scan channel 461.000000 MHz could not be set up");
    } else if (c == GOTO_PAUSED_DEFERRED) {
        test_rc |=
            expect_goto_stayed_paused(&opts, &state, what, "Scan stays paused: tune to 461.000000 MHz deferred; retry");
    } else {
        test_rc |= expect_goto(what, state.trunk_scan_paused == 0U && state.operator_tuned == 0U
                                         && state.rkey_array[9] == 999ULL);
        test_rc |= expect_goto_entry(&state, what, 1U, c == GOTO_PAUSED_LANDS, c == GOTO_PAUSED_LANDS);
    }
    if (c == GOTO_PAUSED_PENDING || c == GOTO_PAUSED_FAILS_LATE) {
        test_rc |= expect_goto(what, dsd_engine_trunk_scan_entry_pending(&state) == 1);
        dsd_trunk_tuning_request_publish(g_scan_tune_pending_request, c == GOTO_PAUSED_PENDING
                                                                          ? DSD_TRUNK_TUNE_RESULT_OK
                                                                          : DSD_TRUNK_TUNE_RESULT_FAILED);
        tick_at(&opts, &state, 1.1);
        const unsigned held = c == GOTO_PAUSED_PENDING;
        test_rc |= expect_goto_entry(&state, what, held ? 1U : 0U, held, held);
        test_rc |= expect_goto(what, state.trunk_scan_paused == 0U && dsd_engine_trunk_scan_entry_pending(&state) == 0);
    }
    test_rc |= expect_goto_failure(&state, what, c == GOTO_PAUSED_FAILS_LATE ? 1 : -1);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, keys_path);
    return test_rc;
}

static int
test_goto_paused_resumes_at_the_target(void) {
    return goto_paused_case(GOTO_PAUSED_LANDS, "paused, lands")
           | goto_paused_case(GOTO_PAUSED_PENDING, "paused, pending")
           | goto_paused_case(GOTO_PAUSED_REFUSED, "paused, refused")
           | goto_paused_case(GOTO_PAUSED_UNPREPARED, "paused, not prepared")
           | goto_paused_case(GOTO_PAUSED_FAILS_LATE, "paused, fails late")
           | goto_paused_case(GOTO_PAUSED_DEFERRED, "paused, deferred");
}

/* An entry hold's life (issue #644): `L`, `J`, an avoid's step and a list-off departure keep it, mark and all, on the
   target they land; `Y` takes both; a pause takes both, while an ordinary hold outlives a pause; a release takes both
   and gives the target a fresh dwell, after which the scan moves on; a release leaves an ordinary hold alone. */
static int
test_entry_hold_lifecycle(void) {
    static const char* const names[] = {"county", "state"};
    static const char* const bodies[] = {
        "a,dmr-trunk,451000000,,250,,\nb,dmr-trunk,452000000,,250,,\n",
        "c,dmr-trunk,453000000,,250,,\n",
    };
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    if (scan_lists_init(&files, NULL, names, bodies, NULL, 2, &opts, &state) != 0) {
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    int test_rc = expect_goto_rc("hold b", goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_HOLDING);
    test_rc |= expect_control_rc("L", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE), 0);
    test_rc |= expect_goto_entry(&state, "L", 2U, 1U, 1U);
    test_rc |= expect_control_rc("J", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_RETREAT), 0);
    test_rc |= expect_goto_entry(&state, "J", 1U, 1U, 1U);
    test_rc |=
        expect_control_rc("b", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE), 0);
    test_rc |= expect_goto_entry(&state, "b", 2U, 1U, 1U);
    test_rc |=
        expect_control_rc("clear", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_AVOID_CLEAR), 1);
    test_rc |= expect_list_rc("state off", list_set(&opts, &state, 2, 0), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |= expect_goto("the list-off departure keeps the hold and mark",
                           dsd_engine_trunk_scan_active_index(&state) != 2U && state.trunk_scan_hold == 1U
                               && state.trunk_scan_entry_hold == 1U);
    test_rc |= expect_list_rc("state on", list_set(&opts, &state, 2, 1), DSD_TRUNK_SCAN_LIST_SET_OK);
    test_rc |=
        expect_control_rc("Y", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 0);
    test_rc |=
        expect_goto("Y takes the hold and mark", state.trunk_scan_hold == 0U && state.trunk_scan_entry_hold == 0U);

    test_rc |= expect_goto_rc("hold b again", goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_HOLDING);
    test_rc |=
        expect_control_rc("pause", dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_TUNE), 0);
    test_rc |=
        expect_goto("a pause takes the entry hold", state.trunk_scan_hold == 0U && state.trunk_scan_entry_hold == 0U);
    test_rc |= expect_control_rc("resume", dsd_engine_trunk_scan_resume_locked(&opts, &state), 0);
    test_rc |= expect_goto_entry(&state, "resumed", 1U, 0U, 0U);
    test_rc |=
        expect_control_rc("Y on", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
    test_rc |= expect_control_rc("pause held",
                                 dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_TUNE), 0);
    test_rc |= expect_goto("an ordinary hold outlives a pause",
                           state.trunk_scan_hold == 1U && state.trunk_scan_entry_hold == 0U);
    test_rc |= expect_control_rc("resume held", dsd_engine_trunk_scan_resume_locked(&opts, &state), 0);
    entry_release(&opts, &state);
    test_rc |= expect_goto_entry(&state, "a release leaves an ordinary hold", 1U, 1U, 0U);
    test_rc |=
        expect_control_rc("Y off", dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 0);

    test_rc |= expect_goto_rc("hold b on air", goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_HOLDING);
    tick_at(&opts, &state, 5.0);
    test_rc |= expect_goto_entry(&state, "held past its dwell", 1U, 1U, 1U);
    entry_release(&opts, &state);
    test_rc |= expect_goto_entry(&state, "released", 1U, 0U, 0U);
    tick_at(&opts, &state, 5.1);
    tick_at(&opts, &state, 5.2);
    test_rc |= expect_goto_entry(&state, "a fresh dwell after the release", 1U, 0U, 0U);
    tick_at(&opts, &state, 5.4);
    test_rc |= expect_goto("the scan continues past the dwell", dsd_engine_trunk_scan_active_index(&state) != 1U);
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* A go-to replaces an entry hold (issue #644): from a target an entry holds, the hold and its mark go once the go-to
   gets past its preparation, and only the new target's confirmed park sets them again, so a park that fails late
   leaves the scan running unheld, on to the next target. An ordinary hold carries over as `L` carries it: the park
   that fails late leaves the scan held on that target. */
static int
goto_replaces_a_hold_case(int entry, const char* what) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_trunked_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    int test_rc = 0;
    if (entry) {
        test_rc |= expect_goto_rc(what, goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_HOLDING);
        test_rc |= expect_goto_entry(&state, what, 1U, 1U, 1U);
    } else {
        test_rc |= expect_control_rc(
            what, dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE), 1);
    }
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    test_rc |= expect_goto_rc(what, goto_target(&opts, &state, 2, NULL), DSD_SCAN_GOTO_PENDING);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    const uint64_t park = g_counting_tune_to_cc_last_request_id;
    const unsigned held = entry ? 0U : 1U;
    test_rc |= expect_goto_entry(&state, "while the park is in flight", 2U, held, 0U);
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_FAILED);
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_goto_entry(&state, what, entry ? 0U : 2U, held, 0U);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* A go-to over an entry hold that moves nothing (its preparation fails) leaves that hold and its mark as they were. */
static int
test_goto_replaces_an_entry_hold(void) {
    int test_rc = goto_replaces_a_hold_case(1, "an entry hold, then a go-to that fails late")
                  | goto_replaces_a_hold_case(0, "an ordinary hold, then a go-to that fails late");
    char dir[DSD_TEST_PATH_MAX];
    char keys_path[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (pause_keyed_scan_init(k_pause_keyed_body, &opts, &state, dir, sizeof dir, keys_path, sizeof keys_path,
                              target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, keys_path);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    test_rc |= expect_goto_rc("hold b", goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_HOLDING);
    dsd_key_set_test_alloc_fail_after(0);
    const dsd_scan_goto_result got = goto_target(&opts, &state, 0, NULL);
    dsd_key_set_test_alloc_fail_after(-1);
    test_rc |= expect_goto_rc("an unprepared go-to over an entry hold", got, DSD_SCAN_GOTO_SETUP_FAILED);
    test_rc |= expect_goto_entry(&state, "an unprepared go-to over an entry hold", 1U, 1U, 1U);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, keys_path);
    return test_rc;
}

/* `L`, `J` and `b` act on the scan, so they cancel an entry still waiting on its park even when they move nothing:
   here the only other target is cooling down after a failed retune, so the walk tries nothing. The park's landing
   then holds nothing, and `b` leaves no hold on the target it avoided. */
static int
operator_move_cancels_an_entry_case(int op, const char* what) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, "a,dmr-trunk,451000000,,250,,\nb,dmr-trunk,452000000,,250,,\n", 0, &opts, &state, dir,
                        sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    /* b's retune and a's recovery both fail: both cool down until 3.0, the receiver installed on a. */
    g_counting_tune_to_cc_failures_remaining = 2;
    int test_rc = expect_goto_rc(what, goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_REFUSED);
    g_counting_tune_to_cc_failures_remaining = 0;
    trunk_scan_test_set_now(1.1);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    test_rc |= expect_goto_rc(what, goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_PENDING);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    const uint64_t park = g_counting_tune_to_cc_last_request_id;
    const int calls = g_counting_tune_to_cc_calls;
    trunk_scan_test_set_now(1.2);
    (void)dsd_engine_trunk_scan_control(&opts, &state, op);
    test_rc |=
        expect_goto(what, dsd_engine_trunk_scan_active_index(&state) == 1U && g_counting_tune_to_cc_calls == calls
                              && dsd_engine_trunk_scan_entry_pending(&state) == 0);
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_OK);
    tick_at(&opts, &state, 1.3);
    test_rc |= expect_goto_entry(&state, what, 1U, 0U, 0U);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
test_operator_moves_cancel_a_pending_entry(void) {
    return operator_move_cancels_an_entry_case(DSD_TRUNK_SCAN_CONTROL_ADVANCE, "L that moves nothing")
           | operator_move_cancels_an_entry_case(DSD_TRUNK_SCAN_CONTROL_RETREAT, "J that moves nothing")
           | operator_move_cancels_an_entry_case(DSD_TRUNK_SCAN_CONTROL_AVOID_ACTIVE, "b that moves nothing");
}

/* An earlier entry still waiting, then a go-to refused after its park began: the earlier entry went with the movement,
   so its park's late answer holds nothing. */
static int
test_goto_refused_retires_an_earlier_entry(void) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_trunked_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    int test_rc = expect_goto_rc("earlier entry", goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_PENDING);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    const uint64_t earlier = g_counting_tune_to_cc_last_request_id;
    g_counting_tune_to_cc_failures_remaining = 1;
    test_rc |= expect_goto_rc("refused, recovered", goto_target(&opts, &state, 2, NULL), DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_goto_entry(&state, "refused, recovered", 1U, 0U, 0U);
    test_rc |= expect_goto("nothing waits", dsd_engine_trunk_scan_entry_pending(&state) == 0);
    dsd_trunk_tuning_request_publish(earlier, DSD_TRUNK_TUNE_RESULT_OK);
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_goto_entry(&state, "the earlier park's late answer", 1U, 0U, 0U);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

/* A go-to refused while an earlier go-to's park is still in flight (issue #644): the coordinator, the label it publishes
   and the receiver agree on the target that park goes to, whatever comes next. With @p failures 1 the walk's recovery
   park onto it is taken at once; with 2 that recovery is refused too, and the park still in flight is the one that
   puts the receiver there. Its late answer then changes nothing that is named. */
static int
goto_refused_over_a_pending_park_case(int failures, const char* what) {
    char dir[DSD_TEST_PATH_MAX];
    char target_path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (scan_visit_init(NULL, k_goto_trunked_body, 0, &opts, &state, dir, sizeof dir, target_path, sizeof target_path)
        != 0) {
        cleanup_paths(dir, target_path, NULL);
        return 1;
    }
    trunk_scan_test_set_now(1.0);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    int test_rc = expect_goto_rc(what, goto_target(&opts, &state, 1, NULL), DSD_SCAN_GOTO_PENDING);
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    const uint64_t pending_park = g_counting_tune_to_cc_last_request_id;
    g_counting_tune_to_cc_parked_freq = 0;
    g_counting_tune_to_cc_failures_remaining = failures;
    test_rc |= expect_goto_rc(what, goto_target(&opts, &state, 2, NULL), DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_goto_entry(&state, what, 1U, 0U, 0U);
    test_rc |= expect_published_target(&state, what, "b", 2U, 3U);
    /* The last tune asked is the recovery onto b, taken (1) or refused (2: the park still in flight lands b). */
    test_rc |= expect_goto(what, g_counting_tune_to_cc_freq == 452000000L
                                     && g_counting_tune_to_cc_parked_freq == (failures < 2 ? 452000000L : 0L));
    dsd_trunk_tuning_request_publish(pending_park, DSD_TRUNK_TUNE_RESULT_OK);
    tick_at(&opts, &state, 1.1);
    test_rc |= expect_goto_entry(&state, "the park in flight lands", 1U, 0U, 0U);
    test_rc |= expect_published_target(&state, "the park in flight lands", "b", 2U, 3U);
    /* The landing confirms b: the recovery's (1) or the park in flight's (2), which the coordinator still awaited. */
    test_rc |= expect_goto(what, dsd_engine_trunk_scan_target_confirmed(&state, 1));
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    trunk_scan_test_clear_now();
    cleanup_paths(dir, target_path, NULL);
    return test_rc;
}

static int
test_goto_refused_over_a_pending_park(void) {
    return goto_refused_over_a_pending_park_case(1, "refused over a pending park, recovered")
           | goto_refused_over_a_pending_park_case(2, "refused over a pending park, recovery refused");
}

/* ---- --trunk-scan-hold (issue #644): a trunk scan that starts parked on one target, held there ---------------- */

static const char* const k_hold_names[] = {"county", "state"};
static const char* const k_hold_bodies[] = {
    "a,dmr-trunk,451000000,,250,,\n"
    "b,dmr-conventional,452000000,,250,,\n",
    "c,dmr-trunk,453000000,,250,,\n"
    "fire,nfm-conventional,154430000,,250,250,,--nfm-bandwidth-hz 20000\n",
};

/* What the last held start logged (hold_scan_start_lists()). */
static char g_hold_log[4096];

/* Start a scan over the lists @p names / @p bodies (@p count of them; list 2 off where @p second_off) with
   --trunk-scan-hold @p id, its log kept in g_hold_log. Returns the init's answer, -2 when the files could not be
   written or the log not captured. */
static int
hold_scan_start_lists(scan_list_files* files, const char* const* names, const char* const* bodies, int count,
                      int second_off, const char* id, dsd_opts* opts, dsd_state* state, char* err, size_t err_sz) {
    g_hold_log[0] = '\0';
    if (scan_list_files_write(files, k_squelch_targets_header, names, bodies, count) != 0) {
        scan_list_files_remove(files);
        return -2;
    }
    reset_scan_opts_state(opts, state);
    const int off[] = {0, second_off};
    scan_list_files_to_opts(files, off, opts);
    DSD_SNPRINTF(opts->trunk_scan_hold_id, sizeof opts->trunk_scan_hold_id, "%s", id);
    err[0] = '\0';
    trunk_scan_test_set_now(0.0);
    dsd_test_capture_stderr cap;
    if (dsd_test_capture_stderr_begin(&cap, "trunkscanhold") != 0) {
        return -2;
    }
    const int rc = dsd_engine_trunk_scan_init(opts, state, err, err_sz);
    (void)dsd_test_capture_stderr_end(&cap);
    (void)dsd_test_capture_stderr_read(&cap, g_hold_log, sizeof g_hold_log);
    return rc;
}

/* Start a scan over the two lists above (targets a, b | c, fire) with --trunk-scan-hold @p id. */
static int
hold_scan_start(scan_list_files* files, int second_off, const char* id, dsd_opts* opts, dsd_state* state, char* err,
                size_t err_sz) {
    return hold_scan_start_lists(files, k_hold_names, k_hold_bodies, 2, second_off, id, opts, state, err, err_sz);
}

/* Whether the held start logged @p want exactly once, and none of the other start lines. */
static int
expect_hold_log(const char* stage, const char* want) {
    static const char* const k_lines[] = {
        "NOTICE: Trunk scan starts held on target",
        "NOTICE: Trunk scan starts on target",
        "WARNING: --trunk-scan-hold:",
    };
    int others = 0;
    for (size_t i = 0; i < sizeof k_lines / sizeof k_lines[0]; i++) {
        if (strstr(want, k_lines[i]) == NULL) {
            others += count_text(g_hold_log, k_lines[i]);
        }
    }
    if (count_text(g_hold_log, want) != 1 || others != 0) {
        DSD_FPRINTF(stderr, "hold start %s: logged %d \"%s\" and %d other start lines\n%s\n", stage,
                    count_text(g_hold_log, want), want, others, g_hold_log);
        return 1;
    }
    return 0;
}

/* Whether the start kept the failure of its hold's park, target @p index named @p label coming to @p result, for
   app-control to name once; @p index -1 for none kept. Takes it either way. */
static int
expect_hold_failure(dsd_state* state, const char* stage, int index, const char* label, dsd_scan_goto_result result) {
    dsd_scan_entry_failure_t failed;
    DSD_MEMSET(&failed, 0, sizeof failed);
    const int took = dsd_engine_scan_entry_take_failure(state, &failed);
    const int ok = index < 0 ? !took
                             : took && failed.scanner == DSD_SCAN_ENTRY_TRUNK && failed.row == index
                                   && failed.result == result && strcmp(failed.label, label) == 0
                                   && !dsd_engine_scan_entry_take_failure(state, NULL);
    if (!ok) {
        DSD_FPRINTF(stderr, "hold start %s: failure kept %d (target %d \"%s\" result %d), want target %d \"%s\"\n",
                    stage, took, took ? failed.row : -1, took ? failed.label : "", took ? (int)failed.result : -1,
                    index, index < 0 ? "" : label);
        return 1;
    }
    return 0;
}

/* An id no target has, one whose list starts off and one whose width the DSP rate cannot filter refuse the start,
   naming the id and why; nothing is left attached. */
static int
test_hold_start_refusals(void) {
    static const struct {
        const char* id;
        int second_off;
        int rate_hz;
        const char* want;
    } cases[] = {
        {"zz", 0, 0, "--trunk-scan-hold: no target in the trunk-scan lists has the id \"zz\""},
        {"c", 1, 0, "--trunk-scan-hold: target \"c\" is in a list that is off (list 2, state); start that list on"},
        {
            "fire",
            0,
            16000,
            "--trunk-scan-hold: target \"fire\"'s width does not fit (NFM 20 kHz does not fit the 16 kHz DSP rate)",
        },
    };

    static dsd_opts opts;
    static dsd_state state;
    int test_rc = 0;
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        scan_list_files files;
        char err[256];
        g_scan_dsp_rate_hz = cases[i].rate_hz;
        const int rc = hold_scan_start(&files, cases[i].second_off, cases[i].id, &opts, &state, err, sizeof err);
        if (rc != -1 || strcmp(err, cases[i].want) != 0 || dsd_engine_trunk_scan_active_index(&state) != (size_t)-1
            || state.trunk_scan_hold != 0U || state.trunk_scan_entry_hold != 0U || opts.trunk_scan_hold_id[0] != '\0') {
            DSD_FPRINTF(stderr, "hold start refusal %zu: rc=%d err=\"%s\", want \"%s\", nothing attached, id taken\n",
                        i, rc, err, cases[i].want);
            test_rc = 1;
        }
        g_scan_dsp_rate_hz = 0;
        scan_lists_finish(&files, &opts, &state);
    }
    return test_rc;
}

/* The scan starts on the target named, in any list, held and marked an entry hold once its park landed (at once
   here), as a typed frequency's go-to holds it; the id is taken, once. */
static int
test_hold_start_parks_and_holds(void) {
    static const struct {
        const char* id;
        size_t index;
    } cases[] = {{"c", 2U}, {"b", 1U}};

    static dsd_opts opts;
    static dsd_state state;
    int test_rc = 0;
    for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        scan_list_files files;
        char err[256];
        const int rc = hold_scan_start(&files, 0, cases[i].id, &opts, &state, err, sizeof err);
        test_rc |= expect_goto("hold start: init", rc == 0);
        test_rc |= expect_goto_entry(&state, cases[i].id, cases[i].index, 1U, 1U);
        test_rc |=
            expect_goto("hold start: on air, nothing waits, the id taken",
                        dsd_engine_trunk_scan_target_confirmed(&state, (int)cases[i].index)
                            && dsd_engine_trunk_scan_entry_pending(&state) == 0 && opts.trunk_scan_hold_id[0] == '\0');
        test_rc |= expect_hold_failure(&state, cases[i].id, -1, "", DSD_SCAN_GOTO_REFUSED);
        char want[128];
        DSD_SNPRINTF(want, sizeof want, "NOTICE: Trunk scan starts held on target '%s' (--trunk-scan-hold)\n",
                     cases[i].id);
        test_rc |= expect_hold_log(cases[i].id, want);
        scan_lists_finish(&files, &opts, &state);
    }
    return test_rc;
}

/* A park still in flight: the hold comes with its landing, not before; a park that fails late leaves the scan
   running unheld on its normal failure path (on to the next target), its failure kept for its toast, once. */
static int
hold_start_pending_case(int fails, const char* what) {
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    char err[256];
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_PENDING;
    const int rc = hold_scan_start(&files, 0, "c", &opts, &state, err, sizeof err);
    const uint64_t park = g_counting_tune_to_cc_last_request_id;
    g_counting_tune_to_cc_result = DSD_TRUNK_TUNE_RESULT_OK;
    int test_rc = expect_goto(what, rc == 0 && park != 0U && opts.trunk_scan_hold_id[0] == '\0');
    test_rc |= expect_hold_log(
        what, "NOTICE: Trunk scan starts on target 'c' (--trunk-scan-hold); it holds there once the tune lands\n");
    test_rc |= expect_goto_entry(&state, what, 2U, 0U, 0U);
    test_rc |= expect_goto(what, dsd_engine_trunk_scan_entry_pending(&state) == 1);
    dsd_trunk_tuning_request_publish(park, fails ? DSD_TRUNK_TUNE_RESULT_FAILED : DSD_TRUNK_TUNE_RESULT_OK);
    tick_at(&opts, &state, 0.1);
    test_rc |= expect_goto_entry(&state, what, fails ? 3U : 2U, fails ? 0U : 1U, fails ? 0U : 1U);
    test_rc |= expect_goto(what, dsd_engine_trunk_scan_entry_pending(&state) == 0);
    test_rc |= expect_hold_failure(&state, what, fails ? 2 : -1, "c", DSD_SCAN_GOTO_REFUSED);
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

static int
test_hold_start_pending_outcomes(void) {
    return hold_start_pending_case(0, "pending, lands") | hold_start_pending_case(1, "pending, fails late");
}

/* A park refused or deferred at the start: the scan runs on unheld, on to the next target as any failed start park
   goes, and the failure is kept for its toast, once. */
static int
test_hold_start_refused_park_runs_on_unheld(void) {
    static dsd_opts opts;
    static dsd_state state;
    int test_rc = 0;
    for (int deferred = 0; deferred < 2; deferred++) {
        const char* what = deferred ? "deferred park" : "refused park";
        scan_list_files files;
        char err[256];
        g_counting_tune_to_cc_failures_remaining = deferred ? 0 : 1;
        g_counting_tune_to_cc_deferrals_remaining = deferred ? 1 : 0;
        const int rc = hold_scan_start(&files, 0, "c", &opts, &state, err, sizeof err);
        test_rc |= expect_goto(what, rc == 0 && opts.trunk_scan_hold_id[0] == '\0');
        test_rc |= expect_goto_entry(&state, what, 3U, 0U, 0U);
        test_rc |= expect_goto(what, dsd_engine_trunk_scan_entry_pending(&state) == 0);
        test_rc |= expect_hold_failure(&state, what, 2, "c", deferred ? DSD_SCAN_GOTO_DEFERRED : DSD_SCAN_GOTO_REFUSED);
        test_rc |= expect_hold_log(what, deferred ? "WARNING: --trunk-scan-hold: the tune to target 'c' was deferred; "
                                                    "the scan runs on unheld\n"
                                                  : "WARNING: --trunk-scan-hold: the tune to target 'c' was refused; "
                                                    "the scan runs on unheld\n");
        g_counting_tune_to_cc_failures_remaining = 0;
        g_counting_tune_to_cc_deferrals_remaining = 0;
        scan_lists_finish(&files, &opts, &state);
    }
    return test_rc;
}

/* A one-target scan whose held start park is refused has nowhere else to go: it stays on that target unheld, and the
   failure is kept for its toast, once. */
static int
test_hold_start_single_target_refused_stays_unheld(void) {
    static const char* const names[] = {"only"};
    static const char* const bodies[] = {"solo,dmr-conventional,452000000,,250,,\n"};
    static dsd_opts opts;
    static dsd_state state;
    scan_list_files files;
    char err[256];
    g_scan_tune_to_freq_failures_remaining = 1;
    const int rc = hold_scan_start_lists(&files, names, bodies, 1, 0, "solo", &opts, &state, err, sizeof err);
    g_scan_tune_to_freq_failures_remaining = 0;
    int test_rc = expect_goto("one target, refused", rc == 0 && opts.trunk_scan_hold_id[0] == '\0');
    test_rc |= expect_goto_entry(&state, "one target, refused", 0U, 0U, 0U);
    test_rc |= expect_goto("one target, refused: nothing waits", dsd_engine_trunk_scan_entry_pending(&state) == 0);
    test_rc |= expect_hold_failure(&state, "one target, refused", 0, "solo", DSD_SCAN_GOTO_REFUSED);
    test_rc |= expect_hold_log("one target, refused",
                               "WARNING: --trunk-scan-hold: the tune to target 'solo' was refused; the scan runs on "
                               "unheld\n");
    scan_lists_finish(&files, &opts, &state);
    return test_rc;
}

/* --- Issue #834: the scan quiet check (scan_quiet.c) over a fake signal tap and a fake realtime clock, separate from
 * the TEST decode clock. The tap's request, status, take and cancel answer as signal_measure.cpp's do for one ticket;
 * the realtime clock is a link wrap (the ENGINE_NO_CARRIER_RESET pattern), so the bounds run on it alone. --- */
#ifdef DSD_NEO_TEST_RTL_WRAP
static int g_quiet_fake_rt = 0;
static uint64_t g_quiet_rt_ms = 0U;
/* The linker's --wrap names, as in ENGINE_NO_CARRIER_RESET. */
// NOLINTBEGIN(bugprone-reserved-identifier,cert-dcl37-c,cert-dcl51-cpp,misc-use-internal-linkage)
uint64_t __real_dsd_realtime_mono_ms(void);
uint64_t __wrap_dsd_realtime_mono_ms(void);

uint64_t
__wrap_dsd_realtime_mono_ms(void) {
    return g_quiet_fake_rt ? g_quiet_rt_ms : __real_dsd_realtime_mono_ms();
}

// NOLINTEND(bugprone-reserved-identifier,cert-dcl37-c,cert-dcl51-cpp,misc-use-internal-linkage)
#endif

#ifdef USE_RADIO
typedef struct {
    int have_capture;
    dsd_signal_capture capture;
    int capture_reads;
    int requests;
    int refuse;
    dsd_signal_quiet_request last_request;
    uint32_t ticket;
    uint32_t next_ticket;
    int status;
    dsd_signal_quiet_result result;
    int cancels;
    uint32_t last_cancel;
    uint32_t receive_seq;
    int rate_ok;
    int analog_ok;
} quiet_fake_tap;

static quiet_fake_tap g_tap;

int
rtl_signal_capture_get(dsd_signal_capture* capture) {
    g_tap.capture_reads++;
    if (!g_tap.have_capture || !capture) {
        return 0;
    }
    *capture = g_tap.capture;
    return 1;
}

int
rtl_signal_quiet_request(const dsd_signal_quiet_request* request, uint32_t* ticket,
                         dsd_signal_request_failure* out_failure) {
    g_tap.requests++;
    g_tap.last_request = *request;
    if (g_tap.refuse) {
        if (out_failure) {
            *out_failure = DSD_SIGNAL_REQUEST_UNSUPPORTED;
        }
        return -1;
    }
    g_tap.ticket = ++g_tap.next_ticket;
    g_tap.status = 0;
    *ticket = g_tap.ticket;
    return 0;
}

int
rtl_signal_quiet_status(uint32_t ticket) {
    if (ticket == 0U || ticket != g_tap.ticket) {
        return -1;
    }
    return g_tap.status;
}

int
rtl_signal_quiet_take(uint32_t ticket, dsd_signal_quiet_result* result) {
    const int status = rtl_signal_quiet_status(ticket);
    if (status == 0) {
        return 0;
    }
    DSD_MEMSET(result, 0, sizeof *result);
    if (status < 0) {
        result->failure = DSD_SIGNAL_MEASURE_SUPERSEDED;
        return -1;
    }
    *result = g_tap.result;
    result->request_id = g_tap.last_request.request_id;
    result->capture = g_tap.last_request.capture;
    g_tap.ticket = 0U;
    return result->failure == DSD_SIGNAL_MEASURE_OK ? 1 : -1;
}

void
rtl_signal_quiet_cancel(uint32_t ticket) {
    g_tap.cancels++;
    g_tap.last_cancel = ticket;
    if (ticket == g_tap.ticket) {
        g_tap.ticket = 0U;
    }
}

uint32_t
rtl_stream_receive_request_seq(void) {
    return g_tap.receive_seq;
}

int
dsd_signal_quiet_rate_supported(uint32_t rate_hz) {
    return g_tap.rate_ok && rate_hz != 0U;
}

/* The stream's width rule (io/radio/rtl_demod_config.cpp, which this fixture does not link), as it is: an explicit
   width as typed, else none for NFM and the kind's default for AM. */
int
rtl_demod_analog_requested_width_hz(int kind, int explicit_width_hz) {
    if (explicit_width_hz > 0) {
        return explicit_width_hz;
    }
    return kind == DSD_ANALOG_DEMOD_FM ? 0 : dsd_analog_width_default_hz(kind);
}

int
dsd_signal_quiet_analog_supported(int kind, uint32_t width_hz, uint32_t rate_hz) {
    return g_tap.analog_ok && (kind == DSD_ANALOG_DEMOD_FM || kind == DSD_ANALOG_DEMOD_AM) && width_hz != 0U
           && rate_hz != 0U;
}
#endif

#if defined(USE_RADIO) && defined(DSD_NEO_TEST_RTL_WRAP)
enum {
    QT_T0 = 100000,
    QT_GEN = 7,
};

static const uint32_t k_qt_hz_a = 452000000U;
static const uint32_t k_qt_hz_b = 453000000U;
static const char k_qt_targets[] = "a,dmr-conventional,452000000,,250,,\n"
                                   "b,dmr-conventional,453000000,,250,,\n";

static uint32_t g_quiet_stream_gen = 0U;

static uint32_t
quiet_stream_gen(void) {
    return g_quiet_stream_gen;
}

static int
qt_expect(const char* stage, int ok) {
    if (!ok) {
        DSD_FPRINTF(stderr, "FAIL #834 scan quiet: %s\n", stage);
        return 1;
    }
    return 0;
}

/* A capture of @p hz on output generation @p gen, Fs/4 shifted at 1.536 Msps. */
static void
quiet_tap_capture(uint32_t hz, uint32_t gen) {
    g_tap.have_capture = 1;
    DSD_MEMSET(&g_tap.capture, 0, sizeof g_tap.capture);
    g_tap.capture.rate_hz = 1536000U;
    g_tap.capture.capture_hz = hz;
    g_tap.capture.generation = gen;
    g_tap.capture.rotation_hz = 384000;
    g_tap.capture.gain = 20;
}

/* The tap answers the request outstanding: quiet or busy, or a failure. */
static void
quiet_tap_finish(int quiet, dsd_signal_measure_failure failure) {
    g_tap.status = 1;
    DSD_MEMSET(&g_tap.result, 0, sizeof g_tap.result);
    g_tap.result.failure = failure;
    g_tap.result.valid = failure == DSD_SIGNAL_MEASURE_OK ? 1U : 0U;
    g_tap.result.quiet = (quiet && failure == DSD_SIGNAL_MEASURE_OK) ? 1U : 0U;
    g_tap.result.max_ratio_db = 1.5f;
    g_tap.result.power_dbfs = -97.25f;
    g_tap.result.floor_dbfs = -98.75f;
    g_tap.result.completed_realtime_ns = g_quiet_rt_ms * 1000000ULL;
}

/* Two DMR conventional targets, the first landed by a synchronous retune at QT_T0 on stream generation QT_GEN; the
   stream then runs generation QT_GEN + 1 and the tap has its capture of target a. */
static int
quiet_rig_init(dsd_opts* opts, dsd_state* state, const char* path) {
    reset_scan_opts_state(opts, state);
    DSD_SNPRINTF(opts->trunk_scan_lists[0].path, sizeof opts->trunk_scan_lists[0].path, "%s", path);
    opts->trunk_scan_list_count = 1;
    opts->scan_skip_silent = 1;
    DSD_MEMSET(&g_tap, 0, sizeof g_tap);
    g_tap.rate_ok = 1;
    g_tap.analog_ok = 1;
    g_quiet_fake_rt = 1;
    g_quiet_rt_ms = QT_T0;
    trunk_scan_test_clear_now();
    dsd_decode_clock_use_test(1000000000000ULL);
    static const dsd_rtl_stream_metrics_hooks hooks = {.stream_generation = quiet_stream_gen};
    dsd_rtl_stream_metrics_hooks_set(&hooks);
    g_quiet_stream_gen = QT_GEN;
    char err[256] = {0};
    if (dsd_engine_trunk_scan_init(opts, state, err, sizeof err) != 0) {
        DSD_FPRINTF(stderr, "scan quiet rig: init failed: %s\n", err);
        return 1;
    }
    g_quiet_stream_gen = QT_GEN + 1;
    quiet_tap_capture(k_qt_hz_a, QT_GEN + 1);
    return 0;
}

static int
quiet_rig_start(dsd_opts* opts, dsd_state* state, char* dir, size_t dir_sz, char* path, size_t path_sz) {
    if (make_runtime_targets(k_qt_targets, path, path_sz, dir, dir_sz) != 0) {
        return 1;
    }
    return quiet_rig_init(opts, state, path);
}

/* The same rig with target a keyed (its keys file in @p keys_path), so a switch to it can fail its preparation. */
static int
quiet_rig_start_keyed(dsd_opts* opts, dsd_state* state, char* dir, size_t dir_sz, char* path, size_t path_sz,
                      char* keys_path, size_t keys_sz) {
    static const char header[] = "id,type,frequency_hz,chan_csv,dwell_ms,activity_hold_ms,notes,keys_hex_csv\n";
    if (make_temp_dir(dir, dir_sz) != 0 || dsd_test_path_join(keys_path, keys_sz, dir, "hexkeys.csv") != 0
        || write_text_file(keys_path, "key id(hex),key value (hex)\n0010,AAAAAAAAAAAAAAAA\n") != 0
        || write_targets_file_with_header(dir, header,
                                          "a,dmr-conventional,452000000,,250,,keyed,hexkeys.csv\n"
                                          "b,dmr-conventional,453000000,,250,,plain,\n",
                                          path, path_sz)
               != 0) {
        return 1;
    }
    return quiet_rig_init(opts, state, path);
}

static void
quiet_rig_finish(dsd_opts* opts, dsd_state* state, const char* dir, const char* path) {
    dsd_engine_trunk_scan_shutdown(opts, state);
    dsd_rtl_stream_metrics_hooks_set(NULL);
    dsd_decode_clock_use_system();
    g_quiet_fake_rt = 0;
    g_scan_tune_to_freq_pending = 0;
    cleanup_paths(dir, path, NULL);
}

/* The visit on air, published as engine service would: the landed target, the 12.5 kHz class. */
static scan_quiet_eligibility
quiet_elig(const dsd_opts* opts, const dsd_state* state) {
    scan_quiet_eligibility e;
    DSD_MEMSET(&e, 0, sizeof e);
    const dsd_engine_scan_landing* landing = dsd_engine_scan_landing_get(state);
    e.key.owner = SCAN_QUIET_OWNER_TRUNK;
    e.key.index = landing ? landing->index : -1;
    e.key.session = landing ? landing->session : 0U;
    e.key.epoch = landing ? landing->epoch : 0U;
    e.key.tune_request = landing ? landing->tune_request : 0U;
    e.eligible = 1;
    e.classes = DSD_SIGNAL_QUIET_CLASS_12K5;
    e.dsp_rate_hz = 48000U;
    e.frequency_hz = landing ? landing->hz : 0U;
    scan_quiet_revisions_read(opts, state, &e.revisions);
    return e;
}

/* The tick's apply, with this pass's facts as engine service works them out (quiet_elig()). */
static int
quiet_apply(dsd_opts* opts, dsd_state* state, int owner_kind) {
    const scan_quiet_eligibility current = quiet_elig(opts, state);
    return scan_quiet_apply(opts, state, owner_kind, &current);
}

static void
quiet_publish(dsd_opts* opts, dsd_state* state) {
    const scan_quiet_eligibility e = quiet_elig(opts, state);
    scan_quiet_publish_eligibility(opts, state, SCAN_QUIET_OWNER_TRUNK, &e);
}

/* The hunt's service @p ms of realtime later. */
static int
quiet_service_after(dsd_opts* opts, dsd_state* state, uint64_t ms) {
    g_quiet_rt_ms += ms;
    return dsd_engine_scan_quiet_service(opts, state);
}

/* Publish, measure and collect a quiet result: READY, and the hunt hands back. */
static int
quiet_to_ready(dsd_opts* opts, dsd_state* state) {
    quiet_publish(opts, state);
    if (scan_quiet_phase_get(state) != SCAN_QUIET_REQUESTED) {
        DSD_FPRINTF(stderr, "scan quiet: publish left phase %d (want REQUESTED)\n", (int)scan_quiet_phase_get(state));
        return 1;
    }
    quiet_tap_finish(1, DSD_SIGNAL_MEASURE_OK);
    const int handed_back = quiet_service_after(opts, state, 10U);
    return qt_expect("a quiet result is READY and the hunt hands back",
                     handed_back == 1 && scan_quiet_phase_get(state) == SCAN_QUIET_READY);
}

/* The same target, landed again: a new visit (a new epoch). */
static void
quiet_land_again(dsd_state* state, uint32_t hz) {
    const dsd_engine_scan_landing* landing = dsd_engine_scan_landing_get(state);
    const int index = landing->index;
    const uint32_t session = landing->session;
    dsd_engine_scan_landing_note_tune(state);
    g_quiet_stream_gen++;
    quiet_tap_capture(hz, g_quiet_stream_gen);
    dsd_engine_scan_landing_note_target(state, index, session, hz, 0U);
}

/* One measurement per visit: a quiet result is READY, handed back until consumed, applied once; the visit stays DONE
   and asks for no eligibility; the same target landed again is a new visit with its own measurement. */
static int
test_scan_quiet_measures_a_landed_target_once(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    int rc = qt_expect("the first landing has an epoch", dsd_engine_scan_landing_epoch(&state) != 0U);
    rc |= qt_expect("a landed visit wants eligibility", scan_quiet_wants_eligibility(&opts, &state, 1) == 1);
    rc |= quiet_to_ready(&opts, &state);
    rc |= qt_expect("one request", g_tap.requests == 1);
    rc |= qt_expect("the request names the landing", g_tap.last_request.frequency_hz == k_qt_hz_a
                                                         && g_tap.last_request.classes == DSD_SIGNAL_QUIET_CLASS_12K5
                                                         && g_tap.last_request.analog_width_hz == 0U
                                                         && g_tap.last_request.request_id != 0U
                                                         && g_tap.last_request.capture.generation == QT_GEN + 1);
    rc |= qt_expect("READY hands back again until the tick decides", quiet_service_after(&opts, &state, 5U) == 1);
    rc |= qt_expect("a -Y apply is not the trunk scan's", quiet_apply(&opts, &state, SCAN_QUIET_OWNER_Y) == 0);
    rc |= qt_expect("applied once", quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK) == 1);
    rc |= qt_expect("consumed: DONE", scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);
    rc |= qt_expect("not twice", quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK) == 0);
    rc |= qt_expect("DONE hands nothing back", quiet_service_after(&opts, &state, 5U) == 0);
    rc |= qt_expect("a DONE visit wants no eligibility", scan_quiet_wants_eligibility(&opts, &state, 1) == 0);
    quiet_publish(&opts, &state);
    rc |= qt_expect("republished, still DONE and no new request",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.requests == 1);

    quiet_land_again(&state, k_qt_hz_a);
    rc |= qt_expect("the same target revisited is a new visit", scan_quiet_wants_eligibility(&opts, &state, 1) == 1);
    quiet_publish(&opts, &state);
    rc |= qt_expect("the revisit measures again",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_REQUESTED && g_tap.requests == 2);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* WAIT_CAPTURE: a stream with no capture yet (startup), a capture of the generation read at the tune request, one of
   another output generation or centred elsewhere all wait; the capture is read at most every 50 ms; the landed capture
   is measured. The wait is bounded at 1000 ms from the landing's note, not from the first service (a synchronous
   landing before the first service). */
static int
test_scan_quiet_waits_for_the_landed_capture(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    g_tap.have_capture = 0;
    quiet_publish(&opts, &state);
    int rc = qt_expect("no capture yet: WAIT_CAPTURE",
                       scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE && g_tap.requests == 0);
    const int reads = g_tap.capture_reads;
    for (int i = 0; i < 4; i++) {
        (void)quiet_service_after(&opts, &state, 10U);
    }
    rc |= qt_expect("read again only after 50 ms", g_tap.capture_reads == reads);
    (void)quiet_service_after(&opts, &state, 10U);
    rc |= qt_expect("read again at 50 ms", g_tap.capture_reads == reads + 1);

    /* The stream has not moved past the generation read at the tune request: its capture is the pre-tune one. */
    g_quiet_stream_gen = QT_GEN;
    quiet_tap_capture(k_qt_hz_a, QT_GEN);
    (void)quiet_service_after(&opts, &state, 50U);
    rc |= qt_expect("the pre-tune generation waits", scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE);
    g_quiet_stream_gen = QT_GEN + 1;
    quiet_tap_capture(k_qt_hz_a, QT_GEN + 2); /* not the stream's live output generation */
    (void)quiet_service_after(&opts, &state, 50U);
    rc |= qt_expect("another output generation waits", scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE);
    quiet_tap_capture(k_qt_hz_b, QT_GEN + 1); /* centred elsewhere */
    (void)quiet_service_after(&opts, &state, 50U);
    rc |= qt_expect("another centre waits",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE && g_tap.requests == 0);
    quiet_tap_capture(k_qt_hz_a, QT_GEN + 1);
    (void)quiet_service_after(&opts, &state, 50U);
    rc |= qt_expect("the landed capture is measured",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_REQUESTED && g_tap.requests == 1);

    /* A landing noted at L, first serviced 700 ms later: the wait ends 1000 ms after L. */
    g_quiet_rt_ms += 1000U;
    quiet_land_again(&state, k_qt_hz_a);
    g_tap.have_capture = 0;
    const uint64_t landed = g_quiet_rt_ms;
    g_quiet_rt_ms = landed + 700U;
    quiet_publish(&opts, &state);
    rc |= qt_expect("late first service waits", scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE);
    g_quiet_rt_ms = landed + 999U;
    (void)dsd_engine_scan_quiet_service(&opts, &state);
    rc |= qt_expect("999 ms after the landing still waits", scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE);
    g_quiet_rt_ms = landed + 1000U;
    (void)dsd_engine_scan_quiet_service(&opts, &state);
    rc |= qt_expect("1000 ms after the landing: DONE, nothing requested",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.requests == 1);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* Known unsupported (DONE, nothing requested): centred I/Q (no Fs/4 rotation: Airspy, offset tuning, the shift off),
   a rate the calibration did not validate, an analog width or kind it did not; a request the tap refuses. Never an
   error. */
static int
test_scan_quiet_unsupported_capture_is_done(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    g_tap.capture.rotation_hz = 0;
    quiet_publish(&opts, &state);
    int rc = qt_expect("centred I/Q: DONE", scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.requests == 0);

    quiet_land_again(&state, k_qt_hz_a);
    g_tap.rate_ok = 0;
    quiet_publish(&opts, &state);
    rc |=
        qt_expect("an unvalidated rate: DONE", scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.requests == 0);
    g_tap.rate_ok = 1;

    quiet_land_again(&state, k_qt_hz_a);
    g_tap.analog_ok = 0;
    scan_quiet_eligibility e = quiet_elig(&opts, &state);
    e.classes = DSD_SIGNAL_QUIET_CLASS_ANALOG;
    e.analog_kind = DSD_ANALOG_DEMOD_FM;
    e.analog_width_hz = 10000U;
    scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
    rc |= qt_expect("an unvalidated analog width: DONE",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.requests == 0);
    g_tap.analog_ok = 1;

    quiet_land_again(&state, k_qt_hz_a);
    e = quiet_elig(&opts, &state);
    e.classes = DSD_SIGNAL_QUIET_CLASS_ANALOG;
    e.analog_kind = DSD_ANALOG_DEMOD_AM;
    e.analog_width_hz = 6000U;
    scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
    rc |= qt_expect("a validated analog width is measured at its width",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_REQUESTED
                        && g_tap.last_request.classes == DSD_SIGNAL_QUIET_CLASS_ANALOG
                        && g_tap.last_request.analog_width_hz == 6000U);

    quiet_land_again(&state, k_qt_hz_a);
    g_tap.refuse = 1;
    const int before = g_tap.requests;
    quiet_publish(&opts, &state);
    rc |= qt_expect("a refused request: DONE",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.requests == before + 1);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* REQUESTED: 400 ms (realtime) to answer, then cancelled and DONE; a lost, capture-changed or dropped request waits
   for the capture again, at most 3 times a visit; clipping, a non-finite sample or a failed transform end the visit
   at once; a busy result ends it. */
static int
test_scan_quiet_request_deadline_and_retries(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    quiet_publish(&opts, &state);
    const uint32_t ticket = g_tap.ticket;
    (void)quiet_service_after(&opts, &state, 399U);
    int rc = qt_expect("399 ms: still REQUESTED", scan_quiet_phase_get(&state) == SCAN_QUIET_REQUESTED);
    (void)quiet_service_after(&opts, &state, 1U);
    rc |= qt_expect("400 ms: cancelled, DONE", scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.cancels == 1
                                                   && g_tap.last_cancel == ticket);

    quiet_land_again(&state, k_qt_hz_a);
    quiet_publish(&opts, &state);
    static const dsd_signal_measure_failure k_retry[] = {
        DSD_SIGNAL_MEASURE_SUPERSEDED, DSD_SIGNAL_MEASURE_CAPTURE_CHANGED, DSD_SIGNAL_MEASURE_DROPPED};
    const int before = g_tap.requests;
    for (int i = 0; i < 3; i++) {
        quiet_tap_finish(0, k_retry[i]);
        (void)quiet_service_after(&opts, &state, 5U);
        rc |= qt_expect("a retried failure waits for the capture again",
                        scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE);
        (void)quiet_service_after(&opts, &state, 50U);
        rc |= qt_expect("and asks again",
                        scan_quiet_phase_get(&state) == SCAN_QUIET_REQUESTED && g_tap.requests == before + i + 1);
    }
    g_tap.ticket = 0U; /* lost: a search, a cancel or a reset moved the tap's ticket */
    (void)quiet_service_after(&opts, &state, 5U);
    rc |= qt_expect("a fourth retry is one too many: DONE",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.requests == before + 3);

    static const dsd_signal_measure_failure k_final[] = {DSD_SIGNAL_MEASURE_CLIPPED, DSD_SIGNAL_MEASURE_NONFINITE,
                                                         DSD_SIGNAL_MEASURE_FAILED};
    for (int i = 0; i < 3; i++) {
        quiet_land_again(&state, k_qt_hz_a);
        quiet_publish(&opts, &state);
        quiet_tap_finish(0, k_final[i]);
        (void)quiet_service_after(&opts, &state, 5U);
        rc |= qt_expect("clipped, non-finite or failed: DONE", scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);
    }
    quiet_land_again(&state, k_qt_hz_a);
    quiet_publish(&opts, &state);
    quiet_tap_finish(0, DSD_SIGNAL_MEASURE_OK);
    rc |= qt_expect("busy: no hand-back", quiet_service_after(&opts, &state, 5U) == 0);
    rc |= qt_expect("busy: DONE", scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* A READY result is the visit's only while the tap's capture is still the result's (a reacquire, a gain change, a
   drop), the stream's output generation is still its generation (a bump before the next block reaches the tap), no
   tune is pending, and it is at most 250 ms old. A hand-back declined after any of them is DONE. */
static int
test_scan_quiet_ready_rechecks_capture_generation_and_age(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    int rc = quiet_to_ready(&opts, &state);
    g_tap.capture.gain = 30;
    rc |= qt_expect("capture changed after retrieval: no hand-back", quiet_service_after(&opts, &state, 5U) == 0);
    rc |= qt_expect("capture changed after retrieval: declined, DONE",
                    quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK) == 0
                        && scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);

    quiet_land_again(&state, k_qt_hz_a);
    rc |= quiet_to_ready(&opts, &state);
    g_quiet_stream_gen++; /* no new tap block: the capture still names the old generation */
    rc |= qt_expect("output generation bumped after retrieval: no hand-back",
                    quiet_service_after(&opts, &state, 5U) == 0);
    rc |= qt_expect("output generation bumped after retrieval: declined, DONE",
                    quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK) == 0
                        && scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);

    g_quiet_stream_gen--;
    quiet_land_again(&state, k_qt_hz_a);
    rc |= quiet_to_ready(&opts, &state);
    const uint64_t pending = dsd_trunk_tuning_request_begin();
    rc |= qt_expect("a tune pending: no hand-back", quiet_service_after(&opts, &state, 5U) == 0);
    dsd_trunk_tuning_request_complete(pending, DSD_TRUNK_TUNE_RESULT_FAILED);
    rc |= qt_expect("none pending: hands back again", quiet_service_after(&opts, &state, 5U) == 1);
    rc |= qt_expect("250 ms old: still READY", quiet_service_after(&opts, &state, 230U) == 1);
    rc |= qt_expect("older than 250 ms: no hand-back", quiet_service_after(&opts, &state, 1U) == 0);
    rc |= qt_expect("older than 250 ms: DONE", scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* Activity since the request ends the check: a sync (any: the engine bumps the sequence for YSF and D-STAR syncs too,
   ENGINE_NO_CARRIER_RESET), whether requested or READY; a sync before the request does not. Allowed trunk-scan activity
   and an analog carrier heard decline a READY result. */
static int
test_scan_quiet_activity_since_the_request_ends_the_check(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    g_tap.have_capture = 0;
    quiet_publish(&opts, &state);
    dsd_engine_scan_quiet_note_sync(&state);
    quiet_tap_capture(k_qt_hz_a, QT_GEN + 1);
    (void)quiet_service_after(&opts, &state, 50U);
    int rc = qt_expect("a sync before the request: measured", scan_quiet_phase_get(&state) == SCAN_QUIET_REQUESTED);
    const uint32_t ticket = g_tap.ticket;
    dsd_engine_scan_quiet_note_sync(&state);
    (void)quiet_service_after(&opts, &state, 5U);
    rc |= qt_expect("a sync after the request: cancelled, DONE",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.last_cancel == ticket);

    /* A retry asks again, but activity still counts from the visit's first request. */
    quiet_land_again(&state, k_qt_hz_a);
    quiet_publish(&opts, &state);
    quiet_tap_finish(0, DSD_SIGNAL_MEASURE_CAPTURE_CHANGED);
    (void)quiet_service_after(&opts, &state, 5U);
    dsd_engine_scan_quiet_note_sync(&state);
    (void)quiet_service_after(&opts, &state, 50U);
    rc |= qt_expect("a sync between a retry's failure and its new request: DONE",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);

    quiet_land_again(&state, k_qt_hz_a);
    rc |= quiet_to_ready(&opts, &state);
    dsd_engine_scan_quiet_note_sync(&state);
    rc |= qt_expect("a sync while READY: no hand-back", quiet_service_after(&opts, &state, 5U) == 0);
    rc |= qt_expect("a sync while READY: DONE, no repeated hand-backs",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && quiet_service_after(&opts, &state, 5U) == 0);

    quiet_land_again(&state, k_qt_hz_a);
    rc |= quiet_to_ready(&opts, &state);
    dsd_engine_trunk_scan_dmr_conventional_activity(&opts, &state, 100U, 200U, 0, 0, 0);
    rc |= qt_expect("allowed activity since the request: no hand-back", quiet_service_after(&opts, &state, 5U) == 0);
    rc |= qt_expect("allowed activity since the request: declined",
                    quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK) == 0
                        && scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);

    /* Activity before the next request does not decline it. */
    dsd_decode_clock_test_set_ns(1001000000000ULL);
    quiet_land_again(&state, k_qt_hz_a);
    rc |= quiet_to_ready(&opts, &state);
    opts.analog_only = 1;
    opts.monitor_input_audio = 1;
    state.analog_rx.carrier_open = 1;
    rc |= qt_expect("an analog carrier heard: no hand-back", quiet_service_after(&opts, &state, 5U) == 0);
    state.analog_rx.carrier_open = 0;
    rc |= qt_expect("closed again: hands back", quiet_service_after(&opts, &state, 5U) == 1);
    opts.analog_only = 0;
    opts.monitor_input_audio = 0;
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

typedef void (*quiet_mutation_fn)(dsd_opts* opts, dsd_state* state);

static void
qt_mut_map(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    state->trunk_chan_map_seq++;
}

static void
qt_mut_list(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    state->lcn_list_rev++;
}

static void
qt_mut_lcn_avoid(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    state->lcn_avoid_rev++;
}

static void
qt_mut_trunk_avoid(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    state->trunk_scan_avoid_rev++;
}

static void
qt_mut_session(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    state->lcn_scan_session++;
}

static void
qt_mut_lists(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    state->trunk_scan_lists_seq++;
}

static void
qt_mut_input(dsd_opts* opts, dsd_state* state) {
    (void)state;
    opts->pcm_input_generation++;
}

static void
qt_mut_receive_request(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    (void)state;
    g_tap.receive_seq++;
}

static void
qt_mut_nfm_width(dsd_opts* opts, dsd_state* state) {
    (void)state;
    opts->analog_nfm_bandwidth_hz += 1000;
}

static void
qt_mut_am_width(dsd_opts* opts, dsd_state* state) {
    (void)state;
    opts->analog_am_bandwidth_hz += 1000;
}

static void
qt_mut_change(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    dsd_engine_scan_quiet_note_change(state);
}

/* An edit of the target not on air. */
static void
qt_mut_inactive_target_edit(dsd_opts* opts, dsd_state* state) {
    dsd_scan_row_edit_value value;
    DSD_MEMSET(&value, 0, sizeof value);
    value.squelch_db = -45;
    (void)dsd_engine_trunk_scan_edit_target(opts, state, state->scan_row_session, "b", DSD_SCAN_ROW_FIELD_SQUELCH,
                                            DSD_SCAN_ROW_EDIT_SET, &value, NULL);
}

static void
qt_mut_hold_toggle(dsd_opts* opts, dsd_state* state) {
    (void)dsd_engine_trunk_scan_control(opts, state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE);
}

static void
qt_mut_hold_twice(dsd_opts* opts, dsd_state* state) {
    qt_mut_hold_toggle(opts, state);
    qt_mut_hold_toggle(opts, state);
}

static void
qt_mut_setting_off_on(dsd_opts* opts, dsd_state* state) {
    opts->scan_skip_silent = 0;
    dsd_engine_scan_quiet_setting_changed(state);
    opts->scan_skip_silent = 1;
    dsd_engine_scan_quiet_setting_changed(state);
}

static void
qt_mut_y_entry_cancel(dsd_opts* opts, dsd_state* state) {
    (void)opts;
    dsd_engine_channel_scan_entry_cancel(state);
}

/* Spec §3.5: every counter the revision snapshot holds, and every mutation site that has none (quiet_inv_seq), cancels
   a request under way and suspends the check; republished, the visit measures afresh. Mutations that undo themselves
   in one pump (a hold and its release, the setting off and on) still count. */
static int
test_scan_quiet_revisions_suspend_the_check(void) {
    static const struct {
        const char* name;
        quiet_mutation_fn fn;
    } k_mutations[] = {
        {"channel map", qt_mut_map},
        {"-Y list", qt_mut_list},
        {"-Y avoid", qt_mut_lcn_avoid},
        {"trunk-scan avoid", qt_mut_trunk_avoid},
        {"-Y scan session", qt_mut_session},
        {"trunk-scan lists", qt_mut_lists},
        {"input switch", qt_mut_input},
        {"receive-profile request in flight", qt_mut_receive_request},
        {"configured NFM width", qt_mut_nfm_width},
        {"configured AM width", qt_mut_am_width},
        {"invalidation", qt_mut_change},
        {"edit of a target not on air", qt_mut_inactive_target_edit},
        {"hold", qt_mut_hold_toggle},
        {"hold and release in one pump", qt_mut_hold_twice},
        {"setting off and on in one pump", qt_mut_setting_off_on},
        {"-Y entry cancel (`Y`)", qt_mut_y_entry_cancel},
    };

    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    int rc = 0;
    for (size_t i = 0; i < sizeof k_mutations / sizeof k_mutations[0]; i++) {
        quiet_land_again(&state, k_qt_hz_a);
        quiet_publish(&opts, &state);
        const uint32_t ticket = g_tap.ticket;
        const int requests = g_tap.requests;
        k_mutations[i].fn(&opts, &state);
        (void)quiet_service_after(&opts, &state, 5U);
        if (scan_quiet_phase_get(&state) != SCAN_QUIET_SUSPENDED || g_tap.last_cancel != ticket) {
            DSD_FPRINTF(stderr, "FAIL #834 scan quiet: %s left phase %d, cancelled %u (want SUSPENDED, %u)\n",
                        k_mutations[i].name, (int)scan_quiet_phase_get(&state), g_tap.last_cancel, ticket);
            rc = 1;
        }
        rc |= qt_expect("SUSPENDED hands nothing back", quiet_service_after(&opts, &state, 5U) == 0);
        if (dsd_engine_trunk_scan_paused(&state) == 0 && dsd_engine_scan_landing_epoch(&state) != 0U) {
            quiet_publish(&opts, &state);
            if (scan_quiet_phase_get(&state) != SCAN_QUIET_REQUESTED || g_tap.requests != requests + 1) {
                DSD_FPRINTF(stderr, "FAIL #834 scan quiet: after %s the republished visit did not measure afresh\n",
                            k_mutations[i].name);
                rc = 1;
            }
        }
    }
    /* A READY result is suspended the same way, between the hunt's return and the tick. */
    quiet_land_again(&state, k_qt_hz_a);
    rc |= quiet_to_ready(&opts, &state);
    qt_mut_hold_twice(&opts, &state);
    rc |= qt_expect("a READY result held and released: declined",
                    quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK) == 0
                        && scan_quiet_phase_get(&state) == SCAN_QUIET_SUSPENDED);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* The mutation sites with no counter of their own bump quiet_inv_seq (spec §3.5): the trunk scan's hold, pause and
   resume, a park in flight, its stop; the -Y entry hold set and released; the setting. The landing epoch moves at
   every note and forget. */
static int
test_scan_quiet_mutation_sites_move_the_counters(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    dsd_engine_scan_owner* owner = dsd_engine_scan_owner_get(&state);
    int rc = qt_expect("an owner", owner != NULL);
    if (!owner) {
        quiet_rig_finish(&opts, &state, dir, path);
        return rc;
    }
    uint64_t inv = owner->quiet_inv_seq;
#define QT_MOVED(label)                                                                                                \
    do {                                                                                                               \
        rc |= qt_expect(label, owner->quiet_inv_seq != inv);                                                           \
        inv = owner->quiet_inv_seq;                                                                                    \
    } while (0)
    (void)dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE);
    QT_MOVED("hold set");
    (void)dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_HOLD_TOGGLE);
    QT_MOVED("hold released");
    (void)dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_TUNE);
    QT_MOVED("pause");
    (void)dsd_engine_trunk_scan_resume_locked(&opts, &state);
    QT_MOVED("resume");
    g_scan_tune_to_freq_pending = 1;
    (void)dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE);
    QT_MOVED("a park in flight (tune_pending set)");
    g_scan_tune_to_freq_pending = 0;
    dsd_engine_scan_quiet_setting_changed(&state);
    QT_MOVED("the setting");
    dsd_engine_scan_entry_hold_now(&state);
    QT_MOVED("-Y entry hold set");
    dsd_engine_scan_entry_hold_replaced(&state);
    QT_MOVED("-Y entry hold replaced");
    dsd_engine_channel_scan_entry_cancel(&state);
    QT_MOVED("-Y entry cancel");
    const uint64_t epoch = owner->landing_epoch;
    dsd_engine_scan_landing_forget(&state);
    rc |= qt_expect("a forget moves the landing epoch", owner->landing_epoch == epoch + 1U);
    dsd_engine_trunk_scan_shutdown(&opts, &state);
    QT_MOVED("scan stop");
#undef QT_MOVED
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* The landing record carries the visit's facts: the output generation read at the tune request (before the retune),
   the realtime it was noted at, the request whose tune landed, and an epoch moved at every note. */
static int
test_scan_quiet_landing_records_the_tune(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    const dsd_engine_scan_landing* landing = dsd_engine_scan_landing_get(&state);
    int rc = qt_expect("the init's synchronous park",
                       landing && landing->index == 0 && landing->hz == k_qt_hz_a && landing->tune_request == 0U
                           && landing->generation_before_tune == QT_GEN && landing->landed_realtime_ms == QT_T0);
    const uint64_t epoch = landing->epoch;
    g_quiet_rt_ms += 25U;
    g_scan_tune_to_freq_pending = 1;
    (void)dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE);
    rc |= qt_expect("a park in flight: no landing", dsd_engine_scan_landing_epoch(&state) == 0U);
    const uint64_t park = g_scan_tune_pending_request;
    g_quiet_stream_gen = QT_GEN + 5;
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_OK);
    rc |= qt_expect("the ledger's lock-free peek sees the park land", dsd_trunk_tuning_request_landed(park) == 1);
    g_quiet_rt_ms += 25U;
    dsd_engine_trunk_scan_tick(&opts, &state);
    landing = dsd_engine_scan_landing_get(&state);
    rc |= qt_expect("the park's landing", landing->index == 1 && landing->tune_request == park
                                              && landing->generation_before_tune == QT_GEN + 1
                                              && landing->landed_realtime_ms == QT_T0 + 50U && landing->epoch > epoch);
    const uint64_t other = dsd_trunk_tuning_request_begin();
    dsd_trunk_tuning_request_complete(other, DSD_TRUNK_TUNE_RESULT_OK);
    rc |= qt_expect("a later landing supersedes the peek", dsd_trunk_tuning_request_landed(park) == 0
                                                               && dsd_trunk_tuning_request_landed(other) == 1
                                                               && dsd_trunk_tuning_request_landed(0U) == 0);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* A park in flight: the hunt starts the measurement once the ledger publishes its completion (read lock-free), before
   the tick notes the landing; the WAIT_CAPTURE bound runs from that read. The coordinator's landing with the same
   tune_request adopts it; any other landing discards it. */
static int
test_scan_quiet_adopts_a_park_measured_in_flight(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    int rc = 0;
    for (int adopt = 1; adopt >= 0; adopt--) {
        if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
            return 1;
        }
        const uint32_t session = dsd_engine_scan_landing_get(&state)->session;
        g_scan_tune_to_freq_pending = 1;
        (void)dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE);
        const uint64_t park = g_scan_tune_pending_request;
        scan_quiet_eligibility e = quiet_elig(&opts, &state);
        e.key.index = 1;
        e.key.session = session;
        e.key.tune_request = park;
        e.frequency_hz = k_qt_hz_b;
        scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
        rc |= qt_expect("in flight: waits", scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE);
        const int reads = g_tap.capture_reads;
        (void)quiet_service_after(&opts, &state, 2000U);
        rc |= qt_expect("in flight: no capture read, no bound",
                        g_tap.capture_reads == reads && scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE);
        g_quiet_stream_gen = QT_GEN + 3;
        quiet_tap_capture(k_qt_hz_b, QT_GEN + 3);
        dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_OK);
        (void)quiet_service_after(&opts, &state, 5U);
        rc |= qt_expect("the completion read: measured before the tick",
                        scan_quiet_phase_get(&state) == SCAN_QUIET_REQUESTED
                            && g_tap.last_request.frequency_hz == k_qt_hz_b);
        quiet_tap_finish(1, DSD_SIGNAL_MEASURE_OK);
        rc |=
            qt_expect("READY before the landing: hands back for the tick", quiet_service_after(&opts, &state, 5U) == 1);
        rc |= qt_expect("not applied before the landing is noted",
                        quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK) == 0
                            && scan_quiet_phase_get(&state) == SCAN_QUIET_READY);
        if (adopt) {
            dsd_engine_trunk_scan_tick(&opts, &state);
            const uint64_t epoch = dsd_engine_scan_landing_epoch(&state);
            rc |= qt_expect("the tick noted the park's landing", epoch != 0U);
            rc |=
                qt_expect("adopted on a matching tune_request", quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK) == 1
                                                                    && scan_quiet_key_get(&state).epoch == epoch);
            quiet_publish(&opts, &state);
            rc |= qt_expect("the adopted visit stays DONE",
                            scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.requests == 1);
        } else {
            dsd_engine_scan_landing_note_target(&state, 1, e.key.session, k_qt_hz_b, park + 1000U);
            rc |= qt_expect("discarded on another tune_request",
                            quiet_service_after(&opts, &state, 5U) == 0
                                && scan_quiet_phase_get(&state) == SCAN_QUIET_SUSPENDED);
        }
        quiet_rig_finish(&opts, &state, dir, path);
    }

    /* The bound runs from the completion read: 1000 ms after it with no capture, DONE. */
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    const uint32_t session = dsd_engine_scan_landing_get(&state)->session;
    g_scan_tune_to_freq_pending = 1;
    (void)dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE);
    const uint64_t park = g_scan_tune_pending_request;
    scan_quiet_eligibility e = quiet_elig(&opts, &state);
    e.key.index = 1;
    e.key.session = session;
    e.key.tune_request = park;
    e.frequency_hz = k_qt_hz_b;
    scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
    g_tap.have_capture = 0;
    g_quiet_rt_ms += 300U;
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_OK);
    (void)dsd_engine_scan_quiet_service(&opts, &state);
    const uint64_t read_at = g_quiet_rt_ms;
    g_quiet_rt_ms = read_at + 999U;
    (void)dsd_engine_scan_quiet_service(&opts, &state);
    rc |= qt_expect("999 ms after the completion read: waits", scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE);
    g_quiet_rt_ms = read_at + 1000U;
    (void)dsd_engine_scan_quiet_service(&opts, &state);
    rc |= qt_expect("1000 ms after the completion read: DONE", scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* SUSPENDED: an ineligible visit (the owner's conditions, no class, an analog class with no width, a session that is
   no RTL input or is an I/Q replay by the stream or by the decode clock) requests nothing, and the hunt's service
   returns 0 without reading the tap. The setting off: nothing published, nothing asked. */
static int
test_scan_quiet_suspended_visit_requests_nothing(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    int rc = 0;
    for (int variant = 0; variant < 8; variant++) {
        scan_quiet_eligibility e = quiet_elig(&opts, &state);
        switch (variant) {
            case 0: e.eligible = 0; break;
            case 1: e.classes = 0U; break;
            case 2:
                e.classes = DSD_SIGNAL_QUIET_CLASS_ANALOG;
                e.analog_width_hz = 0U;
                break;
            case 3: opts.audio_in_type = AUDIO_IN_UDP; break;
            case 4: opts.iq_replay_active = 1U; break;
            case 5: opts.iq_replay_requested = 1U; break;
            case 6: dsd_decode_clock_use_replay(1700000000); break;
            default: e.key.epoch += 1U; break; /* not the visit on air */
        }
        const int reads = g_tap.capture_reads;
        scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
        int handed_back = 0;
        for (int i = 0; i < 10; i++) {
            handed_back |= quiet_service_after(&opts, &state, 100U);
        }
        if (scan_quiet_phase_get(&state) != SCAN_QUIET_SUSPENDED || handed_back || g_tap.requests != 0
            || g_tap.capture_reads != reads) {
            DSD_FPRINTF(stderr, "FAIL #834 scan quiet: ineligible variant %d: phase %d, hand-back %d, requests %d\n",
                        variant, (int)scan_quiet_phase_get(&state), handed_back, g_tap.requests);
            rc = 1;
        }
        opts.audio_in_type = AUDIO_IN_RTL;
        opts.iq_replay_active = 0U;
        opts.iq_replay_requested = 0U;
        dsd_decode_clock_use_test(1000000000000ULL);
    }
    opts.scan_skip_silent = 0;
    rc |= qt_expect("setting off: no eligibility wanted", scan_quiet_wants_eligibility(&opts, &state, 1) == 0);
    quiet_publish(&opts, &state);
    rc |= qt_expect("setting off: nothing published",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_SUSPENDED && g_tap.requests == 0);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

static int g_qt_service_calls = 0;

static int
qt_counting_service(const dsd_opts* opts, dsd_state* state) {
    (void)opts;
    (void)state;
    g_qt_service_calls++;
    return 1;
}

/* The hunt's hook with the setting off is one load of the setting and 0: the engine's service is never called (the
   decoder state is not even read: NULL here). With it on, the engine's answer. The engine's own service with no check
   made answers 0. */
static int
test_scan_quiet_hook_off_is_one_load(void) {
    static dsd_opts opts;
    static dsd_state state;
    DSD_MEMSET(&opts, 0, sizeof opts);
    dsd_frame_sync_hooks saved;
    dsd_frame_sync_hooks_get(&saved);
    dsd_frame_sync_hooks hooks = saved;
    hooks.scan_quiet_service = qt_counting_service;
    dsd_frame_sync_hooks_set(&hooks);
    g_qt_service_calls = 0;
    int rc = qt_expect("off: 0", dsd_frame_sync_hook_scan_quiet_service(&opts, NULL) == 0);
    rc |= qt_expect("off: the engine is not asked", g_qt_service_calls == 0);
    opts.scan_skip_silent = 1;
    rc |= qt_expect("on: the engine's answer", dsd_frame_sync_hook_scan_quiet_service(&opts, &state) == 1);
    rc |= qt_expect("on: asked once", g_qt_service_calls == 1);
    dsd_frame_sync_hooks_set(&saved);
    rc |= qt_expect("no check made: 0", dsd_engine_scan_quiet_service(&opts, &state) == 0);
    return rc;
}

/* "Any decline -> DONE except a lost guard": the engine saw READY and will not apply it; a tick that lost the guard
   leaves it READY, so the next hunt point hands back again. */
static int
test_scan_quiet_decline_ends_it_unless_the_guard_was_lost(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    int rc = quiet_to_ready(&opts, &state);
    scan_quiet_reconcile_declined(&opts, &state, SCAN_QUIET_OWNER_TRUNK, 1);
    rc |= qt_expect("guard lost: still READY, hands back again",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_READY && quiet_service_after(&opts, &state, 5U) == 1);
    scan_quiet_reconcile_declined(&opts, &state, SCAN_QUIET_OWNER_Y, 0);
    rc |= qt_expect("another owner's decline leaves it", scan_quiet_phase_get(&state) == SCAN_QUIET_READY);
    scan_quiet_reconcile_declined(&opts, &state, SCAN_QUIET_OWNER_TRUNK, 0);
    rc |= qt_expect("declined: DONE, no repeated hand-backs",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && quiet_service_after(&opts, &state, 5U) == 0);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* Spec §3.4 (1) at the decision itself: the classes, the analog kind and width, and the DSP rate in force when the tick
   applies (this pass's facts, given to scan_quiet_apply()) must be the ones measured. A class change, an analog width
   change and a DSP rate change between the measurement and the apply each decline (DONE); unchanged facts apply. */
static int
test_scan_quiet_apply_checks_the_facts_in_force(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    int rc = 0;
    for (int change = 0; change < 5; change++) {
        quiet_land_again(&state, k_qt_hz_a);
        scan_quiet_eligibility e = quiet_elig(&opts, &state);
        e.classes = DSD_SIGNAL_QUIET_CLASS_12K5 | DSD_SIGNAL_QUIET_CLASS_ANALOG;
        e.analog_kind = DSD_ANALOG_DEMOD_FM;
        e.analog_width_hz = 12500U;
        scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
        quiet_tap_finish(1, DSD_SIGNAL_MEASURE_OK);
        rc |= qt_expect("a mixed visit is READY", quiet_service_after(&opts, &state, 10U) == 1);
        scan_quiet_eligibility now = e;
        switch (change) {
            case 0: now.classes = DSD_SIGNAL_QUIET_CLASS_12K5 | DSD_SIGNAL_QUIET_CLASS_6K25; break;
            case 1: now.analog_width_hz = 16000U; break;
            case 2: now.dsp_rate_hz = 24000U; break;
            case 3: now.analog_kind = DSD_ANALOG_DEMOD_AM; break; /* the same width, another kind */
            default: break;                                       /* unchanged */
        }
        const int applied = scan_quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &now);
        if (applied != (change == 4) || scan_quiet_phase_get(&state) != SCAN_QUIET_DONE) {
            DSD_FPRINTF(stderr, "FAIL #834 scan quiet: facts change %d applied %d, phase %d\n", change, applied,
                        (int)scan_quiet_phase_get(&state));
            rc = 1;
        }
    }
    quiet_land_again(&state, k_qt_hz_a);
    rc |= quiet_to_ready(&opts, &state);
    rc |= qt_expect("no facts given: declined", scan_quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK, NULL) == 0
                                                    && scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* D4 mixed sets: a digital decoder set with the -8 analog monitor on is judged in the analog class too, at the
   configured kind and width; outside the calibrated analog domain the visit gets no check (DONE, nothing requested). */
static int
test_scan_quiet_mixed_set_judges_the_analog_class(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    opts.frame_dmr = 1;
    opts.monitor_input_audio = 1;
    opts.analog_demod = DSD_ANALOG_DEMOD_AM;
    opts.analog_am_bandwidth_hz = 10000;
    int rc = 0;
    for (int domain = 0; domain <= 1; domain++) {
        quiet_land_again(&state, k_qt_hz_a);
        g_tap.analog_ok = domain;
        scan_quiet_eligibility e = quiet_elig(&opts, &state);
        int kind = -1;
        uint32_t width = 0U;
        e.classes = scan_quiet_decoder_classes(&opts, &kind, &width);
        e.analog_kind = kind;
        e.analog_width_hz = width;
        const int requests = g_tap.requests;
        scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
        if (domain) {
            rc |= qt_expect("a mixed set inside the domain is measured in both classes at the configured width",
                            scan_quiet_phase_get(&state) == SCAN_QUIET_REQUESTED
                                && g_tap.last_request.classes
                                       == (DSD_SIGNAL_QUIET_CLASS_12K5 | DSD_SIGNAL_QUIET_CLASS_ANALOG)
                                && g_tap.last_request.analog_width_hz == 10000U);
        } else {
            rc |= qt_expect("a mixed set outside the analog domain: no check",
                            scan_quiet_phase_get(&state) == SCAN_QUIET_DONE && g_tap.requests == requests);
        }
    }
    /* An unset width resolves as the stream runs it: AM at its 6 kHz default is measured there; an unset NFM width has
       no definite channel, so nothing is published as eligible and nothing is requested. */
    for (int am = 1; am >= 0; am--) {
        quiet_land_again(&state, k_qt_hz_a);
        g_tap.analog_ok = 1;
        opts.analog_demod = am ? DSD_ANALOG_DEMOD_AM : DSD_ANALOG_DEMOD_FM;
        opts.analog_am_bandwidth_hz = 0;
        opts.analog_nfm_bandwidth_hz = 0;
        scan_quiet_eligibility e = quiet_elig(&opts, &state);
        int kind = -1;
        uint32_t width = 0U;
        e.classes = scan_quiet_decoder_classes(&opts, &kind, &width);
        e.analog_kind = kind;
        e.analog_width_hz = width;
        const int requests = g_tap.requests;
        scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
        if (am) {
            rc |= qt_expect("an unset AM width is measured at the 6 kHz default",
                            scan_quiet_phase_get(&state) == SCAN_QUIET_REQUESTED
                                && g_tap.last_request.classes
                                       == (DSD_SIGNAL_QUIET_CLASS_12K5 | DSD_SIGNAL_QUIET_CLASS_ANALOG)
                                && g_tap.last_request.analog_width_hz == 6000U);
        } else {
            rc |= qt_expect("an unset NFM width: no check", e.classes == 0U
                                                                && scan_quiet_phase_get(&state) == SCAN_QUIET_SUSPENDED
                                                                && g_tap.requests == requests);
        }
    }
    opts.analog_demod = DSD_ANALOG_DEMOD_FM;
    opts.frame_dmr = 0;
    opts.monitor_input_audio = 0;
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

/* An in-flight park whose completion the hunt never read lock-free (another landing succeeded first, so the peek is no
   longer its) is still bounded once adopted: the wait runs 1000 ms from the landing's note, then DONE. */
static int
test_scan_quiet_adopted_park_is_bounded_from_its_landing(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    const uint32_t session = dsd_engine_scan_landing_get(&state)->session;
    g_scan_tune_to_freq_pending = 1;
    (void)dsd_engine_trunk_scan_control(&opts, &state, DSD_TRUNK_SCAN_CONTROL_ADVANCE);
    const uint64_t park = g_scan_tune_pending_request;
    scan_quiet_eligibility e = quiet_elig(&opts, &state);
    e.key.index = 1;
    e.key.session = session;
    e.key.tune_request = park;
    e.frequency_hz = k_qt_hz_b;
    scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
    g_tap.have_capture = 0;
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_OK);
    const uint64_t other = dsd_trunk_tuning_request_begin();
    dsd_trunk_tuning_request_complete(other, DSD_TRUNK_TUNE_RESULT_OK);
    int rc = qt_expect("the peek is no longer the park's", dsd_trunk_tuning_request_landed(park) == 0);
    g_quiet_rt_ms += 100U;
    dsd_engine_trunk_scan_tick(&opts, &state);
    const uint64_t landed = g_quiet_rt_ms;
    rc |= qt_expect("the tick noted the park's landing", dsd_engine_scan_landing_get(&state)->tune_request == park);
    g_quiet_rt_ms = landed + 999U;
    (void)dsd_engine_scan_quiet_service(&opts, &state);
    rc |= qt_expect("adopted, 999 ms after the landing: waits",
                    scan_quiet_phase_get(&state) == SCAN_QUIET_WAIT_CAPTURE
                        && scan_quiet_key_get(&state).epoch == dsd_engine_scan_landing_epoch(&state));
    g_quiet_rt_ms = landed + 1000U;
    (void)dsd_engine_scan_quiet_service(&opts, &state);
    rc |= qt_expect("adopted, 1000 ms after the landing: DONE", scan_quiet_phase_get(&state) == SCAN_QUIET_DONE);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

typedef int (*quiet_site_fn)(dsd_opts* opts, dsd_state* state);

static int
qt_site_y_leave(dsd_opts* opts, dsd_state* state) {
    (void)dsd_engine_channel_scan_leave(opts, state);
    return 0;
}

static int
qt_site_y_pause(dsd_opts* opts, dsd_state* state) {
    opts->scanner_mode = 1;
    (void)dsd_engine_channel_scan_pause(opts, state, 0);
    return 0;
}

static int
qt_site_y_resume_landed(dsd_opts* opts, dsd_state* state) {
    state->lcn_scan_resume_pending = 1U;
    dsd_engine_channel_scan_resume_landed(opts, state);
    opts->scanner_mode = 0;
    return 0;
}

static int
qt_site_y_resume_failed(dsd_opts* opts, dsd_state* state) {
    dsd_engine_channel_scan_resume_failed(opts, state, (long)k_qt_hz_a, DSD_SCAN_RESUME_FAILED_TUNE);
    state->lcn_scan_paused = 0U;
    return 0;
}

static int
qt_site_y_entry_release(dsd_opts* opts, dsd_state* state) {
    state->lcn_scan_hold = 1U;
    state->lcn_scan_entry_hold = 1U;
    dsd_engine_channel_scan_entry_release(opts, state);
    return 0;
}

/* A -Y start that lets an ordinary hold go (the receiver is not on the row it held). */
static int
qt_site_y_start_settles_hold(dsd_opts* opts, dsd_state* state) {
    state->lcn_scan_hold = 1U;
    opts->rtlsdr_center_freq = 1U; /* a centre known, and no row's */
    DSD_SNPRINTF(opts->chan_in_file, sizeof opts->chan_in_file, "%s", "channels.csv");
    dsd_engine_channel_scan_config_start(opts, state);
    opts->chan_in_file[0] = '\0';
    return state->lcn_scan_hold != 0U;
}

/* A go-to of the target on air takes the entry hold at once. */
static int
qt_site_trunk_goto_on_air(dsd_opts* opts, dsd_state* state) {
    return goto_target(opts, state, 0, NULL) != DSD_SCAN_GOTO_HOLDING;
}

/* Spec §3.5 mutation sites with no counter of their own, each from a READY result: the site moves quiet_inv_seq and
   the held READY result is declined, not applied. */
static int
test_scan_quiet_more_mutation_sites_decline_a_ready_result(void) {
    static const struct {
        const char* name;
        quiet_site_fn fn;
    } k_sites[] = {
        {"-Y leave (channel_scan_release)", qt_site_y_leave},
        {"-Y pause", qt_site_y_pause},
        {"-Y resume landed", qt_site_y_resume_landed},
        {"-Y untyped resume failed", qt_site_y_resume_failed},
        {"-Y entry release", qt_site_y_entry_release},
        {"-Y start lets a hold go", qt_site_y_start_settles_hold},
        {"trunk go-to on air: entry hold now", qt_site_trunk_goto_on_air},
    };

    int rc = 0;
    for (size_t i = 0; i < sizeof k_sites / sizeof k_sites[0]; i++) {
        char dir[DSD_TEST_PATH_MAX];
        char path[DSD_TEST_PATH_MAX];
        static dsd_opts opts;
        static dsd_state state;
        if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
            return 1;
        }
        rc |= quiet_to_ready(&opts, &state);
        const dsd_engine_scan_owner* owner = dsd_engine_scan_owner_get(&state);
        const uint64_t inv = owner->quiet_inv_seq;
        const int setup_failed = k_sites[i].fn(&opts, &state);
        const int moved = owner->quiet_inv_seq != inv;
        const int applied = quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK);
        if (setup_failed || !moved || applied || scan_quiet_phase_get(&state) == SCAN_QUIET_READY) {
            DSD_FPRINTF(stderr, "FAIL #834 scan quiet: %s: ran %d, moved %d, applied %d\n", k_sites[i].name,
                        !setup_failed, moved, applied);
            rc = 1;
        }
        quiet_rig_finish(&opts, &state, dir, path);
    }
    return rc;
}

/* The trunk scan's go-to sites. A go-to over an entry hold drops the hold, and one whose preparation fails puts it
   back: two moves, each one a mutation of the hold, and the READY result held over them is declined. A park a go-to
   waits on lands at the tick and takes the entry hold there: a READY result measured in flight is declined. A resume
   that fails rolls back to paused: the resume, the rollback and the scope leave it runs each move the counter. */
static int
test_scan_quiet_trunk_goto_and_resume_sites(void) {
    char dir[DSD_TEST_PATH_MAX];
    char path[DSD_TEST_PATH_MAX];
    char keys[DSD_TEST_PATH_MAX];
    static dsd_opts opts;
    static dsd_state state;
    if (quiet_rig_start_keyed(&opts, &state, dir, sizeof dir, path, sizeof path, keys, sizeof keys) != 0) {
        return 1;
    }
    int rc = qt_expect("go-to b holds it", goto_target(&opts, &state, 1, NULL) == DSD_SCAN_GOTO_HOLDING);
    quiet_land_again(&state, k_qt_hz_b);
    rc |= quiet_to_ready(&opts, &state);
    const dsd_engine_scan_owner* owner = dsd_engine_scan_owner_get(&state);
    uint64_t inv = owner->quiet_inv_seq;
    dsd_key_set_test_alloc_fail_after(0);
    const dsd_scan_goto_result got = goto_target(&opts, &state, 0, NULL);
    dsd_key_set_test_alloc_fail_after(-1);
    rc |= qt_expect("an unprepared go-to over the entry hold", got == DSD_SCAN_GOTO_SETUP_FAILED);
    rc |= qt_expect("the hold dropped and put back: two moves", owner->quiet_inv_seq == inv + 2U);
    rc |=
        qt_expect("the READY result held over it is declined", quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK) == 0
                                                                   && scan_quiet_phase_get(&state) != SCAN_QUIET_READY);
    quiet_rig_finish(&opts, &state, dir, path);
    (void)remove(keys);

    /* A go-to's park in flight, measured before the tick: the tick lands it and takes the entry hold. */
    if (quiet_rig_start(&opts, &state, dir, sizeof dir, path, sizeof path) != 0) {
        return 1;
    }
    owner = dsd_engine_scan_owner_get(&state);
    const uint32_t session = dsd_engine_scan_landing_get(&state)->session;
    g_scan_tune_to_freq_pending = 1;
    rc |= qt_expect("go-to b waits on its park", goto_target(&opts, &state, 1, NULL) == DSD_SCAN_GOTO_PENDING);
    const uint64_t park = g_scan_tune_pending_request;
    scan_quiet_eligibility e = quiet_elig(&opts, &state);
    e.key.index = 1;
    e.key.session = session;
    e.key.tune_request = park;
    e.frequency_hz = k_qt_hz_b;
    scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
    g_quiet_stream_gen = QT_GEN + 3;
    quiet_tap_capture(k_qt_hz_b, QT_GEN + 3);
    dsd_trunk_tuning_request_publish(park, DSD_TRUNK_TUNE_RESULT_OK);
    (void)quiet_service_after(&opts, &state, 5U);
    quiet_tap_finish(1, DSD_SIGNAL_MEASURE_OK);
    rc |= qt_expect("READY in flight", quiet_service_after(&opts, &state, 5U) == 1);
    inv = owner->quiet_inv_seq;
    dsd_engine_trunk_scan_tick(&opts, &state);
    rc |= qt_expect("the landed go-to takes the entry hold: a move", owner->quiet_inv_seq != inv);
    rc |= qt_expect("the READY result measured in flight is declined",
                    quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK) == 0
                        && scan_quiet_phase_get(&state) != SCAN_QUIET_READY);

    /* A resume whose retune is refused rolls back to paused. */
    rc |= qt_expect("pauses", dsd_engine_trunk_scan_pause_locked(&opts, &state, DSD_TRUNK_SCAN_PAUSE_TUNE) == 0);
    g_scan_tune_to_freq_pending = 0;
    g_scan_tune_to_freq_failures_remaining = 8;
    inv = owner->quiet_inv_seq;
    (void)dsd_engine_trunk_scan_resume_locked(&opts, &state);
    g_scan_tune_to_freq_failures_remaining = 0;
    rc |= qt_expect("a refused resume stays paused", dsd_engine_trunk_scan_paused(&state) == 1);
    /* The resume, the rollback to paused, and the scope leave the rollback runs (channel_scan_release()). */
    rc |= qt_expect("the resume, its rollback and its leave: three moves", owner->quiet_inv_seq == inv + 3U);
    quiet_rig_finish(&opts, &state, dir, path);
    return rc;
}

#endif

/* The NOTICE line (spec §3.4 format) and the width classes (spec §2.2). */
static int
test_scan_quiet_notice_and_classes(void) {
    char line[192];
    (void)scan_quiet_format_skip(line, sizeof line, "County Fire", 0, 154430000U, -97.25f, -98.75f, 1.5f);
    int rc = 0;
    if (strcmp(line, "NOTICE: scan: skipped quiet County Fire 154.430000 MHz: -97.2 dBFS, floor -98.8 dBFS (1.5 dB)\n")
        != 0) {
        DSD_FPRINTF(stderr, "FAIL #834 scan quiet: notice '%s'\n", line);
        rc = 1;
    }
    (void)scan_quiet_format_skip(line, sizeof line, NULL, 2, 462675000U, -101.0f, -103.5f, 2.5f);
    if (strcmp(line, "NOTICE: scan: skipped quiet row 3 462.675000 MHz: -101.0 dBFS, floor -103.5 dBFS (2.5 dB)\n")
        != 0) {
        DSD_FPRINTF(stderr, "FAIL #834 scan quiet: notice '%s'\n", line);
        rc = 1;
    }
    rc |= scan_quiet_mode_classes(DSD_SCAN_MODE_P25) != 1U || scan_quiet_mode_classes(DSD_SCAN_MODE_DMR) != 1U
          || scan_quiet_mode_classes(DSD_SCAN_MODE_NXDN96) != 1U || scan_quiet_mode_classes(DSD_SCAN_MODE_YSF) != 1U
          || scan_quiet_mode_classes(DSD_SCAN_MODE_M17) != 1U || scan_quiet_mode_classes(DSD_SCAN_MODE_NXDN48) != 2U
          || scan_quiet_mode_classes(DSD_SCAN_MODE_DPMR) != 2U || scan_quiet_mode_classes(DSD_SCAN_MODE_DSTAR) != 2U
          || scan_quiet_mode_classes(DSD_SCAN_MODE_NFM) != 4U || scan_quiet_mode_classes(DSD_SCAN_MODE_AM) != 4U
          || scan_quiet_mode_classes(DSD_SCAN_MODE_INHERIT) != 0U;
    static dsd_opts opts;
    DSD_MEMSET(&opts, 0, sizeof opts);
    opts.analog_nfm_bandwidth_hz = 12500;
    opts.analog_am_bandwidth_hz = 6000;
    int kind = -1;
    uint32_t width = 1U;
    opts.frame_dmr = 1;
    rc |= scan_quiet_decoder_classes(&opts, &kind, &width) != 1U || kind != 0 || width != 0U;
    opts.frame_dstar = 1;
    rc |= scan_quiet_decoder_classes(&opts, NULL, NULL) != 3U;
    /* The -8 analog monitor beside a digital set: a mixed set, the analog class judged at the configured kind and
       width (D4). */
    opts.monitor_input_audio = 1;
    rc |= scan_quiet_decoder_classes(&opts, &kind, &width) != 7U || kind != DSD_ANALOG_DEMOD_FM || width != 12500U;
    opts.analog_demod = DSD_ANALOG_DEMOD_AM;
    rc |= scan_quiet_decoder_classes(&opts, &kind, &width) != 7U || kind != DSD_ANALOG_DEMOD_AM || width != 6000U;
#ifdef USE_RADIO
    /* An unset AM width runs the AM default, a definite 6 kHz channel the calibration covers: judged there. */
    opts.analog_am_bandwidth_hz = 0;
    rc |= scan_quiet_decoder_classes(&opts, &kind, &width) != 7U || kind != DSD_ANALOG_DEMOD_AM || width != 6000U;
#endif
    /* An unset NFM width keeps the historical filter rule and WIDE fallback: no definite channel, no check. */
    opts.analog_am_bandwidth_hz = 6000;
    opts.analog_demod = DSD_ANALOG_DEMOD_FM;
    opts.analog_nfm_bandwidth_hz = 0;
    rc |= scan_quiet_decoder_classes(&opts, &kind, &width) != 0U || width != 0U;
    opts.analog_nfm_bandwidth_hz = 12500;
#ifdef USE_RADIO
    rc |= scan_quiet_analog_width_hz(DSD_ANALOG_DEMOD_FM, 0) != 0U
          || scan_quiet_analog_width_hz(DSD_ANALOG_DEMOD_AM, 0) != 6000U
          || scan_quiet_analog_width_hz(DSD_ANALOG_DEMOD_FM, 16000) != 16000U
          || scan_quiet_analog_width_hz(DSD_ANALOG_DEMOD_AM, 10000) != 10000U;
#else
    rc |= scan_quiet_analog_width_hz(DSD_ANALOG_DEMOD_AM, 0) != 0U;
#endif
    opts.monitor_input_audio = 0;
    opts.frame_provoice = 1; /* Auto's set holds ProVoice and X2-TDMA: no check */
    rc |= scan_quiet_decoder_classes(&opts, NULL, NULL) != 0U;
    opts.frame_provoice = 0;
    opts.frame_x2tdma = 1;
    rc |= scan_quiet_decoder_classes(&opts, NULL, NULL) != 0U;
    opts.monitor_input_audio = 1; /* mixed, but holding an unsourced mode */
    rc |= scan_quiet_decoder_classes(&opts, NULL, NULL) != 0U;
    DSD_MEMSET(&opts, 0, sizeof opts);
    opts.analog_nfm_bandwidth_hz = 12500;
    opts.analog_only = 1;
    rc |= scan_quiet_decoder_classes(&opts, &kind, &width) != 4U || kind != DSD_ANALOG_DEMOD_FM || width != 12500U;
    if (rc) {
        DSD_FPRINTF(stderr, "FAIL #834 scan quiet: notice or classes\n");
    }
    return rc;
}

#ifndef USE_RADIO
/* A radio-off build compiles the check as a no-op service: nothing is published, the hunt is never handed back. */
static int
test_scan_quiet_radio_off_is_a_no_op(void) {
    static dsd_opts opts;
    static dsd_state state;
    DSD_MEMSET(&opts, 0, sizeof opts);
    opts.scan_skip_silent = 1;
    opts.audio_in_type = AUDIO_IN_RTL;
    dsd_engine_scan_landing_note_target(&state, 0, 1U, 452000000U, 0U);
    scan_quiet_eligibility e;
    DSD_MEMSET(&e, 0, sizeof e);
    e.key.owner = SCAN_QUIET_OWNER_TRUNK;
    e.key.epoch = dsd_engine_scan_landing_epoch(&state);
    e.key.session = 1U;
    e.eligible = 1;
    e.classes = 1U;
    e.frequency_hz = 452000000U;
    scan_quiet_publish_eligibility(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e);
    const int rc = scan_quiet_session_supported(&opts) != 0 || scan_quiet_wants_eligibility(&opts, &state, 1) != 0
                   || scan_quiet_phase_get(&state) != SCAN_QUIET_SUSPENDED
                   || dsd_engine_scan_quiet_service(&opts, &state) != 0
                   || scan_quiet_apply(&opts, &state, SCAN_QUIET_OWNER_TRUNK, &e) != 0;
    dsd_state_ext_free_all(&state);
    if (rc) {
        DSD_FPRINTF(stderr, "FAIL #834 scan quiet: the radio-off service is not a no-op\n");
    }
    return rc;
}
#endif

static int
test_scan_quiet_all(void) {
    int rc = test_scan_quiet_notice_and_classes();
#if defined(USE_RADIO) && defined(DSD_NEO_TEST_RTL_WRAP)
    rc |= run_with_default_tune_hook(test_scan_quiet_measures_a_landed_target_once);
    rc |= run_with_default_tune_hook(test_scan_quiet_waits_for_the_landed_capture);
    rc |= run_with_default_tune_hook(test_scan_quiet_unsupported_capture_is_done);
    rc |= run_with_default_tune_hook(test_scan_quiet_request_deadline_and_retries);
    rc |= run_with_default_tune_hook(test_scan_quiet_ready_rechecks_capture_generation_and_age);
    rc |= run_with_default_tune_hook(test_scan_quiet_activity_since_the_request_ends_the_check);
    rc |= run_with_default_tune_hook(test_scan_quiet_revisions_suspend_the_check);
    rc |= run_with_default_tune_hook(test_scan_quiet_mutation_sites_move_the_counters);
    rc |= run_with_default_tune_hook(test_scan_quiet_landing_records_the_tune);
    rc |= run_with_default_tune_hook(test_scan_quiet_adopts_a_park_measured_in_flight);
    rc |= run_with_default_tune_hook(test_scan_quiet_suspended_visit_requests_nothing);
    rc |= test_scan_quiet_hook_off_is_one_load();
    rc |= run_with_default_tune_hook(test_scan_quiet_decline_ends_it_unless_the_guard_was_lost);
    rc |= run_with_default_tune_hook(test_scan_quiet_apply_checks_the_facts_in_force);
    rc |= run_with_default_tune_hook(test_scan_quiet_mixed_set_judges_the_analog_class);
    rc |= run_with_default_tune_hook(test_scan_quiet_adopted_park_is_bounded_from_its_landing);
    rc |= run_with_default_tune_hook(test_scan_quiet_more_mutation_sites_decline_a_ready_result);
    rc |= run_with_default_tune_hook(test_scan_quiet_trunk_goto_and_resume_sites);
#endif
#ifndef USE_RADIO
    rc |= test_scan_quiet_radio_off_is_a_no_op();
#endif
    return rc;
}

